function bookErrorKey(e) {
  const m = String((e && e.message) || "");
  if (m.includes("Zapys zakryto")) return "bkClosed";
  if (m.includes("Nemaye vilnykh")) return "bkNoSpots";
  if (m.includes("Vkazhit")) return "bkFillFields";
  if (m.includes("Nepravylna")) return "bkBadCount";
  if (m.includes("Potriben kontakt")) return "bkNeedContact";
  if (m.includes("Kontakt ne zbihaetsya")) return "bkWrongContact";
  if (m.includes("Zapys ne znaideno")) return "bkNotFound";
  return "bkFailed";
}

// ── Завантаження фото в Supabase Storage ───────────────────────────────
// Фото стискається до розумного розміру прямо на пристрої (щоб швидко
// вантажилось і не з'їдало квоту), заливається в публічний bucket "photos",
// а в поїздку записується постійне публічне посилання.
function downscaleImage(file, maxW, quality) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      const scale = Math.min(1, maxW / img.width);
      const w = Math.round(img.width * scale), h = Math.round(img.height * scale);
      const cv = document.createElement("canvas");
      cv.width = w; cv.height = h;
      cv.getContext("2d").drawImage(img, 0, 0, w, h);
      cv.toBlob((b) => (b ? resolve(b) : reject(new Error("Не вдалося обробити зображення"))), "image/jpeg", quality);
    };
    img.onerror = () => reject(new Error("Файл не схожий на зображення"));
    img.src = URL.createObjectURL(file);
  });
}
async function sbUploadImage(file) {
  if (!sbConfigured()) throw new Error("База даних не підключена");
  const name = `trip-${Date.now()}-${Math.random().toString(36).slice(2, 8)}.jpg`;
  const blob = await downscaleImage(file, 1600, 0.85);
  const r = await fetch(`${SUPABASE_URL}/storage/v1/object/photos/${name}`, {
    method: "POST",
    headers: { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${SUPABASE_ANON_KEY}`, "Content-Type": "image/jpeg" },
    body: blob,
  });
  if (!r.ok) throw new Error(await r.text());
  return `${SUPABASE_URL}/storage/v1/object/public/photos/${name}`;
}

// ── Розбір координат із буфера обміну ──────────────────────────────────
// Приймає що завгодно з Google Maps: "47.4920, 11.0975", посилання виду
// ...@47.4920,11.0975,15z, або текст із градусами — і дістає два числа.
// Пошук місця за адресою (Nominatim / OpenStreetMap — безкоштовно, без ключа).
async function geocodeAddress(q) {
  const url = `https://nominatim.openstreetmap.org/search?format=json&limit=5&addressdetails=0&accept-language=uk&q=${encodeURIComponent(q)}`;
  const r = await fetch(url, { headers: { Accept: "application/json" } });
  if (!r.ok) throw new Error("geocode " + r.status);
  const j = await r.json();
  return (j || []).map((x) => ({ label: x.display_name, lat: parseFloat(x.lat), lng: parseFloat(x.lon) }));
}

function parseCoordsInput(str) {
  if (!str) return null;
  const m = String(str).match(/-?\d{1,3}\.\d+/g);
  if (!m || m.length < 2) return null;
  const lat = parseFloat(m[0]), lng = parseFloat(m[1]);
  if (isNaN(lat) || isNaN(lng) || Math.abs(lat) > 90 || Math.abs(lng) > 180) return null;
  return { lat, lng };
}
