// Current language is held in a module-level ref updated by the app, so the
// translate helper t() can be called from anywhere without prop drilling.
let CURRENT_LANG = "uk";
const t = (key) => {
  const entry = T[key];
  if (!entry) return key;
  return entry[CURRENT_LANG] ?? entry.uk ?? key;
};

// ── Trip content translation ───────────────────────────────────────────
// Trip content (titles, descriptions, routes…) can be stored either as a
// plain string (one language) or as a {uk,en,ru} object (pre-translated).
// tc() picks the current language with graceful fallback so nothing renders
// blank.
// DeepL сприймає коротку фразу як заголовок і повертає її з Великих
// Літер: «Одяг по погоді» → «Clothing for the Weather». Знімаємо зайві
// великі літери, але тільки там, де це безпечно:
//   • лише короткі рядки — саме на них трапляється така поведінка;
//   • німецьку НЕ чіпаємо: там усі іменники пишуться з великої за
//     правилами мови, і «Kleidung nach dem Wetter» — правильно;
//   • якщо в українському оригіналі велика літера є десь, крім першого
//     знака, або є латиниця — там власна назва («Deutschland Ticket»,
//     «München Hbf»), і переклад лишаємо недоторканим;
//   • слова з цифрами та написані повністю великими («ICE», «RB55»)
//     не чіпаємо в жодному разі.
function fixTitleCase(text, src, lang) {
  if (lang === "uk" || lang === "de") return text;
  if (!text || !src || text.length > 44) return text;
  if (/[A-Za-z]/.test(src)) return text;
  if (/[A-ZА-ЯЁЄІЇҐ]/.test(src.slice(1))) return text;
  return text.replace(/\S+/g, (w, offset) => {
    if (offset === 0) return w;
    if (/\d/.test(w) || w === w.toUpperCase()) return w;
    return w.charAt(0).toLowerCase() + w.slice(1);
  });
}

const tc = (val) => {
  if (val == null) return "";
  if (typeof val === "string") return val;
  const out = val[CURRENT_LANG] || val.uk || val.en || val.ru || "";
  return fixTitleCase(out, val.uk || "", CURRENT_LANG);
};

// ── Автопереклад вмісту (DeepL через /api/translate на Vercel) ────────
// Викликається при збереженні поїздки: всі текстові поля перекладаються
// на EN і RU та зберігаються як {uk,en,ru}. Якщо ключ DeepL не задано або
// сервер недоступний — вміст лишається українським (tc() це переживе).
const ukOf = (v) => (v == null ? "" : (typeof v === "string" ? v : (v.uk || v.en || v.ru || "")));
const TRANSLATABLE = (trip) => {
  const acc = [];
  const push = (get, set) => acc.push({ get, set });
  push(() => trip.title, (v) => (trip.title = v));
  push(() => trip.subtitle, (v) => (trip.subtitle = v));
  push(() => trip.about, (v) => (trip.about = v));
  push(() => trip.difficultyNote, (v) => (trip.difficultyNote = v));
  // Потрібне для випадків на кшталт «цілий день» — числові варіанти
  // збирає durationText() сам, без перекладача.
  push(() => trip.durationHrs, (v) => (trip.durationHrs = v));
  push(() => trip.meetingPoint, (v) => (trip.meetingPoint = v));
  push(() => trip.returnTime, (v) => (trip.returnTime = v));
  (trip.route || []).forEach((st) => { push(() => st.name, (v) => (st.name = v)); push(() => st.note, (v) => (st.note = v)); push(() => st.info, (v) => (st.info = v)); });
  (trip.bonus || []).forEach((b) => { push(() => b.name, (v) => (b.name = v)); push(() => b.note, (v) => (b.note = v)); });
  (trip.cafes || []).forEach((c) => { push(() => c.note, (v) => (c.note = v)); push(() => c.tag, (v) => (c.tag = v)); });
  (trip.packing || []).forEach((_, i) => push(() => trip.packing[i], (v) => (trip.packing[i] = v)));
  const cl = (trip.contacts && trip.contacts.length ? trip.contacts : (trip.contact ? [trip.contact] : []));
  cl.forEach((c) => push(() => c.role, (v) => (c.role = v)));
  (trip.sections || []).forEach((sec) => push(() => sec.title, (v) => (sec.title = v)));
  return acc;
};
// ── Переклад тексту: три джерела поспіль ──────────────────────────────
// 1) DeepL через власний сервер (якщо налаштований — найкраща якість)
// 2) Google Translate з браузера (без ключа, працює завжди)
// 3) MyMemory (останній запас)
// Якщо всі три не спрацювали для рядка — лишається оригінал.

async function gtxOne(text, target) {
  const url = `https://translate.googleapis.com/translate_a/single?client=gtx&sl=uk&tl=${target.toLowerCase()}&dt=t&q=${encodeURIComponent(text)}`;
  const r = await fetch(url);
  if (!r.ok) throw new Error("gtx " + r.status);
  const j = await r.json();
  const out = (j && j[0] ? j[0].map((x) => (x && x[0]) || "").join("") : "").trim();
  if (!out) throw new Error("gtx empty");
  return out;
}

async function mmOne(text, target) {
  const url = `https://api.mymemory.translated.net/get?q=${encodeURIComponent(text)}&langpair=uk|${target.toLowerCase()}`;
  const r = await fetch(url);
  if (!r.ok) throw new Error("mm " + r.status);
  const j = await r.json();
  const out = j && j.responseData && j.responseData.translatedText;
  if (!out || /^MYMEMORY WARNING|QUERY LENGTH LIMIT/i.test(out)) throw new Error("mm limit");
  return out;
}

async function deeplBatch(texts, target) {
  const r = await fetch("/api/translate", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ texts, target }),
  });
  if (!r.ok) throw new Error("translate http " + r.status);
  const j = await r.json();
  if (!j || !Array.isArray(j.translations) || j.translations.length !== texts.length) throw new Error("translate disabled");
  return j.translations;
}

// Перекладає масив рядків, повертає масив тієї ж довжини.
async function translateBatch(texts, target) {
  try {
    const d = await deeplBatch(texts, target);
    if (d && d.length === texts.length && d.every((x) => x)) return d;
  } catch { /* пробуємо наступне джерело */ }

  // По 4 паралельно — помітно швидше, ніж по одному, і без перевантаження.
  const out = new Array(texts.length).fill(null);
  const CHUNK = 4;
  for (let i = 0; i < texts.length; i += CHUNK) {
    const slice = texts.slice(i, i + CHUNK);
    const res = await Promise.all(slice.map((x) => gtxOne(x, target).catch(() => null)));
    res.forEach((v, k) => { out[i + k] = v; });
  }
  for (let i = 0; i < texts.length; i++) {
    if (out[i] == null) {
      try { out[i] = await mmOne(texts[i], target); } catch { out[i] = null; }
    }
  }
  return out.map((v, i) => (v == null ? texts[i] : v));
}

async function translateTripContent(trip0) {
  const trip = JSON.parse(JSON.stringify(trip0));
  // Ручні виправлення, збережені редактором перекладів. Вони мають
  // перевагу над машинним перекладом — інакше кожне збереження поїздки
  // повертало б «Штурм Бисмарка» замість виправленої «Башни Бисмарка».
  // Ручні виправлення шукаємо за САМИМ українським текстом, а не за
  // номером поля в списку. Прив'язка до номера була помилкою: варто було
  // додати чи прибрати один пункт спорядження — і всі наступні поля
  // отримували чужий переклад. Саме через це назви розділів «поїхали»
  // на дві позиції: «Кафе/їжа» стало заголовком контактів тощо.
  const manual = (trip.manualTr && typeof trip.manualTr === "object") ? trip.manualTr : {};
  delete trip.__tr;      // залишок старого формату
  delete trip.__trShow;  // службове поле редактора
  const acc = TRANSLATABLE(trip);
  const idx = []; const texts = [];
  acc.forEach((a, i) => {
    const v = ukOf(a.get()).trim();
    if (v === "") return;
    // Рядок без жодної кирилиці — це власна назва латиницею: «Würzburg»,
    // «Starnberger See», «Bismarcksturm», «Andreas-Stüberl». Перекладачеві
    // його віддавати не можна: він транслітерує назву в «Вюрцбург» або й
    // зовсім вигадує сенс («Bismarcksturm» → «Штурм Бисмарка»). Такі рядки
    // лишаємо як є в усіх мовах — назва вокзалу чи гори має бути тією
    // самою, що на табло й на вказівнику.
    if (!/[А-Яа-яЁёЄєІіЇїҐґ]/.test(v)) { acc[i].set({ uk: v, en: v, ru: v }); return; }
    idx.push(i); texts.push(v);
  });
  if (texts.length === 0) return trip;
  const [en, ru] = await Promise.all([translateBatch(texts, "EN"), translateBatch(texts, "RU")]);
  let changed = 0;
  idx.forEach((ai, k) => {
    const m = manual[texts[k]] || {};
    const e = (m.en && m.en.trim() !== "") ? m.en : (en[k] || texts[k]);
    const r = (m.ru && m.ru.trim() !== "") ? m.ru : (ru[k] || texts[k]);
    if (e !== texts[k] || r !== texts[k]) changed++;
    acc[ai].set({ uk: texts[k], en: e, ru: r });
  });
  // Прибираємо правки до текстів, яких у поїздці вже немає, щоб список
  // не ріс без потреби.
  const alive = new Set(texts);
  const kept = {};
  Object.keys(manual).forEach((k) => { if (alive.has(k)) kept[k] = manual[k]; });
  trip.manualTr = kept;
  trip.__translated = changed;
  return trip;
}
// Готує поїздку до редагування: всі багатомовні поля → прості укр. рядки,
// інакше поля вводу отримали б об'єкт замість тексту. Самі переклади при
// цьому не викидаємо, а відкладаємо в окремий список __tr, вирівняний за
// тим самим обходом TRANSLATABLE. Без цього кроку будь-яка правка поїздки
// стирала б усі ручні виправлення перекладу.
function toEditable(trip0) {
  const trip = JSON.parse(JSON.stringify(trip0));
  const acc = TRANSLATABLE(trip);
  // Чинні переклади складаємо у словник «український текст → переклад».
  // Він потрібен лише редакторові, щоб показати, що зараз бачать
  // учасники; у базу не потрапляє. Самі ручні правки живуть окремо,
  // у полі manualTr, і зберігаються разом із поїздкою.
  const show = {};
  acc.forEach((a) => {
    const v = a.get();
    const uk = ukOf(v).trim();
    if (uk !== "" && v && typeof v === "object") show[uk] = { en: v.en || "", ru: v.ru || "" };
  });
  trip.__trShow = show;
  delete trip.__tr;
  acc.forEach((a) => a.set(ukOf(a.get())));
  return trip;
}

