  d === "Легкий" ? C.green : d === "Середній" ? "#7d8a4a" : C.rasp;

// ── Multi-leg train journey ─────────────────────────────────────────────
// Renders a chain of train segments with transfer markers between them.
// legs: [{ from, fromTime, platform, train, to, toTime }]. Backward
// compatible: callers fall back to the old single from/to fields when a trip
// has no legs array.
// ── Кілька окремих маршрутів до тієї самої цілі ──────────────────────
// Поїздка може мати кілька незалежних відправлень: із Landsberg, із
// Augsburg, із Мюнхена. Кожне — власний ланцюжок поїздів із пересадками.
// Старі поїздки зберігали ОДИН маршрут у полі legs; читаємо обидва
// формати, щоб нічого зі збереженого не загубилось.
function tripJourneys(trip) {
  const js = trip && Array.isArray(trip.journeys) ? trip.journeys : null;
  if (js && js.length > 0) return js.map((j) => ({ legs: Array.isArray(j.legs) ? j.legs : [] }));
  const legs = trip && Array.isArray(trip.legs) ? trip.legs : [];
  return legs.length > 0 ? [{ legs }] : [];
}

// Порожня заготовка поїзда — це ще не поїзд. Без цієї перевірки в шапці
// картки замість кінцевої станції показувалась риска («07:52 → —»),
// бо в кінці списку висів недозаповнений блок.
const legFilled = (l) => l && [l.from, l.fromTime, l.train, l.to, l.toTime]
  .some((v) => String(v == null ? "" : v).trim() !== "");
const filledLegs = (j) => ((j && j.legs) || []).filter(legFilled);
const blankLeg = () => ({ from: "", fromTime: "", platform: "", train: "", to: "", toTime: "", toPlatform: "", transfer: "" });

// Додане, але не заповнене місце — це ще не місце. Без цієї перевірки
// в розділі «Маршрут» з'являвся заголовок «Додатково поруч» і під ним
// порожня біла картка з самою іконкою.
const bonusFilled = (b) => {
  if (!b) return false;
  const txt = (v) => String(tc(v) || "").trim();
  const hasGeo = !isNaN(parseFloat(b.lat)) && !isNaN(parseFloat(b.lng));
  return txt(b.name) !== "" || txt(b.note) !== "" || hasGeo;
};

// Скільки хвилин між двома часами у форматі «10:56». Потрібно, щоб
// показати тривалість пересадки, коли організатор не вписав її вручну.
function minutesBetween(a, b) {
  const pa = String(a || "").match(/(\d{1,2}):(\d{2})/);
  const pb = String(b || "").match(/(\d{1,2}):(\d{2})/);
  if (!pa || !pb) return null;
  let d = (Number(pb[1]) * 60 + Number(pb[2])) - (Number(pa[1]) * 60 + Number(pa[2]));
  if (d < 0) d += 24 * 60;
  return d;
}

// Тривалість організатор пише вільним текстом: «4 год», «5–6 год».
// Показувати її як є не можна — в англійській лишалось «4 год» поруч із
// «11.86 km». Тому дістаємо число або діапазон і додаємо одиницю мовою
// інтерфейсу. Якщо там не число, а слова («цілий день»), покладаємось на
// звичайний переклад тексту.
function durationText(v) {
  const raw = String(tc(v) || "").trim();
  if (raw === "") return "";
  // Число шукаємо будь-де в рядку, а не тільки на початку. Раніше стояла
  // прив'язка до початку, і варіанти на кшталт «~4 год», «прибл. 4 год»
  // чи «близько 5 годин» не розпізнавались — тоді показувався сирий
  // текст організатора, який лишався українським у всіх мовах.
  const m = raw.match(/(\d+(?:[.,]\d+)?)\s*(?:[–—-]\s*(\d+(?:[.,]\d+)?))?/);
  if (!m) return raw;
  const range = m[2] ? `${m[1]}–${m[2]}` : m[1];
  return `${range} ${t("unitH")}`;
}

// Позначка середнього чека в кафе. Це вільний текст організатора, який
// автопереклад щоразу вивертав по-різному — в одному списку виходило
// «Average check: 25€», «€12 average check», «Average check: 15€».
// Якщо в українському тексті впізнається сума й слова «середній чек»,
// збираємо підпис із ціни та одного перекладеного слова: вигляд стає
// однаковим для всіх кафе й усіх мов.
function cafeTag(tag) {
  const src = String(ukOf(tag) || "").trim();
  if (src === "") return "";
  const m = src.match(/(\d+(?:[.,]\d+)?)\s*(?:€|eur|євро|евро)?/i);
  if (m && /середн\S*\s+чек/i.test(src)) return `${m[1]}€ ${t("avgCheck")}`;
  return tc(tag);
}

// Тривалість у людському вигляді: «58 хв», «2 год», «2 год 18 хв».
function formatDuration(min) {
  if (min == null || isNaN(min) || min < 0) return "";
  const h = Math.floor(min / 60), m = min % 60;
  if (h === 0) return `${m} ${t("legMin")}`;
  if (m === 0) return `${h} ${t("legHour")}`;
  return `${h} ${t("legHour")} ${m} ${t("legMin")}`;
}

// Один рядок ланцюжка: точка на лінії, час, станція, платформа.
function LegStop({ time, name, platform, last }) {
  return (
    <div style={{ display: "flex", gap: 11, alignItems: "flex-start" }}>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", width: 14, flexShrink: 0 }}>
        <span style={{ width: 11, height: 11, borderRadius: "50%", border: `2.5px solid ${C.green}`, background: "#fff", marginTop: 4 }} />
        {!last && <span style={{ width: 2, flex: 1, minHeight: 26, background: C.greenLine }} />}
      </div>
      <div style={{ minWidth: 50, flexShrink: 0 }}>
        <div style={{ fontSize: 16, fontWeight: 800, color: C.ink, lineHeight: 1.2 }}>{time || "—"}</div>
      </div>
      <div style={{ flex: 1, minWidth: 0, paddingBottom: last ? 0 : 12 }}>
        <div style={{ fontSize: 13.5, fontWeight: 700, color: C.ink, lineHeight: 1.3 }}>{name || "—"}</div>
        {platform && platform.trim() !== "" && (
          <div style={{ fontSize: 11.5, color: C.rasp, fontWeight: 700, marginTop: 2 }}>{t("jpTrack")} {platform}</div>
        )}
      </div>
    </div>
  );
}

// ── Ланцюжок поїздів із пересадками ─────────────────────────────────
// Згорнута картка показує головне: коли й звідки виїжджати, коли й куди
// приїде, якими поїздами. Натиск розкриває повний ланцюжок, де кожна
// пересадка стоїть МІЖ двома поїздами — щоб було видно, на якій станції
// і скільки часу на неї є.
function TrainLegs({ legs: rawLegs }) {
  const [open, setOpen] = useState(false);
  const legs = (rawLegs || []).filter(legFilled);
  if (legs.length === 0) return null;
  const first = legs[0] || {};
  const last = legs[legs.length - 1] || {};
  const trains = legs.map((l) => l.train).filter((x) => x && x.trim() !== "");
  // Загальний час у дорозі — від відправлення першого поїзда до прибуття
  // останнього. Пересадки входять сюди самі собою, бо це просто різниця
  // між двома часами, а не сума відрізків.
  const totalMin = minutesBetween(first.fromTime, last.toTime);
  const totalText = formatDuration(totalMin);

  return (
    <div style={{ border: `1px solid ${C.greenLine}`, borderRadius: 14, overflow: "hidden", background: "#fff" }}>
      <button onClick={() => setOpen(!open)}
        style={{ width: "100%", display: "block", textAlign: "left", background: "none", border: "none", padding: "13px 14px", cursor: "pointer", fontFamily: "inherit" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ display: "flex", alignItems: "baseline", gap: 8, flexWrap: "wrap" }}>
              <span style={{ fontSize: 19, fontWeight: 800, color: C.ink }}>{first.fromTime || "—"}</span>
              <span style={{ fontSize: 13, color: C.faint }}>→</span>
              <span style={{ fontSize: 19, fontWeight: 800, color: C.ink }}>{last.toTime || "—"}</span>
            </div>
            <div style={{ fontSize: 12.5, color: C.inkSoft, marginTop: 3, lineHeight: 1.35 }}>
              {first.from || "—"} → {last.to || "—"}
            </div>
          </div>
          <span style={{ color: C.green, flexShrink: 0, transform: open ? "rotate(90deg)" : "none", transition: "transform .15s" }}>
            <ChevronRight size={19} />
          </span>
        </div>
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 9 }}>
          {trains.map((tr, i) => (
            <span key={i} style={{ fontSize: 11.5, fontWeight: 800, color: C.yellowInk, background: C.yellow, padding: "4px 11px", borderRadius: 20 }}>{tr}</span>
          ))}
          {legs.length > 1 && (
            <span style={{ fontSize: 11.5, fontWeight: 700, color: C.yellowInk, background: C.yellowSoft, padding: "4px 11px", borderRadius: 20, display: "flex", alignItems: "center", gap: 5 }}>
              <Footprints size={13} /> {legs.length - 1}
            </span>
          )}
          {totalText && (
            <span style={{ fontSize: 11.5, fontWeight: 700, color: C.greenDark, background: C.greenSoft, padding: "4px 11px", borderRadius: 20, display: "flex", alignItems: "center", gap: 5 }}>
              <Clock size={13} /> {totalText}
            </span>
          )}
        </div>
      </button>

      {open && (
        <div style={{ padding: "4px 14px 14px", borderTop: `1px solid ${C.line}` }}>
          {legs.map((leg, i) => {
            const prev = i > 0 ? legs[i - 1] : null;
            // Час пересадки: вписаний організатором має перевагу, інакше
            // рахуємо з часів прибуття попереднього і відправлення цього.
            // Час пересадки. Якщо організатор вписав саме число хвилин
            // («14» чи «14 хв»), показуємо його мовою інтерфейсу — раніше
            // текст «14 хв» лишався українським і в англійській, і в
            // німецькій версії. Довільний текст лишаємо як є.
            const manual = String(leg.transfer || "").trim();
            const onlyMin = manual.match(/^(\d{1,3})\s*(хв|хвилин\w*|мин|минут\w*|min|mins|minutes|minuten)?\.?$/i);
            const autoMin = prev ? minutesBetween(prev.toTime, leg.fromTime) : null;
            const waitMin = onlyMin ? parseInt(onlyMin[1], 10) : (manual === "" ? autoMin : null);
            const wait = waitMin != null ? formatDuration(waitMin) : manual;
            return (
              <div key={i}>
                {prev && (
                  <div style={{ display: "flex", gap: 11, alignItems: "stretch" }}>
                    <div style={{ width: 14, display: "flex", justifyContent: "center", flexShrink: 0 }}>
                      <span style={{ width: 2, background: C.yellow }} />
                    </div>
                    <div style={{ flex: 1, background: C.yellowSoft, borderRadius: 10, padding: "8px 11px", margin: "2px 0 12px", display: "flex", alignItems: "center", gap: 8 }}>
                      <Footprints size={15} style={{ color: C.yellowInk, flexShrink: 0 }} />
                      <span style={{ fontSize: 12.5, fontWeight: 700, color: C.yellowInk }}>
                        {t("legTransfer")}{wait ? ` · ${wait}` : ""}
                      </span>
                    </div>
                  </div>
                )}
                <LegStop time={leg.fromTime} name={leg.from} platform={leg.platform} />
                {leg.train && leg.train.trim() !== "" && (
                  <div style={{ display: "flex", gap: 11, alignItems: "center", margin: "-6px 0 6px" }}>
                    <div style={{ width: 14, display: "flex", justifyContent: "center", flexShrink: 0 }}>
                      <span style={{ width: 2, height: 26, background: C.greenLine }} />
                    </div>
                    <span style={{ minWidth: 50, flexShrink: 0 }} />
                    <span style={{ fontSize: 11.5, fontWeight: 800, color: C.yellowInk, background: C.yellow, padding: "4px 11px", borderRadius: 20 }}>{leg.train}</span>
                  </div>
                )}
                <LegStop time={leg.toTime} name={leg.to} platform={leg.toPlatform} last={i === legs.length - 1} />
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

// Посилання на точку в Google Maps. Форма «/maps/place/<коорд>/@<коорд>»
// ставить шпильку РІВНО в задані координати. Попередня форма
// «/maps/search/?api=1&query=…» була саме ПОШУКОМ: Google брав координати
// як запит і підставляв найближчий відомий йому об'єкт. У місті різниця
// непомітна, а в горах, де адрес майже немає, точка з'їжджала на сотні
// метрів — тому в застосунку місце показувалось правильно, а в Google
// Maps ні. Координати округлюємо до шести знаків — це близько 10 см,
// точніше не має сенсу.
function gmapsUrl(lat, lng) {
  const a = Number(lat), b = Number(lng);
  if (isNaN(a) || isNaN(b)) return "https://www.google.com/maps";
  const c = `${a.toFixed(6)},${b.toFixed(6)}`;
  return `https://www.google.com/maps/place/${c}/@${c},17z`;
}

// ── Карта точки на OpenStreetMap ────────────────────────────────────
// Керування масштабом власними кнопками, а не тими, що малює сам OSM.
// Причина: вбудована карта лишається несприйнятливою до дотиків
// (pointerEvents: none), інакше палець на карті тягав би її замість
// того, щоб гортати сторінку. Тому «+» і «−» просто перебудовують
// адресу карти з іншим охопленням — гортання сторінки не страждає.
const MAP_SPAN_MIN = 0.0006;   // найближче
const MAP_SPAN_MAX = 0.25;     // найдалі
const MAP_SPAN_DEFAULT = 0.008;
function MeetingMap({ lat, lng, accent }) {
  // Жовта шпилька для бонусних точок, червона для звичайних — щоб на
  // карті було одразу видно, дивишся ти на точку маршруту чи на
  // необов'язкове місце поруч.
  const pinFill = accent === "bonus" ? "#f2c200" : "#e8332f";
  const pinDot = accent === "bonus" ? "#4a3f00" : "#fff";
  const [span, setSpan] = useState(MAP_SPAN_DEFAULT);
  const gmaps = gmapsUrl(lat, lng);
  const bbox = `${lng - span},${lat - span},${lng + span},${lat + span}`;
  const mapSrc = `https://www.openstreetmap.org/export/embed.html?bbox=${bbox}&layer=mapnik`;
  const canIn = span > MAP_SPAN_MIN * 1.01;
  const canOut = span < MAP_SPAN_MAX * 0.99;
  const zoom = (factor) => setSpan((v) => Math.min(MAP_SPAN_MAX, Math.max(MAP_SPAN_MIN, v * factor)));
  const zoomBtn = (label, onClick, enabled, radius) => (
    <button
      onClick={onClick}
      disabled={!enabled}
      aria-label={label === "+" ? "Наблизити" : "Віддалити"}
      style={{
        width: 34, height: 34, border: "none", background: "#fff", color: enabled ? C.green : C.faint,
        fontSize: 20, fontWeight: 700, lineHeight: 1, cursor: enabled ? "pointer" : "default",
        fontFamily: "inherit", display: "flex", alignItems: "center", justifyContent: "center",
        borderRadius: radius, padding: 0,
      }}>{label}</button>
  );
  return (
    <div style={{ position: "relative", borderRadius: 16, overflow: "hidden", border: `1px solid ${C.line}`, aspectRatio: "16/10", background: C.greenSoft }}>
      <iframe
        title="meeting-map"
        src={mapSrc}
        style={{ width: "100%", height: "calc(100% + 26px)", border: "none", display: "block", pointerEvents: "none" }}
        loading="lazy"
      />
      {/* Ліцензія OSM вимагає атрибуції — лишаємо її, але компактно
          й у стилі застосунку, замість службової смуги від iframe. */}
      <span style={{ position: "absolute", right: 6, bottom: 4, fontSize: 8.5, color: "rgba(0,0,0,0.42)", background: "rgba(255,255,255,0.72)", padding: "1px 5px", borderRadius: 6 }}>© OpenStreetMap</span>
      {/* Червона шпилька в центрі */}
      <div style={{ position: "absolute", top: "50%", left: "50%", transform: "translate(-50%, -100%)", pointerEvents: "none" }}>
        <svg width="34" height="44" viewBox="0 0 34 44" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ filter: "drop-shadow(0 2px 4px rgba(0,0,0,0.35))" }}>
          <path d="M17 0C7.6 0 0 7.6 0 17c0 12 17 27 17 27s17-15 17-27C34 7.6 26.4 0 17 0z" fill={pinFill}/>
          <circle cx="17" cy="17" r="6.5" fill={pinDot}/>
        </svg>
      </div>
      {/* Масштаб */}
      <div style={{ position: "absolute", right: 10, top: 10, display: "flex", flexDirection: "column", borderRadius: 10, overflow: "hidden", boxShadow: "0 1px 5px rgba(0,0,0,0.22)" }}>
        {zoomBtn("+", () => zoom(0.5), canIn, "10px 10px 0 0")}
        <span style={{ height: 1, background: C.line }} />
        {zoomBtn("\u2212", () => zoom(2), canOut, "0 0 10px 10px")}
      </div>
      {/* Перехід у Google Maps — окремим значком, а не всією картою:
          інакше натиск на «+» відкривав би карти замість наближення. */}
      <a href={gmaps} target="_blank" rel="noreferrer"
        style={{ position: "absolute", right: 10, bottom: 10, background: "#fff", borderRadius: 10, padding: "7px 11px", fontSize: 12, fontWeight: 700, color: C.green, display: "flex", alignItems: "center", gap: 5, boxShadow: "0 1px 5px rgba(0,0,0,0.18)", textDecoration: "none" }}>
        <Navigation size={14} /> Google Maps
      </a>
    </div>
  );
}

// Кнопка на повний розклад Deutsche Bahn. Замінила вбудований пошук
// поїздів: розклад тепер вводить організатор, а хто хоче інші варіанти —
// відкриває сайт перевізника, де список завжди повний і актуальний.
function DbScheduleLink({ trip }) {
  const js = tripJourneys(trip).map(filledLegs).filter((l) => l.length > 0);
  const legs = js.length > 0 ? js[0] : null;
  const from = (legs ? legs[0].from : trip.from && trip.from.name) || "";
  const to = (legs ? legs[legs.length - 1].to : trip.to && trip.to.name) || "";
  if (from.trim() === "" || to.trim() === "") return null;
  const enc = (v) => encodeURIComponent(v.trim().replace(/\s+/g, "+")).replace(/%2B/g, "+");
  const url = `https://mobile.bahn.de/bin/query.exe/dox?S=${enc(from)}&Z=${enc(to)}&timeSel=depart&start=1`;
  return (
    <a href={url} target="_blank" rel="noreferrer"
      style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8, marginTop: 8, background: C.green, color: "#fff", borderRadius: 12, padding: "13px", fontSize: 13.5, fontWeight: 700, textDecoration: "none" }}>
      <Train size={16} /> {t("jpButton")}
    </a>
  );
}

// ── Сповіщення: підписка учасника ────────────────────────────────────
// Кнопка живе на головному екрані. Свідомо не просимо дозвіл самі при
// відкритті: непроханий системний запит люди майже завжди відхиляють,
// а відхилений дозвіл у браузері вдруге не попросиш — його доводиться
// вмикати руками в налаштуваннях. Тому спершу пояснюємо, навіщо.
function PushToggle() {
  const [state, setState] = useState("idle"); // idle | on | busy | denied | unsupported | needInstall
  const [err, setErr] = useState("");

  useEffect(() => {
    if (!pushSupported()) { setState("unsupported"); return; }
    // На iPhone дозвіл доступний лише встановленому застосунку.
    if (isIOS() && !isStandalone()) { setState("needInstall"); return; }
    pushRegister().then(async () => {
      if (Notification.permission === "denied") { setState("denied"); return; }
      const reg = await navigator.serviceWorker.ready;
      const sub = await reg.pushManager.getSubscription();
      setState(sub ? "on" : "idle");
    }).catch(() => setState("unsupported"));
  }, []);

  const turnOn = async () => {
    setState("busy"); setErr("");
    try {
      await pushSubscribe(CURRENT_LANG);
      setState("on");
    } catch (e) {
      if (String(e.message) === "denied") { setState("denied"); }
      else { setState("idle"); setErr(t("pnFailed")); }
    }
  };
  const turnOff = async () => {
    setState("busy");
    try { await pushUnsubscribe(); } catch {}
    setState("idle");
  };

  if (state === "unsupported") return null;

  const shell = (children, border) => (
    <div style={{ display: "flex", alignItems: "center", gap: 11, margin: "18px 30px 0", background: "transparent", border: `1px solid ${border}`, borderRadius: 14, padding: "11px 13px" }}>
      {children}
    </div>
  );
  const icon = (
    <span style={{ width: 30, height: 30, borderRadius: 9, background: "rgba(255,255,255,0.12)", color: "rgba(255,255,255,0.85)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
      <Signal size={15} />
    </span>
  );
  const label = (title, note) => (
    <span style={{ flex: 1, minWidth: 0 }}>
      <span style={{ display: "block", fontSize: 13, fontWeight: 700, color: "rgba(255,255,255,0.9)" }}>{title}</span>
      <span style={{ display: "block", fontSize: 11, color: "rgba(255,255,255,0.5)", marginTop: 1, lineHeight: 1.35 }}>{note}</span>
    </span>
  );

  if (state === "needInstall") return shell(<>{icon}{label(t("pnTitle"), t("pnNeedInstall"))}</>, "rgba(255,255,255,0.18)");
  if (state === "denied") return shell(<>{icon}{label(t("pnTitle"), t("pnDenied"))}</>, "rgba(255,255,255,0.18)");

  if (state === "on") {
    return shell(<>
      {icon}
      {label(t("pnOnTitle"), t("pnOnNote"))}
      <button onClick={turnOff} style={{ border: "none", background: "none", color: "rgba(255,255,255,0.5)", fontSize: 11.5, fontWeight: 700, cursor: "pointer", flexShrink: 0, fontFamily: "inherit", textDecoration: "underline" }}>{t("pnOff")}</button>
    </>, "rgba(253,228,70,0.6)");
  }

  return shell(<>
    {icon}
    {label(t("pnTitle"), err || t("pnNote"))}
    <button onClick={turnOn} disabled={state === "busy"}
      style={{ border: `1px solid ${C.yellow}`, background: "transparent", color: C.yellow, fontSize: 11.5, fontWeight: 700, cursor: "pointer", flexShrink: 0, fontFamily: "inherit", borderRadius: 9, padding: "7px 12px" }}>
      {state === "busy" ? "…" : t("pnOn")}
    </button>
  </>, "rgba(255,255,255,0.22)");
}

// ── Trip card (list view) ──────────────────────────────────────────────
function TripCard({ trip, onClick, isAdmin, onSetStatus, onSetPostponedDate, onEdit, counts }) {
  const left = Math.max(0, (Number(trip.spots) || 0) - takenOf(trip, counts));
  return (
    <div style={{
      width: "100%", borderRadius: 20, overflow: "hidden", background: C.card,
      boxShadow: "0 2px 14px rgba(60,79,44,0.08)", marginBottom: 16,
    }}>
      <div onClick={onClick} style={{ cursor: "pointer" }}>
        <div style={{ height: 116, background: trip.heroGradient, position: "relative", padding: 16, display: "flex", flexDirection: "column", justifyContent: "space-between" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
            <span style={{
              background: "rgba(255,255,255,0.22)", backdropFilter: "blur(4px)",
              color: "#fff", fontSize: 11, fontWeight: 600, padding: "4px 10px",
              borderRadius: 20, letterSpacing: 0.3,
            }}>{dateWithWeekday(trip)}</span>
            {STATUS[trip.status]?.badge && (
              <span style={{ background: STATUS[trip.status].bg, color: STATUS[trip.status].fg, fontSize: 10, fontWeight: 700, padding: "4px 9px", borderRadius: 20, textTransform: "uppercase", letterSpacing: 0.5 }}>{trip.status === "postponed" ? postponedLabel(trip) : statusLabel(trip.status)}</span>
            )}
          </div>
          <div style={{ color: "#fff" }}>
            <div style={{ fontSize: 22, fontWeight: 800, lineHeight: 1.1, letterSpacing: -0.3 }}>{tc(trip.title)}</div>
            <div style={{ fontSize: 13, opacity: 0.92, marginTop: 2 }}>{tc(trip.subtitle)}</div>
          </div>
        </div>
        <div style={{ padding: "13px 16px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <div style={{ display: "flex", gap: 14, fontSize: 12.5, color: C.inkSoft }}>
            <span style={{ display: "flex", alignItems: "center", gap: 4 }}><Footprints size={14} /> {trip.distanceKm} {t("unitKm")}</span>
            <span style={{ display: "flex", alignItems: "center", gap: 4 }}><Clock size={14} /> {durationText(trip.durationHrs)}</span>
            <span style={{ display: "flex", alignItems: "center", gap: 4, color: diffColor(trip.difficulty) }}>
              <span style={{ width: 7, height: 7, borderRadius: 7, background: diffColor(trip.difficulty), display: "inline-block" }} />
              {diffLabel(trip.difficulty)}
            </span>
          </div>
          <ChevronRight size={18} color={C.faint} />
        </div>
        {STATUS[trip.status]?.group === "upcoming" && (
          <div style={{ padding: isAdmin ? "0 16px 10px" : "0 16px 13px", fontSize: 12, color: left <= 3 ? C.rasp : C.green, fontWeight: 600, display: "flex", alignItems: "center", gap: 5 }}>
            <Users size={13} /> {left > 0 ? `${t("spotsLeft")} ${left} ${t("spotsLeftWord")}`.trim() : t("noSpots")}
          </div>
        )}
      </div>
      {isAdmin && (
        <div style={{ borderTop: `1px solid ${C.line}`, background: "#fff" }}>
          <div style={{ display: "flex", gap: 8, padding: "10px 14px", alignItems: "center" }}>
            <button onClick={onEdit} style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", gap: 5, background: C.greenSoft, color: C.greenDark, border: "none", borderRadius: 9, padding: "9px", fontSize: 12.5, fontWeight: 700, cursor: "pointer" }}><Pencil size={13} /> {t("edit")}</button>
            <select value={trip.status} onChange={(e) => onSetStatus(e.target.value)} style={{ flex: 1.2, border: `1px solid ${C.line}`, borderRadius: 9, padding: "9px 8px", fontSize: 12.5, fontWeight: 700, fontFamily: "inherit", background: C.yellowSoft, color: C.yellowInk, cursor: "pointer" }}>
              {STATUS_ORDER.map((s) => (
                <option key={s} value={s}>{statusLabel(s)}</option>
              ))}
            </select>
          </div>
          {trip.status === "postponed" && (
            <div style={{ padding: "0 14px 12px" }}>
              <input
                value={trip.postponedTo || ""}
                onChange={(e) => onSetPostponedDate(e.target.value)}
                placeholder="Нова дата, напр.: 12 липня"
                style={{ width: "100%", boxSizing: "border-box", border: `1px solid ${C.line}`, borderRadius: 9, padding: "9px 12px", fontSize: 13, fontFamily: "inherit", background: "#fff", color: C.ink }}
              />
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ── Place photo (real image if provided, else themed placeholder) ──────
function PlacePhoto({ trip }) {
  const [failed, setFailed] = React.useState(false);
  const typeIcon = {
    lake: <Waves size={40} strokeWidth={1.5} />,
    city: <Building2 size={40} strokeWidth={1.5} />,
    gorge: <Mountain size={40} strokeWidth={1.5} />,
    mountain: <Mountain size={40} strokeWidth={1.5} />,
    forest: <TreePine size={40} strokeWidth={1.5} />,
    valley: <MountainSnow size={40} strokeWidth={1.5} />,
    river: <Droplets size={40} strokeWidth={1.5} />,
    museum: <Landmark size={40} strokeWidth={1.5} />,
    waterfall: <CloudRain size={40} strokeWidth={1.5} />,
    bike: <Bike size={40} strokeWidth={1.5} />,
  }[trip.placeType] || <Mountain size={40} strokeWidth={1.5} />;

  const hasImage = trip.image && trip.image.trim() !== "" && !failed;

  return (
    <div style={{
      position: "relative", borderRadius: 18, overflow: "hidden",
      marginBottom: 14, aspectRatio: "16/9",
      boxShadow: "0 4px 16px rgba(60,79,44,0.12)",
    }}>
      {hasImage ? (
        <img
          src={trip.image}
          alt={tc(trip.title)}
          onError={() => setFailed(true)}
          style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }}
        />
      ) : (
        <div style={{
          width: "100%", height: "100%", background: trip.heroGradient,
          display: "flex", flexDirection: "column", alignItems: "center",
          justifyContent: "center", color: "rgba(255,255,255,0.92)", gap: 10,
        }}>
          <div style={{
            width: 72, height: 72, borderRadius: 20,
            background: "rgba(255,255,255,0.15)",
            display: "flex", alignItems: "center", justifyContent: "center",
          }}>{typeIcon}</div>
          <div style={{ fontSize: 17, fontWeight: 700 }}>{tc(trip.title)}</div>
          <div style={{
            display: "flex", alignItems: "center", gap: 5, fontSize: 11.5,
            opacity: 0.85, background: "rgba(0,0,0,0.18)", padding: "4px 10px", borderRadius: 20,
          }}>
            <Camera size={13} /> Фото додається
          </div>
        </div>
      )}
    </div>
  );
}

// ── Пошук поїздів у режимі користувача прибрано ──────────────────────
// Розклад тепер вводить організатор вручну (розділ «Поїзди» в редакторі),
// а для повного розкладу лишилась кнопка на сайт Deutsche Bahn. Разом із
// планувальником прибрано і весь мережевий шар до сервісів розкладу:
// він більше нікуди не викликався.

// Маленька крутилка завантаження — використовується на кнопках пошуку
// розкладу, щоб було видно, що застосунок працює, а не завис.
// Екран завантаження при відкритті застосунку: логотип обертається за
// годинниковою стрілкою, поки підвантажуються поїздки з бази.
function SplashScreen() {
  return (
    <div style={{
      position: "fixed", inset: 0, background: C.green, zIndex: 9999,
      display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 18,
    }}>
      <img src={LOGO} alt="" style={{
        width: 92, height: 92, borderRadius: 22, objectFit: "cover",
        border: "2px solid rgba(253,228,70,0.45)", boxShadow: "0 6px 20px rgba(0,0,0,0.25)",
        animation: "appSpin 1.4s linear infinite",
      }} />
      <div style={{ color: "rgba(255,255,255,0.75)", fontSize: 13.5, fontWeight: 600, letterSpacing: 0.3 }}>
        {t("appName")}
      </div>
      <style>{"@keyframes appSpin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }"}</style>
    </div>
  );
}

function Spinner({ size = 15, color = "#fff" }) {
  return (
    <>
      <span style={{
        display: "inline-block", width: size, height: size, borderRadius: "50%",
        border: `2px solid rgba(255,255,255,0.35)`, borderTopColor: color,
        animation: "jpSpin 0.7s linear infinite", flexShrink: 0,
      }} />
      <style>{"@keyframes jpSpin { to { transform: rotate(360deg); } }"}</style>
    </>
  );
}

// ── Section definitions (renameable, reorderable per trip) ─────────────
// Each section has a fixed `type` (which content renders) and an editable
// `title`. The default list/order below is used for trips that don't yet
// carry their own `sections` array (backward compatible).
const DEFAULT_SECTIONS = [
  { type: "about", tkey: "secAbout" },
  { type: "booking", tkey: "secBooking" },
  { type: "difficulty", tkey: "secDifficulty" },
  { type: "weather", tkey: "secWeather" },
  { type: "travel", tkey: "secTravel" },
  { type: "meeting", tkey: "secMeeting" },
  { type: "route", tkey: "secRoute" },
  { type: "cafes", tkey: "secCafes" },
  { type: "packing", tkey: "secPacking" },
  { type: "drive", tkey: "secDrive" },
  { type: "contact", tkey: "secContact" },
];
// Спільний архів фото й відео з усіх поїздок. Окрема поїздка може мати
// власне посилання (поле driveUrl) — тоді показується воно.
const DRIVE_URL = "https://drive.google.com/drive/folders/17zaBzXwcsTBnjvf7ncOlzltQNaVTGOyi?usp=drive_link";
const SECTION_LABELS = {
  about: "Про місце", booking: "Запис у поїздку", difficulty: "Складність", weather: "Погода",
  travel: "Транспорт", meeting: "Точка збору", route: "Маршрут",
  cafes: "Кафе/їжа", packing: "Спорядження", drive: "Фото та відео", contact: "Контакт",
};
// Вбудована назва розділу поточною мовою. Потрібна і для показу, і для
// підказки в редакторі: якщо організатор лишає поле порожнім, застосунок
// бере власний, вручну виписаний переклад — він завжди правильний в усіх
// мовах, на відміну від машинного перекладу довільної назви.
const sectionDefaultTitle = (sec) => {
  const key = (sec && sec.tkey) || (DEFAULT_SECTIONS.find((d) => d.type === (sec && sec.type)) || {}).tkey;
  return key ? t(key) : "";
};

// Дні тижня для підпису дати. Рахуються з поля «дата для прогнозу», тож
// організаторові не треба вписувати їх руками — і вони самі стають на
// потрібну мову.
const WEEKDAYS = {
  uk: ["Неділя", "Понеділок", "Вівторок", "Середа", "Четвер", "П'ятниця", "Субота"],
  en: ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"],
  ru: ["Воскресенье", "Понедельник", "Вторник", "Среда", "Четверг", "Пятница", "Суббота"],
};
// Скільки місць зайнято. Джерело правди — реальні записи з бази; поле
// spotsTaken лишається запасним для поїздок, створених до появи запису.
function takenOf(trip, counts) {
  if (counts && Object.prototype.hasOwnProperty.call(counts, trip.id)) return counts[trip.id];
  return Number(trip.spotsTaken) || 0;
}
// Чи вже минув дедлайн запису. Порожнє поле означає «без дедлайну».
function bookingClosed(trip) {
  const d = String((trip && trip.deadline) || "").trim();
  if (d === "") return false;
  const dt = new Date(d);
  if (isNaN(dt.getTime())) return false;
  return Date.now() > dt.getTime();
}
// Дедлайн у людському вигляді: «пт, 14.08, 22:00».
function deadlineText(trip) {
  const d = String((trip && trip.deadline) || "").trim();
  if (d === "") return "";
  const dt = new Date(d);
  if (isNaN(dt.getTime())) return "";
  const wd = (WEEKDAYS[CURRENT_LANG] || WEEKDAYS.uk)[dt.getDay()];
  const p2 = (n) => String(n).padStart(2, "0");
  return `${wd}, ${p2(dt.getDate())}.${p2(dt.getMonth() + 1)}, ${p2(dt.getHours())}:${p2(dt.getMinutes())}`;
}

function weekdayOf(iso) {
  // Полудень замість опівночі — щоб зсув часового поясу не «переносив»
  // поїздку на сусідній день.
  const d = new Date(String(iso || "").trim() + "T12:00:00");
  if (isNaN(d.getTime())) return "";
  return (WEEKDAYS[CURRENT_LANG] || WEEKDAYS.uk)[d.getDay()];
}
// Підпис дати з днем тижня. Якщо організатор уже вписав день у текст
// дати («Субота, 21 червня»), другий раз не додаємо.
function dateWithWeekday(trip) {
  const label = tc(trip && trip.dateLabel) || "";
  const wd = weekdayOf(trip && trip.date);
  if (!wd) return label;
  const hay = (label + " " + ukOf(trip && trip.dateLabel)).toLowerCase();
  const known = [].concat(WEEKDAYS.uk, WEEKDAYS.en, WEEKDAYS.ru);
  if (known.some((w) => hay.includes(w.toLowerCase().slice(0, 5)))) return label;
  return label ? `${wd}, ${label}` : wd;
}

const resolveSections = (trip) => {
  // If the trip carries its own sections (possibly renamed by the organizer),
  // use them as-is. Otherwise use the defaults, translated to current language.
  if (trip.sections && trip.sections.length > 0) {
    // ВАЖЛИВО: збережені секції можуть містити лише технічний ключ (tkey)
    // без назви — тоді заголовок треба взяти з перекладу, інакше секція
    // рендериться без підпису (лишається сама іконка).
    const stored = trip.sections.map((s) => ({
      visible: true,
      ...s,
      title: (s.title && String(s.title).trim() !== "") ? s.title : sectionDefaultTitle(s),
    }));
    // Розділи, доданих у застосунок після збереження цієї поїздки, у її
    // списку відсутні. Дописуємо їх у кінець, інакше нове ніколи не
    // з'явилось би у старих поїздках.
    const have = new Set(stored.map((x) => x.type));
    const missing = DEFAULT_SECTIONS
      .filter((d) => !have.has(d.type))
      .map((d) => ({ visible: true, type: d.type, tkey: d.tkey, title: t(d.tkey) }));
    return stored.concat(missing);
  }
  return DEFAULT_SECTIONS.map((s) => ({ visible: true, type: s.type, title: t(s.tkey) }));
};

// ── Жива погода (Open-Meteo, безкоштовно, без ключів) ─────────────────
// Тягне прогноз на дату поїздки (до 16 днів наперед) за координатами.
// Якщо дати нема, вона в минулому або мережа недоступна — показує
// демо-погоду, збережену в поїздці.
const WMO_MAP = [
  { codes: [0], icon: "sun", uk: "Ясно", en: "Clear", ru: "Ясно" },
  { codes: [1, 2], icon: "sun", uk: "Переважно ясно", en: "Mostly clear", ru: "Преимущественно ясно" },
  { codes: [3], icon: "cloud", uk: "Хмарно", en: "Cloudy", ru: "Облачно" },
  { codes: [45, 48], icon: "cloud", uk: "Туман", en: "Fog", ru: "Туман" },
  { codes: [51, 53, 55, 56, 57], icon: "rain", uk: "Мряка", en: "Drizzle", ru: "Морось" },
  { codes: [61, 63, 65, 66, 67, 80, 81, 82], icon: "rain", uk: "Дощ", en: "Rain", ru: "Дождь" },
  { codes: [71, 73, 75, 77, 85, 86], icon: "snow", uk: "Сніг", en: "Snow", ru: "Снег" },
  { codes: [95, 96, 99], icon: "rain", uk: "Гроза", en: "Thunderstorm", ru: "Гроза" },
];
const wmoInfo = (code) => WMO_MAP.find((m) => m.codes.includes(code)) || WMO_MAP[2];

function LiveWeather({ trip, isAdmin }) {
  const [live, setLive] = useState(null);
  const [mode, setMode] = useState("fallback"); // fallback | loading | live
  const [reason, setReason] = useState("nodate"); // nodate | nocoords | past | far | error
  // Що саме прийшло від сервісу. Показується лише організаторові — щоб
  // не гадати, а бачити координати, дату й сирі числа.
  const [raw, setRaw] = useState("");
  // Лічильник перезапитів: змінюється кожні 15 хвилин і тим самим
  // перезапускає завантаження.
  const [tick, setTick] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setTick((n) => n + 1), 15 * 60 * 1000);
    return () => clearInterval(id);
  }, []);
  useEffect(() => {
    let cancelled = false;
    // Погода, вписана організатором, має перевагу над будь-яким
    // прогнозом. Причина проста: жоден сервіс не можна перевірити
    // зсередини застосунку, а організатор дивиться той прогноз, якому
    // довіряє, і бачить розбіжність раніше за всіх.
    if (trip.weatherManual) { setReason("manual"); setMode("fallback"); return; }
    const d = (trip.date || "").trim();
    // Координати могли зберегтися як текст — приводимо до чисел, щоб живий
    // прогноз не «зривався» мовчки в демо.
    // Погода потрібна там, КУДИ їдемо, а не там, де сідаємо в поїзд.
    // Раніше бралися координати точки збору — для Штарнберга це був
    // Пасінг у Мюнхені, за 30 км від озера. Тепер спершу шукаємо першу
    // точку маршруту з координатами, і лише як запасний варіант беремо
    // точку збору.
    const spot = (trip.route || []).find((st) =>
      st && !isNaN(parseFloat(st.lat)) && !isNaN(parseFloat(st.lng)));
    const src = spot ? "маршрут" : "точка збору";
    const lat = parseFloat(spot ? spot.lat : (trip.coords && trip.coords.lat));
    const lng = parseFloat(spot ? spot.lng : (trip.coords && trip.coords.lng));
    if (!d) { setReason("nodate"); setMode("fallback"); return; }
    if (isNaN(lat) || isNaN(lng)) { setReason("nocoords"); setMode("fallback"); return; }
    const today = new Date(); today.setHours(0, 0, 0, 0);
    const target = new Date(d + "T00:00:00");
    const diff = Math.round((target - today) / 86400000);
    if (isNaN(diff) || diff < 0) { setReason("past"); setMode("fallback"); return; }
    if (diff > 15) {
      // Справжній прогноз існує лише на ~16 днів. Далі — типова погода для
      // цієї дати за минулі роки, чесно підписана.
      if (diff <= 60) {
        setMode("loading");
        const yr = new Date(d + "T00:00:00").getFullYear();
        const md = d.slice(5);
        Promise.all([yr - 1, yr - 2, yr - 3].map((y) =>
          fetch(`https://archive-api.open-meteo.com/v1/archive?latitude=${lat}&longitude=${lng}&start_date=${y}-${md}&end_date=${y}-${md}&daily=temperature_2m_max,apparent_temperature_max,precipitation_sum,wind_speed_10m_max,relative_humidity_2m_mean&timezone=Europe%2FBerlin`)
            .then((r) => r.json()).catch(() => null)
        )).then((rs) => {
          if (cancelled) return;
          const vals = rs.filter((r) => r && r.daily && r.daily.temperature_2m_max && r.daily.temperature_2m_max[0] != null);
          if (vals.length === 0) { setReason("far"); setMode("fallback"); return; }
          const avg = (pick) => {
            const nums = vals.map((v) => pick(v.daily)).filter((x) => typeof x === "number");
            return nums.length ? nums.reduce((a, b) => a + b, 0) / nums.length : null;
          };
          const rain = avg((dd) => dd.precipitation_sum && dd.precipitation_sum[0]);
          setLive({
            tempC: Math.round(avg((dd) => dd.temperature_2m_max[0]) || 0),
            tempMin: null,
            feelsC: Math.round(avg((dd) => dd.apparent_temperature_max && dd.apparent_temperature_max[0]) || 0),
            rainPct: rain != null ? Math.min(100, Math.round(rain * 20)) : 0,
            windKmh: Math.round(avg((dd) => dd.wind_speed_10m_max && dd.wind_speed_10m_max[0]) || 0),
            humidity: Math.round(avg((dd) => dd.relative_humidity_2m_mean && dd.relative_humidity_2m_mean[0]) || 60),
            icon: "cloud", cond: null,
          });
          setReason("climate"); setMode("climate");
        });
        return;
      }
      setReason("far"); setMode("fallback"); return;
    }
    setMode("loading");
    // Просимо ДЕННІ показники, а не погодинні. Раніше бралася температура
    // рівно о 13:00 — і застосунок показував 18°, коли всі інші сервіси
    // показували 29°. Обидва числа були правдиві, але означали різне:
    // одне — температуру в конкретну годину під хмарою, друге — максимум
    // за день. Люди звіряють із WetterOnline і Google, а ті показують
    // максимум і мінімум. Тепер і ми показуємо те саме.
    const url = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lng}` +
      `&daily=weather_code,temperature_2m_max,temperature_2m_min,apparent_temperature_max,` +
      `precipitation_probability_max,wind_speed_10m_max,relative_humidity_2m_mean` +
      `&timezone=Europe%2FBerlin&start_date=${d}&end_date=${d}` +
      // Мітка часу проти кешу браузера: без неї оновлення кожні 15 хвилин
      // поверталося б тим самим збереженим відповіддю.
      `&_t=${Math.floor(Date.now() / 60000)}`;
    // Дві незалежні моделі одночасно. ECMWF — європейський центр
    // середньострокових прогнозів, у світі вважається найточнішим на
    // кілька днів уперед. ICON — німецька метеослужба. Показуємо ECMWF,
    // а в діагностиці видно ОБИДВІ: якщо вони розходяться між собою,
    // це вже не помилка застосунку, а стан прогнозу на цей день.
    let iconNote = "—";
    Promise.all([
      fetch(`${url}&models=ecmwf_ifs025`).then((r) => (r.ok ? r.json() : null)).catch(() => null),
      fetch(`${url}&models=icon_seamless`).then((r) => (r.ok ? r.json() : null)).catch(() => null),
    ])
      .then(([ec, ic]) => {
        const dd = ic && ic.daily;
        if (dd && dd.temperature_2m_max && dd.temperature_2m_max[0] != null) {
          iconNote = `ICON/DWD: max ${dd.temperature_2m_max[0]}° / min ${dd.temperature_2m_min[0]}° · опади ${dd.precipitation_probability_max[0]}%`;
        }
        // Якщо ECMWF мовчить — беремо ICON, а не лишаємо порожньо.
        const good = ec && ec.daily && ec.daily.temperature_2m_max && ec.daily.temperature_2m_max[0] != null;
        return good ? ec : ic;
      })
      .then((j) => (j ? j : fetch(url).then((r) => r.json())))
      .then((j) => {
        if (cancelled || j == null) return;
        const dl = j && j.daily;
        if (j && j.error) { setRaw(`ПОМИЛКА СЕРВІСУ: ${j.reason || "невідома"}`); setReason("error"); setMode("fallback"); return; }
        if (!dl || !dl.time || dl.time.length === 0 || dl.temperature_2m_max == null) {
          setRaw(`Відповідь без денних даних. Отримано ключі: ${Object.keys(j || {}).join(", ") || "нічого"}`);
          setReason("error"); setMode("fallback"); return;
        }
        const one = (arr, fb) => (arr && arr[0] != null ? arr[0] : fb);
        const info = wmoInfo(one(dl.weather_code, 3));
        const tmax = Math.round(one(dl.temperature_2m_max, 0));
        setLive({
          tempC: tmax,
          tempMin: dl.temperature_2m_min && dl.temperature_2m_min[0] != null ? Math.round(dl.temperature_2m_min[0]) : null,
          feelsC: Math.round(one(dl.apparent_temperature_max, tmax)),
          rainPct: Math.round(one(dl.precipitation_probability_max, 0)),
          windKmh: Math.round(one(dl.wind_speed_10m_max, 0)),
          humidity: Math.round(one(dl.relative_humidity_2m_mean, trip.weather.humidity)),
          icon: info.icon, cond: info,
        });
        setRaw(`${lat.toFixed(4)}, ${lng.toFixed(4)} (${src}) · ${dl.time[0]} · висота ${j.elevation != null ? j.elevation + " м" : "?"}\nПоказано: max ${dl.temperature_2m_max[0]}° / min ${dl.temperature_2m_min && dl.temperature_2m_min[0]}° · код ${dl.weather_code && dl.weather_code[0]} · опади ${dl.precipitation_probability_max && dl.precipitation_probability_max[0]}%\nДруга модель — ${iconNote}`);
        setMode("live");
      })
      .catch(() => { if (!cancelled) { setReason("error"); setMode("fallback"); } });
    return () => { cancelled = true; };
  }, [trip.id, trip.date, tick]);

  // Стан неба зберігається кодом WMO, а не текстом. Тоді підпис
  // перекладається сам усіма мовами й не залежить від автоперекладу —
  // те саме рішення, що з колією у поїздах.
  const manualInfo = wmoInfo(Number(trip.weather.code));
  const w = (mode === "live" || mode === "climate") && live ? live : {
    tempC: trip.weather.tempC,
    tempMin: trip.weather.tempMin != null && trip.weather.tempMin !== "" ? Number(trip.weather.tempMin) : null,
    feelsC: trip.weather.feelsC, rainPct: trip.weather.rainPct,
    windKmh: trip.weather.windKmh, humidity: trip.weather.humidity,
    icon: trip.weather.code != null ? manualInfo.icon : trip.weather.icon,
    cond: null,
  };
  const condText = mode === "live" && live && live.cond ? (live.cond[CURRENT_LANG] || live.cond.uk)
    : mode === "climate" ? t("wClimateCond")
    : trip.weather.code != null ? (manualInfo[CURRENT_LANG] || manualInfo.uk)
    : tc(trip.weather.condition);
  return (
    <>
      <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 14 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <div style={{ color: C.green }}>{weatherIcon(w.icon, 44)}</div>
          <div>
            <div style={{ display: "flex", alignItems: "baseline", gap: 7 }}>
              <span style={{ fontSize: 32, fontWeight: 800, color: C.ink, lineHeight: 1 }}>{w.tempC}°</span>
              {w.tempMin != null && (
                <span style={{ fontSize: 19, fontWeight: 700, color: C.muted, lineHeight: 1 }}>/ {w.tempMin}°</span>
              )}
            </div>
            {w.feelsC !== w.tempC && (
              <div style={{ fontSize: 12.5, color: C.muted }}>{t("wFeels")} {w.feelsC}°</div>
            )}
          </div>
        </div>
        <div style={{ fontSize: 14, color: "#4a4a42", fontWeight: 600 }}>{condText}</div>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 8 }}>
        {[
          { icon: <Droplets size={15} />, label: t("wRain"), value: `${w.rainPct}%` },
          { icon: <Wind size={15} />, label: t("wWind"), value: `${w.windKmh} ${t("unitKm")}/${t("unitH")}` },
          { icon: <Cloud size={15} />, label: t("wHumidity"), value: `${w.humidity}%` },
        ].map((x, i) => (
          <div key={i} style={{ background: C.greenSoft, borderRadius: 11, padding: "9px 6px", textAlign: "center" }}>
            <div style={{ color: C.green, display: "flex", justifyContent: "center", marginBottom: 3 }}>{x.icon}</div>
            <div style={{ fontSize: 13.5, fontWeight: 700, color: C.ink }}>{x.value}</div>
            <div style={{ fontSize: 10.5, color: C.muted }}>{x.label}</div>
          </div>
        ))}
      </div>
      {/* Підпис про джерело прибрано: учасникові байдуже, звідки числа,
          а «дані вказані організатором» лише підважувало довіру до них.
          Пояснення лишається в діагностиці, видимій організаторові. */}
      {isAdmin && raw !== "" && (
        <div style={{ marginTop: 8, background: "#fff", border: `1px solid ${C.line}`, borderRadius: 9, padding: "8px 10px", fontSize: 10.5, color: C.muted, lineHeight: 1.5, wordBreak: "break-word", whiteSpace: "pre-line" }}>
          <b style={{ color: C.ink }}>Джерело погоди:</b>{"\n"}{raw}
        </div>
      )}
    </>
  );
}

// ── Запис у поїздку ──────────────────────────────────────────────────
// Один компонент на всі стани: відкритий запис, форма, підтвердження,
// «місць немає», «запис закрито». Стан обирається сам за дедлайном і
// кількістю вільних місць, тож організаторові нічого не треба вимикати
// вручну — навіть якщо він спить, коли настане дедлайн.
function BookingSection({ trip, taken, onBooked }) {
  const [open, setOpen] = useState(false);
  const [name, setName] = useState("");
  const [contact, setContact] = useState("");
  const [people, setPeople] = useState(1);
  const [showName, setShowName] = useState(true);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [done, setDone] = useState(false);
  const [guests, setGuests] = useState(null);
  // Власний запис цього пристрою: { id, token, name, contact, people, showName }
  const [mine, setMine] = useState(() => myBooking(trip.id));
  const [editing, setEditing] = useState(false);
  const [saved, setSaved] = useState(false);
  // Пошук власного запису для тих, хто записався до появи ключів.
  const [finding, setFinding] = useState(false);
  const [fName, setFName] = useState("");
  const [fContact, setFContact] = useState("");

  const spots = Number(trip.spots) || 0;
  const left = Math.max(0, spots - taken);
  const closed = bookingClosed(trip);
  const full = spots > 0 && left <= 0;
  const dl = deadlineText(trip);

  // Стан власної заявки перепитуємо щоразу: організатор міг підтвердити
  // або відхилити її, поки застосунок був закритий.
  useEffect(() => {
    if (!mine || !mine.id || !mine.token || !sbConfigured()) return;
    sbMyBooking(mine.id, mine.token)
      .then((r) => {
        if (!r) { rememberBooking(trip.id, null); setMine(null); return; }
        const rec = { ...mine, status: r.status, name: r.name,
                      contact: r.contact || "", people: Number(r.people) || 1 };
        rememberBooking(trip.id, rec); setMine(rec);
      })
      .catch(() => {});
  }, [trip.id]);

  const loadGuests = () => {
    if (!sbConfigured()) return;
    sbGuests(trip.id).then((g) => setGuests(g || [])).catch(() => setGuests([]));
  };
  useEffect(() => { loadGuests(); }, [trip.id, done]);

  // Зберегти правки власного запису. Форма та сама, що й для запису —
  // відрізняється лише те, куди йде результат.
  const saveEdit = async () => {
    if (name.trim() === "") { setErr(t("bkFillFields")); return; }
    setBusy(true); setErr("");
    try {
      await sbUpdateBooking(mine.id, mine.token, name.trim(), contact.trim(), people, showName);
      const rec = { ...mine, name: name.trim(), contact: contact.trim(), people, showName };
      rememberBooking(trip.id, rec);
      setMine(rec); setEditing(false); setSaved(true);
      setTimeout(() => setSaved(false), 2500);
      loadGuests();
      if (onBooked) onBooked();
    } catch (e) {
      setErr(t(bookErrorKey(e)));
    } finally { setBusy(false); }
  };

  // Забрати свій запис на цей пристрій. Потрібно тим, хто записався
  // до появи ключів, або хто відкрив застосунок з іншого телефона.
  const claim = async () => {
    if (fName.trim() === "") { setErr(t("bkFillFields")); return; }
    setBusy(true); setErr("");
    try {
      const r = await sbClaimBooking(trip.id, fName.trim(), fContact.trim());
      const rec = {
        id: r.id, token: r.token, name: r.name,
        contact: r.contact || "", people: Number(r.people) || 1,
        showName: r.show_name !== false,
      };
      rememberBooking(trip.id, rec);
      setMine(rec); setFinding(false); setFName(""); setFContact("");
    } catch (e) {
      setErr(t(bookErrorKey(e)));
    } finally { setBusy(false); }
  };

  // Зняти свій запис. Ключ підтверджує, що це справді власний запис.
  const leave = async () => {
    if (!window.confirm(t("bkLeaveAsk"))) return;
    setBusy(true); setErr("");
    try {
      await sbCancelBooking(mine.id, mine.token);
      rememberBooking(trip.id, null);
      setMine(null); setEditing(false); setOpen(false); setDone(false);
      setName(""); setContact(""); setPeople(1);
      loadGuests();
      if (onBooked) onBooked();
    } catch (e) {
      setErr(t(bookErrorKey(e)));
    } finally { setBusy(false); }
  };

  // Відкрити форму на редагування з підставленими значеннями.
  const startEdit = () => {
    setName(mine.name || ""); setContact(mine.contact || "");
    setPeople(Number(mine.people) || 1); setShowName(mine.showName !== false);
    setErr(""); setEditing(true); setOpen(true);
  };

  const submit = async () => {
    // Контакт необовʼязковий: людина сама вирішує, лишати його чи ні.
    if (name.trim() === "") { setErr(t("bkFillFields")); return; }
    setBusy(true); setErr("");
    try {
      const rec = await sbBook(trip.id, name.trim(), contact.trim(), people, showName);
      // Ключ зберігаємо одразу — без нього людина більше не зможе
      // виправити свій запис і муситиме писати організаторові.
      const saveRec = {
        id: rec && rec.id, token: rec && rec.token,
        status: (rec && rec.status) || "confirmed",
        name: name.trim(), contact: contact.trim(), people, showName,
      };
      rememberBooking(trip.id, saveRec);
      setMine(saveRec);
      // Заявка, що чекає, — привід одразу постукати організаторові.
      if (saveRec.status === "pending" && saveRec.id) notifyOrganizer(saveRec.id, saveRec.token);
      setDone(true); setOpen(false);
      if (onBooked) onBooked();
    } catch (e) {
      setErr(t(bookErrorKey(e)));
    } finally { setBusy(false); }
  };

  const box = (bg, color, icon, text) => (
    <div style={{ background: bg, borderRadius: 11, padding: "10px 12px", display: "flex", gap: 9, alignItems: "flex-start", marginBottom: 11 }}>
      <span style={{ color, flexShrink: 0, display: "flex", marginTop: 1 }}>{icon}</span>
      <span style={{ fontSize: 12.5, color, lineHeight: 1.5 }}>{text}</span>
    </div>
  );

  return (
    <>
      {dl !== "" && !done && (
        <div style={{ background: closed ? C.raspSoft : C.yellowSoft, border: `1px solid ${closed ? C.rasp : C.yellow}`, borderRadius: 11, padding: "10px 12px", display: "flex", alignItems: "center", gap: 9, marginBottom: 11 }}>
          <Clock size={16} style={{ color: closed ? C.rasp : C.yellowInk, flexShrink: 0 }} />
          <span style={{ fontSize: 12.5, color: closed ? C.rasp : C.yellowInk }}>
            {closed ? t("bkClosedTitle") : <>{t("bkDeadline")} <b style={{ fontWeight: 700 }}>{dl}</b></>}
          </span>
        </div>
      )}

      {trip.needsApproval && !mine && !closed && (
        <div style={{ background: C.yellowSoft, borderRadius: 11, padding: "10px 12px", display: "flex", gap: 9, alignItems: "flex-start", marginBottom: 11 }}>
          <Info size={15} style={{ color: C.yellowInk, flexShrink: 0, marginTop: 1 }} />
          <span style={{ fontSize: 12.5, color: C.yellowInk, lineHeight: 1.5 }}>{t("bkNeedsApproval")}</span>
        </div>
      )}
      {spots > 0 && !done && (
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 12 }}>
          <Users size={16} style={{ color: full ? C.rasp : C.green, flexShrink: 0 }} />
          <span style={{ fontSize: 13.5, color: C.ink, fontWeight: 600 }}>
            {full ? t("bkNoSpotsTitle") : <>{t("bkLeft")} {left} {t("bkOf")} {spots} {t("bkSpots")}</>}
          </span>
        </div>
      )}

      {/* Свій запис видно завжди, а не лише одразу після натискання:
          людина може зайти через тиждень і виправити ім'я чи кількість
          осіб, не звертаючись до організатора. */}
      {mine && !editing && (
        <div style={{ border: `1.5px solid ${mine.status === "pending" ? C.yellow : mine.status === "declined" ? C.rasp : C.green}`, background: mine.status === "pending" ? C.yellowSoft : mine.status === "declined" ? C.raspSoft : C.greenSoft, borderRadius: 13, padding: 13, marginBottom: 11 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
            <ClipboardCheck size={16} style={{ color: C.greenDark, flexShrink: 0 }} />
            <span style={{ fontSize: 13, fontWeight: 800, color: C.greenDark, flex: 1 }}>
              {saved ? t("bkSaved")
                : mine.status === "pending" ? t("bkPending")
                : mine.status === "declined" ? t("bkDeclined")
                : t("bkMine")}
            </span>
            {/* Після дедлайну редагування закривається: список уже пішов
                організаторові, і тиха зміна за його спиною зіпсувала б
                розрахунок. Те саме перевіряє й база — не лише екран. */}
            {!closed && (
              <button onClick={startEdit}
                style={{ border: `1px solid ${C.green}`, background: "#fff", color: C.greenDark, borderRadius: 9, padding: "6px 13px", fontSize: 12, fontWeight: 700, cursor: "pointer", fontFamily: "inherit", flexShrink: 0 }}>
                {t("bkEdit")}
              </button>
            )}
          </div>
          <div style={{ fontSize: 14, fontWeight: 700, color: C.ink }}>
            {mine.name}{Number(mine.people) > 1 ? ` · ${mine.people} ${t("bkPersons")}` : ""}
          </div>
          {mine.contact && mine.contact.trim() !== "" && (
            <div style={{ fontSize: 12.5, color: C.muted, marginTop: 2 }}>{mine.contact}</div>
          )}
          {mine.status === "pending" && (
            <div style={{ marginTop: 9, background: C.yellowSoft, borderRadius: 10, padding: "10px 12px", display: "flex", gap: 8, alignItems: "flex-start" }}>
              <Clock size={14} style={{ color: C.yellowInk, flexShrink: 0, marginTop: 1 }} />
              <span style={{ fontSize: 11.5, color: C.yellowInk, lineHeight: 1.5 }}>{t("bkPendingNote")}</span>
            </div>
          )}
          {mine.status === "declined" && (
            <div style={{ marginTop: 9, background: C.raspSoft, borderRadius: 10, padding: "10px 12px", display: "flex", gap: 8, alignItems: "flex-start" }}>
              <Info size={14} style={{ color: C.rasp, flexShrink: 0, marginTop: 1 }} />
              <span style={{ fontSize: 11.5, color: C.rasp, lineHeight: 1.5 }}>{t("bkDeclinedNote")}</span>
            </div>
          )}
          {closed ? (
            <div style={{ marginTop: 11, background: C.yellowSoft, borderRadius: 10, padding: "10px 12px", display: "flex", gap: 8, alignItems: "flex-start" }}>
              <Info size={14} style={{ color: C.yellowInk, flexShrink: 0, marginTop: 1 }} />
              <span style={{ fontSize: 11.5, color: C.yellowInk, lineHeight: 1.5 }}>{t("bkLockedNote")}</span>
            </div>
          ) : (
            <button onClick={leave} disabled={busy}
              style={{ width: "100%", marginTop: 11, border: `1px solid ${C.rasp}`, background: "transparent", color: C.rasp, borderRadius: 10, padding: "10px", fontSize: 12.5, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>
              {t("bkLeave")}
            </button>
          )}
        </div>
      )}

      {!mine && closed && box(C.raspSoft, C.rasp, <Info size={15} />, t("bkClosed") + " " + t("bkAskOrganizer"))}
      {!mine && !closed && full && box(C.raspSoft, C.rasp, <Info size={15} />, t("bkNoSpots") + " " + t("bkAskOrganizer"))}

      {!mine && !open && !finding && guests && guests.length > 0 && (
        <button onClick={() => { setFinding(true); setErr(""); }}
          style={{ width: "100%", border: "none", background: "none", color: C.green, fontSize: 12.5, fontWeight: 700, cursor: "pointer", fontFamily: "inherit", textDecoration: "underline", padding: "4px 0 12px", textAlign: "left" }}>
          {t("bkFindMine")}
        </button>
      )}

      {finding && (
        <div style={{ border: `1.5px solid ${C.green}`, borderRadius: 13, padding: 13, marginBottom: 11, background: "#fff" }}>
          <div style={{ fontSize: 13.5, fontWeight: 800, color: C.ink, marginBottom: 5 }}>{t("bkFindTitle")}</div>
          <p style={{ fontSize: 11.5, color: C.muted, lineHeight: 1.5, margin: "0 0 10px" }}>{t("bkFindNote")}</p>
          <input value={fName} onChange={(e) => { setFName(e.target.value); setErr(""); }} placeholder={t("bkName")}
            style={{ width: "100%", boxSizing: "border-box", border: `1px solid ${C.line}`, borderRadius: 10, padding: "11px", fontSize: 14, fontFamily: "inherit", marginBottom: 8 }} />
          <input value={fContact} onChange={(e) => { setFContact(e.target.value); setErr(""); }} placeholder={t("bkContact")}
            style={{ width: "100%", boxSizing: "border-box", border: `1px solid ${C.line}`, borderRadius: 10, padding: "11px", fontSize: 14, fontFamily: "inherit", marginBottom: 10 }} />
          {err !== "" && <p style={{ fontSize: 12, color: C.rasp, margin: "0 0 10px", lineHeight: 1.45 }}>{err}</p>}
          <div style={{ display: "flex", gap: 8 }}>
            <button onClick={() => { setFinding(false); setErr(""); }}
              style={{ border: `1px solid ${C.line}`, background: "#fff", color: C.muted, borderRadius: 11, padding: "12px 16px", fontSize: 13, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>
              {t("bkCancelEdit")}
            </button>
            <button onClick={claim} disabled={busy}
              style={{ flex: 1, border: "none", background: busy ? C.pageSoft : C.green, color: "#fff", borderRadius: 11, padding: "12px", fontSize: 13.5, fontWeight: 700, cursor: busy ? "default" : "pointer", fontFamily: "inherit" }}>
              {busy ? t("bkSending") : t("bkFindBtn")}
            </button>
          </div>
        </div>
      )}

      {!mine && !closed && !full && !open && !finding && (
        <button onClick={() => setOpen(true)}
          style={{ width: "100%", border: "none", background: C.green, color: "#fff", borderRadius: 12, padding: "13px", fontSize: 14, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>
          {t("bkJoin")}
        </button>
      )}

      {open && (
        <div>
          <div style={{ fontSize: 11, color: C.muted, fontWeight: 700, marginBottom: 4 }}>{t("bkName")}</div>
          <input value={name} onChange={(e) => { setName(e.target.value); setErr(""); }}
            style={{ width: "100%", boxSizing: "border-box", border: `1px solid ${C.line}`, borderRadius: 10, padding: "11px", fontSize: 14, fontFamily: "inherit", background: "#fff", color: C.ink, marginBottom: 10 }} />
          <div style={{ fontSize: 11, color: C.muted, fontWeight: 700, marginBottom: 4 }}>
            {t("bkContact")} <span style={{ fontWeight: 500, textTransform: "lowercase" }}>· {t("bkOptional")}</span>
          </div>
          <input value={contact} onChange={(e) => { setContact(e.target.value); setErr(""); }}
            style={{ width: "100%", boxSizing: "border-box", border: `1px solid ${C.line}`, borderRadius: 10, padding: "11px", fontSize: 14, fontFamily: "inherit", background: "#fff", color: C.ink, marginBottom: 5 }} />
          <p style={{ fontSize: 11, color: C.muted, lineHeight: 1.5, margin: "0 0 10px" }}>{t("bkContactWhy")}</p>
          <div style={{ fontSize: 11, color: C.muted, fontWeight: 700, marginBottom: 4 }}>{t("bkPeople")}</div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(6, 1fr)", gap: 6, marginBottom: 11 }}>
            {[1, 2, 3, 4, 5, 6].map((n) => (
              <button key={n} onClick={() => setPeople(n)} disabled={spots > 0 && n > left + (editing ? (Number(mine.people) || 0) : 0)}
                style={{ flex: 1, border: `1px solid ${people === n ? C.green : C.line}`, background: people === n ? C.green : "#fff", color: people === n ? "#fff" : (spots > 0 && n > left ? C.faint : C.muted), borderRadius: 10, padding: "10px 0", fontSize: 14, fontWeight: 700, cursor: spots > 0 && n > left ? "default" : "pointer", fontFamily: "inherit" }}>{n}</button>
            ))}
          </div>
          <button onClick={() => setShowName(!showName)}
            style={{ width: "100%", textAlign: "left", background: "#fff", border: `1px solid ${C.line}`, borderRadius: 11, padding: "11px", display: "flex", gap: 10, alignItems: "center", cursor: "pointer", fontFamily: "inherit", marginBottom: 11 }}>
            <span style={{ width: 20, height: 20, borderRadius: 6, background: showName ? C.green : "#fff", border: `1.5px solid ${showName ? C.green : C.line}`, color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
              {showName && <ClipboardCheck size={12} />}
            </span>
            <span style={{ fontSize: 12.5, color: C.ink, lineHeight: 1.45 }}>{t("bkShowName")}</span>
          </button>
          <p style={{ fontSize: 11, color: C.muted, lineHeight: 1.5, margin: "0 0 12px" }}>{t("bkPrivacy")}</p>
          {err !== "" && <p style={{ fontSize: 12.5, color: C.rasp, margin: "0 0 10px", lineHeight: 1.45 }}>{err}</p>}
          <div style={{ display: "flex", gap: 8 }}>
            {editing && (
              <button onClick={() => { setEditing(false); setOpen(false); setErr(""); }}
                style={{ border: `1px solid ${C.line}`, background: "#fff", color: C.muted, borderRadius: 12, padding: "13px 16px", fontSize: 13.5, fontWeight: 700, cursor: "pointer", fontFamily: "inherit", flexShrink: 0 }}>
                {t("bkCancelEdit")}
              </button>
            )}
            <button onClick={editing ? saveEdit : submit} disabled={busy}
              style={{ flex: 1, border: "none", background: busy ? C.pageSoft : C.green, color: "#fff", borderRadius: 12, padding: "13px", fontSize: 14, fontWeight: 700, cursor: busy ? "default" : "pointer", fontFamily: "inherit" }}>
              {busy ? t("bkSending") : (editing ? t("bkSave") : t("bkConfirm"))}
            </button>
          </div>
        </div>
      )}

      {guests && guests.length > 0 && (
        <div style={{ marginTop: 16, paddingTop: 14, borderTop: `1px dashed ${C.greenLine}` }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 9 }}>
            <Users size={15} style={{ color: C.green }} />
            <span style={{ fontSize: 13, fontWeight: 800, color: C.ink }}>
              {t("bkGuests")} · {guests.reduce((a, g) => a + (Number(g.people) || 1), 0)}
            </span>
          </div>
          <div style={{ background: "#fff", borderRadius: 11, padding: "2px 12px" }}>
            {guests.map((g, i) => (
              <div key={i} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, padding: "9px 0", borderBottom: i === guests.length - 1 ? "none" : `1px solid ${C.line}` }}>
                <span style={{ fontSize: 13, color: g.name ? C.ink : C.muted }}>{g.name || t("bkGuestHidden")}</span>
                {Number(g.people) > 1 && (
                  <span style={{ fontSize: 11.5, color: C.muted }}>
                    {Number(g.people) === 2 ? t("bkPlusOne") : t("bkPlusMany").replace("{n}", String(Number(g.people) - 1))}
                  </span>
                )}
              </div>
            ))}
          </div>
          <p style={{ fontSize: 11, color: C.muted, margin: "8px 0 0" }}>{t("bkOnlyOrganizer")}</p>
        </div>
      )}
      {guests && guests.length === 0 && !done && !closed && !full && (
        <p style={{ fontSize: 12, color: C.muted, margin: "12px 0 0", lineHeight: 1.5 }}>{t("bkNobody")}</p>
      )}
    </>
  );
}

// ── Список записаних для організатора ────────────────────────────────
// Тут, і тільки тут, видно контакти. Плюс готовий текст для групи:
// одне повідомлення в Telegram чи WhatsApp накриває всіх одразу, і люди
// бачать його від організатора, а не від застосунку — можуть відповісти
// в тій самій розмові.
function OrganizerBookings({ trip, pin, onChanged }) {
  const [rows, setRows] = useState(null);
  const [err, setErr] = useState("");
  const [copied, setCopied] = useState("");
  const [editId, setEditId] = useState(null);
  const [adding, setAdding] = useState(false);
  const [draft, setDraft] = useState({ name: "", contact: "", people: 1 });

  // Раніше при порожньому PIN функція мовчки виходила, і на екрані
  // назавжди лишалось «Завантаження…» без жодного пояснення. Тепер
  // кожен стан має свій видимий текст — не доводиться гадати, чому
  // списку немає.
  const load = () => {
    if (!sbConfigured()) { setErr("Базу не налаштовано."); setRows([]); return; }
    if (!pin) { setErr("Введіть PIN організатора ще раз — без нього список не завантажується."); setRows([]); return; }
    setErr("");
    sbBookings(trip.id, pin)
      .then((r) => { setRows(r || []); setErr(""); })
      .catch((e) => { setRows([]); setErr("Не вдалося завантажити: " + String((e && e.message) || e).slice(0, 120)); });
  };
  useEffect(() => { load(); }, [trip.id, pin]);

  // Рахуємо лише підтверджені — так само, як це робить база.
  const total = (rows || []).filter((r) => r.status !== "pending" && r.status !== "declined")
    .reduce((a, r) => a + (Number(r.people) || 1), 0);

  const startEdit = (r) => {
    setAdding(false); setEditId(r.id);
    setDraft({ name: r.name || "", contact: r.contact || "", people: Number(r.people) || 1 });
    setErr("");
  };
  const startAdd = () => {
    setEditId(null); setAdding(true);
    setDraft({ name: "", contact: "", people: 1 });
    setErr("");
  };
  const save = async () => {
    if (String(draft.name).trim() === "") { setErr("Вкажіть імʼя."); return; }
    const n = Number(draft.people) || 1;
    try {
      if (adding) await sbAdminAddBooking(pin, trip.id, draft.name.trim(), draft.contact.trim(), n, true);
      else await sbAdminUpdateBooking(editId, pin, draft.name.trim(), draft.contact.trim(), n, true);
      setEditId(null); setAdding(false); load();
      if (onChanged) onChanged();
    } catch (e) {
      setErr("Не вдалося зберегти: " + String((e && e.message) || e).slice(0, 120));
    }
  };
  // Підтвердити або відхилити заявку. Раніше кнопки викликали функцію,
  // якої в цьому компоненті не існувало, — натискання не давало нічого.
  const applyStatus = async (id, status) => {
    setErr("");
    try {
      await sbSetBookingStatus(id, pin, status);
      load();
      if (onChanged) onChanged();
    } catch (e) {
      setErr("Не вдалося: " + String((e && e.message) || e).slice(0, 140));
    }
  };

  const remove = async (id) => {
    if (!window.confirm("Зняти цей запис? Місце звільниться для інших.")) return;
    try {
      await sbDeleteBooking(id, pin);
      load();
      if (onChanged) onChanged();
    } catch (e) { setErr("Не вдалося зняти: " + String((e && e.message) || e).slice(0, 120)); }
  };

  const copy = (text, tag) => {
    const done = () => { setCopied(tag); setTimeout(() => setCopied(""), 1800); };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done).catch(() => {});
    } else {
      const ta = document.createElement("textarea");
      ta.value = text; document.body.appendChild(ta); ta.select();
      try { document.execCommand("copy"); done(); } catch {}
      document.body.removeChild(ta);
    }
  };
  const listText = () => (rows || [])
    .map((r, i) => `${i + 1}. ${r.name}${Number(r.people) > 1 ? ` (${r.people})` : ""}${r.contact && r.contact.trim() !== "" ? ` — ${r.contact}` : ""}`)
    .join("\n");

  const inputStyle = { width: "100%", boxSizing: "border-box", border: `1px solid ${C.line}`, borderRadius: 9, padding: "9px 10px", fontSize: 13, fontFamily: "inherit", marginBottom: 7 };

  const form = (
    <div style={{ border: `1.5px solid ${C.rasp}`, background: C.raspSoft, borderRadius: 11, padding: 11, marginBottom: 10 }}>
      <div style={{ fontSize: 12, fontWeight: 800, color: C.rasp, marginBottom: 8 }}>
        {adding ? "Новий учасник" : "Редагування запису"}
      </div>
      <input value={draft.name} onChange={(e) => setDraft({ ...draft, name: e.target.value })} placeholder="Імʼя" style={{ ...inputStyle, background: "#fff" }} />
      <input value={draft.contact} onChange={(e) => setDraft({ ...draft, contact: e.target.value })} placeholder="Контакт (необовʼязково)" style={{ ...inputStyle, background: "#fff" }} />
      <div style={{ display: "grid", gridTemplateColumns: "repeat(6, 1fr)", gap: 5, marginBottom: 9 }}>
        {[1, 2, 3, 4, 5, 6].map((n) => (
          <button key={n} onClick={() => setDraft({ ...draft, people: n })}
            style={{ border: `1px solid ${draft.people === n ? C.rasp : C.line}`, background: draft.people === n ? C.rasp : "#fff", color: draft.people === n ? "#fff" : C.muted, borderRadius: 8, padding: "8px 0", fontSize: 13, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>{n}</button>
        ))}
      </div>
      <div style={{ display: "flex", gap: 7 }}>
        <button onClick={() => { setEditId(null); setAdding(false); setErr(""); }}
          style={{ border: `1px solid ${C.line}`, background: "#fff", color: C.muted, borderRadius: 9, padding: "9px 14px", fontSize: 12.5, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>Скасувати</button>
        <button onClick={save}
          style={{ flex: 1, border: "none", background: C.green, color: "#fff", borderRadius: 9, padding: "9px", fontSize: 12.5, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>Зберегти</button>
      </div>
    </div>
  );

  return (
    <div style={{ marginTop: 4, paddingBottom: 4 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 3 }}>
        <ClipboardCheck size={16} style={{ color: C.rasp, flexShrink: 0 }} />
        <span style={{ fontSize: 13, fontWeight: 800, color: C.ink, flex: 1 }}>
          Записалися · {total}{Number(trip.spots) > 0 ? ` з ${trip.spots}` : ""}
          {(rows || []).some((r) => r.status === "pending") && (
            <span style={{ fontSize: 11, fontWeight: 800, color: C.yellowInk, background: C.yellowSoft, padding: "2px 8px", borderRadius: 20, marginLeft: 7 }}>
              чекають: {(rows || []).filter((r) => r.status === "pending").length}
            </span>
          )}
        </span>
        <button onClick={load} style={{ border: "none", background: "none", color: C.green, fontSize: 11.5, fontWeight: 700, cursor: "pointer", fontFamily: "inherit", textDecoration: "underline" }}>оновити</button>
      </div>
      <p style={{ fontSize: 11.5, color: C.muted, margin: "0 0 11px" }}>
        {deadlineText(trip) ? (bookingClosed(trip) ? `Запис закрито ${deadlineText(trip)}` : `Запис до ${deadlineText(trip)}`) : "Дедлайн не встановлено"}
      </p>

      {err !== "" && (
        <div style={{ background: C.raspSoft, borderRadius: 10, padding: "10px 12px", marginBottom: 10, fontSize: 12, color: C.rasp, lineHeight: 1.5 }}>{err}</div>
      )}
      {rows === null && <p style={{ fontSize: 12.5, color: C.muted, margin: "0 0 10px" }}>Завантаження…</p>}
      {rows && rows.length === 0 && err === "" && <p style={{ fontSize: 12.5, color: C.muted, margin: "0 0 10px" }}>Поки ніхто не записався.</p>}

      {(adding || editId) && form}

      {rows && rows.length > 0 && (
        <div style={{ background: "#fff", borderRadius: 11, padding: "2px 12px", marginBottom: 10 }}>
          {rows.map((r, i) => (
            <div key={r.id} style={{ display: "flex", alignItems: "center", gap: 6, padding: "9px 0", borderBottom: i === rows.length - 1 ? "none" : `1px solid ${C.line}`, opacity: editId === r.id || r.status === "declined" ? 0.45 : 1 }}>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 13, color: C.ink, fontWeight: 600 }}>
                  {r.name}{Number(r.people) > 1 ? ` · ${r.people}` : ""}
                  {r.status === "pending" && (
                    <span style={{ fontSize: 10, fontWeight: 800, color: C.yellowInk, background: C.yellowSoft, padding: "2px 7px", borderRadius: 20, marginLeft: 6 }}>ЧЕКАЄ</span>
                  )}
                  {r.status === "declined" && (
                    <span style={{ fontSize: 10, fontWeight: 800, color: C.rasp, background: C.raspSoft, padding: "2px 7px", borderRadius: 20, marginLeft: 6 }}>ВІДХИЛЕНО</span>
                  )}
                  {!r.show_name && <span style={{ fontSize: 10.5, color: C.muted, fontWeight: 400 }}> (прихований)</span>}
                </div>
                <div style={{ fontSize: 12, color: r.contact && r.contact.trim() !== "" ? C.muted : C.faint, marginTop: 1 }}>
                  {r.contact && r.contact.trim() !== "" ? r.contact : "контакт не вказано"}
                </div>
              </div>
              {r.status === "pending" ? (
                <>
                  <button onClick={() => applyStatus(r.id, "confirmed")}
                    style={{ border: "none", background: C.green, color: "#fff", borderRadius: 8, padding: "7px 11px", fontSize: 11.5, fontWeight: 700, cursor: "pointer", fontFamily: "inherit", flexShrink: 0 }}>Прийняти</button>
                  <button onClick={() => applyStatus(r.id, "declined")}
                    style={{ border: `1px solid ${C.rasp}`, background: "#fff", color: C.rasp, borderRadius: 8, padding: "7px 11px", fontSize: 11.5, fontWeight: 700, cursor: "pointer", fontFamily: "inherit", flexShrink: 0 }}>Ні</button>
                </>
              ) : (
                <button onClick={() => startEdit(r)} aria-label="Змінити запис"
                  style={{ border: "none", background: "none", color: C.green, cursor: "pointer", padding: 6, display: "flex", flexShrink: 0 }}>
                  <Pencil size={15} />
                </button>
              )}
              <button onClick={() => remove(r.id)} aria-label="Зняти запис"
                style={{ border: "none", background: "none", color: C.rasp, cursor: "pointer", padding: 6, display: "flex", flexShrink: 0 }}>
                <Trash2 size={15} />
              </button>
            </div>
          ))}
        </div>
      )}

      <div style={{ display: "flex", gap: 8 }}>
        {!adding && !editId && (
          <button onClick={startAdd}
            style={{ flex: 1, border: `1.5px dashed ${C.rasp}`, background: C.raspSoft, color: C.rasp, borderRadius: 10, padding: "10px", fontSize: 12.5, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>
            + Додати учасника
          </button>
        )}
        {rows && rows.length > 0 && (
          <button onClick={() => copy(listText(), "list")}
            style={{ flex: 1, border: `1.5px solid ${C.green}`, background: "transparent", color: C.greenDark, borderRadius: 10, padding: "10px", fontSize: 12.5, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>
            {copied === "list" ? "Скопійовано ✓" : "Скопіювати список"}
          </button>
        )}
      </div>
    </div>
  );
}

// Сповіщення про зміну часу. Складається тут, а не в годиннику: лише
// застосунок знає, коли саме ви вирішили, що зміна варта розсилки.
function timeChangeMsgs(trip) {
  const out = {};
  const prev = CURRENT_LANG;
  for (const lang of ["uk", "en", "ru"]) {
    CURRENT_LANG = lang;
    const name = tc(trip.title);
    const when = tc(trip.dateLabel) || trip.date || "";
    out[lang] = {
      uk: { title: "Змінився час поїздки", body: `${name}, ${when}. Час відправлення та час зустрічі змінився. Перевірте інформацію ще раз.` },
      en: { title: "Trip times changed", body: `${name}, ${when}. The departure and meeting times have changed. Please check the details again.` },
      ru: { title: "Изменилось время поездки", body: `${name}, ${when}. Время отправления и время встречи изменилось. Проверьте информацию ещё раз.` },
    }[lang];
  }
  CURRENT_LANG = prev;
  return out;
}

// Вибір причини й кнопка розсилки. Показується лише коли поїздку
// перенесено або скасовано.
function SituationPush({ trip, kind, pin }) {
  const [reason, setReason] = useState("");
  const [busy, setBusy] = useState(false);
  const [done, setDone] = useState("");

  const send = async () => {
    if (reason === "") return;
    if (!window.confirm("Надіслати сповіщення всім, хто увімкнув сповіщення?")) return;
    setBusy(true); setDone("");
    try {
      const msgs = situationMsgs(kind, trip, reason, trip.postponedTo);
      const r = await pushSendMsgs(pin, msgs, `trip-${trip.id}`);
      setDone(`Надіслано: ${r.sent}${r.failed ? `, не вдалось ${r.failed}` : ""}`);
    } catch (e) {
      setDone("Помилка: " + String((e && e.message) || e).slice(0, 120));
    } finally { setBusy(false); }
  };

  const preview = reason !== "" ? situationMsgs(kind, trip, reason, trip.postponedTo).uk : null;

  return (
    <div style={{ border: `1.5px solid ${C.rasp}`, background: C.raspSoft, borderRadius: 12, padding: 12, marginBottom: 10 }}>
      <div style={{ fontSize: 12, fontWeight: 800, color: C.rasp, marginBottom: 8 }}>
        Причина {kind === "postponed" ? "перенесення" : "скасування"}
      </div>
      <div style={{ display: "grid", gap: 6, marginBottom: 10 }}>
        {REASONS.map((r) => (
          <button key={r.code} onClick={() => { setReason(r.code); setDone(""); }}
            style={{ textAlign: "left", border: `1px solid ${reason === r.code ? C.rasp : C.line}`, background: reason === r.code ? C.rasp : "#fff", color: reason === r.code ? "#fff" : C.ink, borderRadius: 9, padding: "10px 12px", fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>
            {{ personal: "Особисті обставини організатора", force: "Форс-мажор", weather: "Погода" }[r.code]}
          </button>
        ))}
      </div>
      {preview && (
        <div style={{ background: "#fff", borderRadius: 9, padding: 10, fontSize: 12, color: C.ink, lineHeight: 1.5, marginBottom: 10 }}>
          <div style={{ fontWeight: 800, marginBottom: 3 }}>{preview.title}</div>
          {preview.body}
        </div>
      )}
      <button onClick={send} disabled={reason === "" || busy}
        style={{ width: "100%", border: "none", background: reason === "" || busy ? C.pageSoft : C.green, color: "#fff", borderRadius: 10, padding: "12px", fontSize: 13.5, fontWeight: 700, cursor: reason === "" || busy ? "default" : "pointer", fontFamily: "inherit" }}>
        {busy ? "Надсилаю…" : "Повідомити учасників"}
      </button>
      {done !== "" && <p style={{ fontSize: 12, color: C.greenDark, margin: "8px 0 0" }}>{done}</p>}
      <p style={{ fontSize: 11, color: C.muted, margin: "8px 0 0", lineHeight: 1.5 }}>
        Сповіщення піде кожному своєю мовою. Надсилається лише після натискання — зміна стану сама нічого не розсилає.
      </p>
    </div>
  );
}

// ── Ситуативні сповіщення: перенесення й скасування ─────────────────
// Ці два не мають розкладу — їх запускає дія організатора. Тому текст
// збирається тут, у застосунку, а не в годиннику: лише тут відомо, яку
// причину щойно обрали.
const REASONS = [
  { code: "personal", tkey: "rsPersonal" },
  { code: "force", tkey: "rsForce" },
  { code: "weather", tkey: "rsWeather" },
];
// Дата й назва потрібні кожною мовою окремо, бо «Субота» німець не читає.
function situationMsgs(kind, trip, reasonCode, newDate) {
  const reason = REASONS.find((r) => r.code === reasonCode);
  const out = {};
  const prev = CURRENT_LANG;
  for (const lang of ["uk", "en", "ru"]) {
    CURRENT_LANG = lang;
    const name = tc(trip.title);
    const when = tc(trip.dateLabel) || trip.date || "";
    const why = reason ? t(reason.tkey) : "";
    const to = String(newDate || "").trim();
    out[lang] = kind === "postponed"
      ? {
          uk: { title: "Поїздку перенесено", body: `Поїздка на ${when} до ${name} через ${why} переноситься${to ? ` на ${to}` : ""}. Для додаткової інформації зверніться до організатора.` },
          en: { title: "Trip postponed", body: `The trip to ${name} on ${when} is postponed due to ${why}${to ? `, new date: ${to}` : ""}. Contact the organiser for details.` },
          ru: { title: "Поездка перенесена", body: `Поездка на ${when} до ${name} из-за ${why} переносится${to ? ` на ${to}` : ""}. За дополнительной информацией обратитесь к организатору.` },
        }[lang]
      : {
          uk: { title: "Поїздку скасовано", body: `Поїздка на ${when} до ${name} через ${why} відміняється. Просимо вибачення за незручності!` },
          en: { title: "Trip cancelled", body: `The trip to ${name} on ${when} is cancelled due to ${why}. We apologise for the inconvenience!` },
          ru: { title: "Поездка отменена", body: `Поездка на ${when} до ${name} из-за ${why} отменяется. Приносим извинения за неудобства!` },
        }[lang];
  }
  CURRENT_LANG = prev;
  return out;
}

// ── Перевірка сповіщень (режим організатора) ────────────────────────
// Кнопка навмисно показує СИРУ відповідь сервера, а не «щось пішло не
// так». Push проходить через шість ланок: дозвіл у браузері, фоновий
// скрипт, підписка в базі, ключі у Vercel, серверна функція і сам
// push-сервер Google чи Apple. Здогадуватись, яка з них мовчить, — це
// щоразу година навмання. Відповідь називає ланку одразу.
function PushDiagnostics({ pin, trip }) {
  const [state, setState] = useState("");
  const [busy, setBusy] = useState(false);
  const [subs, setSubs] = useState(null);
  const [beat, setBeat] = useState(null);
  const [mine, setMine] = useState(null); // true | false | null (невідомо)

  useEffect(() => {
    if (!sbConfigured()) return;
    sbRpc("push_count", {}).then((n) => setSubs(Number(n) || 0)).catch(() => setSubs(-1));
    if (pin) sbRpc("cron_last", { pin }).then(setBeat).catch(() => setBeat({ last_run: null }));
    checkMine();
  }, [pin]);

  // Чи позначений САМЕ цей пристрій як пристрій організатора. Сповіщення
  // про нові заявки йдуть лише на нього, тож без позначки вони просто
  // нікуди не надсилаються — і досі це відбувалось мовчки.
  const checkMine = async () => {
    if (!pushSupported() || !sbConfigured() || !pin) { setMine(null); return; }
    try {
      const reg = await navigator.serviceWorker.ready;
      const sub = await reg.pushManager.getSubscription();
      if (!sub) { setMine(false); return; }
      const r = await sbRpc("push_is_admin", { p_endpoint: sub.toJSON().endpoint, pin });
      setMine(r === true);
    } catch (e) { setMine(null); }
  };
  const markMine = async () => {
    try { await sbMarkAdminDevice(pin); await checkMine(); }
    catch (e) { setState("Не вдалося позначити: " + String((e && e.message) || e).slice(0, 120)); }
  };

  // Пульс годинника. Це головна відповідь на питання «чому не приходять
  // сповіщення за розкладом»: якщо годинник мовчить, справа не в текстах.
  const beatLine = () => {
    if (!beat) return "…";
    if (!beat.last_run) return "жодного разу — cron-job.org не викликає адресу";
    const d = new Date(beat.last_run);
    const minAgo = Math.round((Date.now() - d.getTime()) / 60000);
    const when = d.toLocaleString("uk-UA", { timeZone: "Europe/Berlin", hour: "2-digit", minute: "2-digit", day: "2-digit", month: "2-digit" });
    return `${when} (${minAgo} хв тому)${minAgo > 40 ? " — ЗАДОВГО, годинник стоїть" : ""}`;
  };

  const sendTimeChange = async () => {
    if (!window.confirm("Надіслати всім сповіщення про зміну часу?")) return;
    setBusy(true); setState("");
    try {
      const r = await pushSendMsgs(pin, timeChangeMsgs(trip), `trip-${trip.id}`);
      setState(`Про зміну часу: надіслано ${r.sent}${r.failed ? `, не вдалось ${r.failed}` : ""}`);
    } catch (e) {
      setState("Помилка: " + String((e && e.message) || e).slice(0, 200));
    } finally { setBusy(false); }
  };

  const test = async () => {
    setBusy(true); setState("");
    const lines = [];
    lines.push(`Підписок у базі: ${subs === null ? "…" : subs === -1 ? "не вдалося прочитати (немає функції push_count?)" : subs}`);
    lines.push(`Дозвіл у цьому браузері: ${typeof Notification === "undefined" ? "не підтримується" : Notification.permission}`);
    try {
      const reg = await navigator.serviceWorker.getRegistration();
      lines.push(`Фоновий скрипт: ${reg ? "зареєстровано" : "НЕМАЄ — перевірте, що sw.js лежить у папці public"}`);
      const sub = reg ? await reg.pushManager.getSubscription() : null;
      lines.push(`Підписка цього пристрою: ${sub ? "є" : "немає"}`);
    } catch (e) {
      lines.push(`Фоновий скрипт: помилка — ${String(e.message || e)}`);
    }
    try {
      const r = await pushSend(pin, "Перевірка сповіщень", "Якщо ви це бачите — усе працює.", "/", "test");
      lines.push(`Сервер відповів: надіслано ${r.sent}, не вдалось ${r.failed}${r.removed ? `, прибрано мертвих ${r.removed}` : ""}${r.note ? ` (${r.note})` : ""}`);
    } catch (e) {
      lines.push(`ПОМИЛКА СЕРВЕРА: ${String(e.message || e).slice(0, 220)}`);
    }
    setState(lines.join("\n"));
    setBusy(false);
  };

  return (
    <div style={{ marginTop: 14, paddingTop: 14, borderTop: `1px solid ${C.line}` }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 9 }}>
        <Signal size={16} style={{ color: C.rasp, flexShrink: 0 }} />
        <span style={{ fontSize: 13, fontWeight: 800, color: C.ink, flex: 1 }}>Сповіщення</span>
        <span style={{ fontSize: 11.5, color: C.muted }}>
          {subs === null ? "…" : subs === -1 ? "?" : `${subs} підписок`}
        </span>
      </div>
      <div style={{ background: (beat && beat.last_run) ? C.greenSoft : C.raspSoft, borderRadius: 10, padding: "9px 11px", marginBottom: 10 }}>
        <div style={{ fontSize: 11, fontWeight: 800, color: C.muted, textTransform: "uppercase", letterSpacing: 0.4, marginBottom: 3 }}>Годинник озивався</div>
        <div style={{ fontSize: 12.5, color: (beat && beat.last_run) ? C.greenDark : C.rasp, lineHeight: 1.45 }}>{beatLine()}</div>
      </div>
      <div style={{ background: mine === true ? C.greenSoft : C.raspSoft, borderRadius: 10, padding: "9px 11px", marginBottom: 10, display: "flex", alignItems: "center", gap: 9 }}>
        <span style={{ flex: 1, fontSize: 12, color: mine === true ? C.greenDark : C.rasp, lineHeight: 1.45 }}>
          {mine === true
            ? "Сповіщення про нові заявки приходять на цей пристрій"
            : mine === false
              ? "Цей пристрій НЕ позначений — сповіщення про заявки нікуди не йдуть"
              : "Позначку пристрою не вдалося перевірити"}
        </span>
        {mine !== true && (
          <button onClick={markMine}
            style={{ border: `1px solid ${C.rasp}`, background: "#fff", color: C.rasp, borderRadius: 8, padding: "7px 12px", fontSize: 11.5, fontWeight: 700, cursor: "pointer", fontFamily: "inherit", flexShrink: 0 }}>
            Позначити
          </button>
        )}
      </div>
      <button onClick={test} disabled={busy}
        style={{ width: "100%", border: `1.5px solid ${C.green}`, background: busy ? C.greenSoft : "transparent", color: C.greenDark, borderRadius: 10, padding: "11px", fontSize: 12.5, fontWeight: 700, cursor: busy ? "default" : "pointer", fontFamily: "inherit" }}>
        {busy ? "Перевіряю…" : "Надіслати тестове сповіщення"}
      </button>
      {/* Розсилка про зміну часу. Кнопкою, а не автоматично при правці
          поля: під час редагування час міняється кілька разів, і кожна
          проміжна правка підняла б тривогу всій групі. Момент, коли
          зміна остаточна, знаєте тільки ви. */}
      {trip && (
        <div style={{ marginTop: 10, border: `1px solid ${C.line}`, borderRadius: 10, padding: 11, background: "#fff" }}>
          <div style={{ fontSize: 12, fontWeight: 800, color: C.ink, marginBottom: 6 }}>Змінився час</div>
          <p style={{ fontSize: 11.5, color: C.muted, lineHeight: 1.5, margin: "0 0 9px" }}>
            Надішліть, коли поправили час відправлення або час збору й хочете, щоб усі перевірили розклад.
          </p>
          <button onClick={sendTimeChange} disabled={busy}
            style={{ width: "100%", border: `1.5px solid ${C.yellowInk}`, background: busy ? C.pageSoft : C.yellowSoft, color: C.yellowInk, borderRadius: 10, padding: "11px", fontSize: 12.5, fontWeight: 700, cursor: busy ? "default" : "pointer", fontFamily: "inherit" }}>
            {busy ? "Надсилаю…" : "Повідомити про зміну часу"}
          </button>
        </div>
      )}
      {state !== "" && (
        <pre style={{ marginTop: 10, background: "#fff", border: `1px solid ${C.line}`, borderRadius: 10, padding: 11, fontSize: 11, color: C.ink, lineHeight: 1.6, whiteSpace: "pre-wrap", fontFamily: "inherit", margin: "10px 0 0" }}>{state}</pre>
      )}
      <p style={{ fontSize: 11, color: C.muted, lineHeight: 1.5, margin: "9px 0 0" }}>
        Сповіщення отримають усі, хто його увімкнув, включно з вами.
      </p>
    </div>
  );
}

// ── Detail view ────────────────────────────────────────────────────────
function TripDetail({ trip, onBack, isAdmin, onEdit, onDelete, onSetStatus, onSetPostponedDate, counts, onBooked, adminPin }) {
  // Одразу показуємо першу точку з координатами, щоб у розділі «Маршрут»
  // карта була видна без зайвого натискання (цю роль раніше виконувала
  // верхня оглядова карта, яку прибрано).
  // Обрана бонусна точка. Окремий стан, а не спільний з routeSel: так
  // ніщо в уже робочому списку маршруту не змінюється. Вибір одного
  // знімає вибір іншого — на карті завжди рівно одна точка.
  const [bonusSel, setBonusSel] = useState(null);
  // Показуємо лише заповнені місця — і в списку, і на карті, щоб індекси
  // збігались і вибір не «з'їжджав» на сусідній пункт.
  const bonusPts = (trip.bonus || []).filter(bonusFilled);
  const [routeSel, setRouteSel] = useState(() => {
    const i = (trip.route || []).findIndex((s) => !isNaN(parseFloat(s.lat)) && !isNaN(parseFloat(s.lng)));
    return i >= 0 ? i : null;
  });
  const taken = takenOf(trip, counts);
  const left = Math.max(0, (Number(trip.spots) || 0) - taken);
  const Section = ({ icon, title, children, accent = C.green }) => (
    <div style={{ background: C.card, borderRadius: 18, padding: 18, marginBottom: 14, boxShadow: "0 2px 12px rgba(60,79,44,0.06)" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 9, marginBottom: 14 }}>
        <div style={{ width: 32, height: 32, borderRadius: 10, background: accent + "16", color: accent, display: "flex", alignItems: "center", justifyContent: "center" }}>{icon}</div>
        <h3 style={{ margin: 0, fontSize: 15.5, fontWeight: 700, color: C.ink }}>{title}</h3>
      </div>
      {children}
    </div>
  );

  return (
    <div style={{ paddingBottom: 30 }}>
      {/* На айфоні верх екрана зайнятий вирізом і рядком стану. Без
          відступу env(safe-area-inset-top) кнопка «Усі поїздки» лізла
          під годинник — саме це видно на скріншоті. На Android відступ
          дорівнює нулю, тож нічого не змінюється. */}
      <div style={{ background: trip.heroGradient, padding: "calc(16px + env(safe-area-inset-top)) 18px 26px", color: "#fff", position: "relative" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <button onClick={onBack} style={{ background: "rgba(255,255,255,0.2)", border: "none", color: "#fff", borderRadius: 12, padding: "8px 12px", display: "flex", alignItems: "center", gap: 6, cursor: "pointer", fontSize: 13.5, fontWeight: 600 }}>
            <ArrowLeft size={16} /> {t("allTrips")}
          </button>
          {isAdmin && (
            <button onClick={onEdit} style={{ background: "rgba(255,255,255,0.22)", border: "none", color: "#fff", borderRadius: 12, padding: "8px 12px", display: "flex", alignItems: "center", gap: 6, cursor: "pointer", fontSize: 13.5, fontWeight: 700 }}>
              <Pencil size={15} /> {t("edit")}
            </button>
          )}
        </div>
        <div style={{ marginTop: 22 }}>
          <span style={{ background: "rgba(255,255,255,0.22)", padding: "5px 12px", borderRadius: 20, fontSize: 12, fontWeight: 600 }}>{dateWithWeekday(trip)}</span>
          <h1 style={{ margin: "12px 0 4px", fontSize: 30, fontWeight: 800, letterSpacing: -0.6, lineHeight: 1.05 }}>{tc(trip.title)}</h1>
          <p style={{ margin: 0, fontSize: 14.5, opacity: 0.93 }}>{tc(trip.subtitle)}</p>
        </div>
      </div>

      <div style={{ padding: "18px 16px 0", marginTop: -14, background: C.page, borderRadius: "20px 20px 0 0", position: "relative" }}>
        <PlacePhoto trip={trip} />
        {(() => {
          const sv = trip.statsVisible || {};
          // default: distance/ascent/duration shown, descent shown only if set
          const items = [
            { key: "distance", show: sv.distance !== false, label: t("statDistance"), value: `${trip.distanceKm} ${t("unitKm")}`, icon: <Footprints size={17} /> },
            { key: "ascent", show: sv.ascent !== false, label: t("statAscent"), value: `${trip.ascentM} ${t("unitM")}`, icon: <TrendingUp size={17} /> },
            { key: "descent", show: sv.descent === true, label: t("statDescent"), value: `${trip.descentM || 0} ${t("unitM")}`, icon: <TrendingDown size={17} /> },
            { key: "duration", show: sv.duration !== false, label: t("statDuration"), value: durationText(trip.durationHrs), icon: <Clock size={17} /> },
          ].filter((s) => s.show);
          if (items.length === 0) return null;
          // 3 or fewer → single row; 4 → 2×2 grid
          const cols = items.length >= 4 ? 2 : items.length;
          return (
            <div style={{ display: "grid", gridTemplateColumns: `repeat(${cols},1fr)`, gap: 10, marginBottom: 14 }}>
              {items.map((s) => (
                <div key={s.key} style={{ background: C.card, borderRadius: 14, padding: "13px 10px", textAlign: "center", boxShadow: "0 2px 10px rgba(60,79,44,0.05)" }}>
                  <div style={{ color: C.green, display: "flex", justifyContent: "center", marginBottom: 5 }}>{s.icon}</div>
                  <div style={{ fontSize: 15, fontWeight: 800, color: C.ink }}>{s.value}</div>
                  <div style={{ fontSize: 11, color: C.muted, marginTop: 1 }}>{s.label}</div>
                </div>
              ))}
            </div>
          );
        })()}

        {resolveSections(trip).filter((s) => s.visible !== false).map((sec) => {
          const renderers = {
            booking: {
              icon: <ClipboardCheck size={17} />, accent: C.green,
              body: <BookingSection trip={trip} taken={taken} onBooked={onBooked} />,
            },
            about: {
              icon: <Info size={17} />, accent: C.green,
              body: <p style={{ margin: 0, fontSize: 14, lineHeight: 1.6, color: "#4a4a42" }}>{tc(trip.about)}</p>,
            },
            difficulty: {
              icon: <Signal size={17} />, accent: diffColor(trip.difficulty),
              body: (
                <>
                  <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 13 }}>
                    <div style={{ display: "flex", gap: 5 }}>
                      {["Легкий", "Середній", "Складний"].map((lvl, i) => {
                        const order = { "Легкий": 0, "Середній": 1, "Складний": 2 };
                        const active = i <= order[trip.difficulty];
                        const barColor = [C.green, C.yellow, C.rasp][i];
                        return <div key={lvl} style={{ width: 34, height: 8, borderRadius: 6, background: active ? barColor : C.line }} />;
                      })}
                    </div>
                    <span style={{ fontSize: 15, fontWeight: 800, color: diffColor(trip.difficulty) }}>{diffLabel(trip.difficulty)}</span>
                  </div>
                  <p style={{ margin: 0, fontSize: 13.5, lineHeight: 1.55, color: "#4a4a42" }}>{tc(trip.difficultyNote)}</p>
                </>
              ),
            },
            weather: {
              icon: weatherIcon(trip.weather.icon, 17), accent: C.green,
              body: <LiveWeather trip={trip} isAdmin={isAdmin} />,
            },
            travel: {
              icon: <Train size={17} />, accent: C.rasp,
              body: (
                <>
                  {tripJourneys(trip).some((j) => filledLegs(j).length > 0) ? (
                    <>
                      {/* Кожне відправлення — окрема картка. Учасник
                          розгортає лише те, що стосується його міста. */}
                      <div style={{ display: "grid", gap: 10 }}>
                        {tripJourneys(trip)
                          .filter((j) => filledLegs(j).length > 0)
                          .map((j, i) => <TrainLegs key={i} legs={j.legs} />)}
                      </div>
                      {/* Список поїздів веде організатор вручну, тож у ньому
                          є лише ті міста, які він вніс. Підказка потрібна,
                          щоб людина з іншого міста знала, що робити. */}
                      {!isAdmin && (
                        <p style={{ fontSize: 11, color: C.muted, lineHeight: 1.45, margin: "8px 2px 0" }}>
                          {t("travelCityNote")}
                        </p>
                      )}
                    </>
                  ) : (
                    <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                      <div style={{ flex: 1, textAlign: "center" }}>
                        <div style={{ fontSize: 20, fontWeight: 800, color: C.ink }}>{trip.from.time}</div>
                        <div style={{ fontSize: 12.5, color: C.inkSoft, marginTop: 2 }}>{trip.from.name}</div>
                        <div style={{ fontSize: 11, color: C.rasp, fontWeight: 600, marginTop: 2 }}>{trip.from.platform}</div>
                      </div>
                      <div style={{ flex: 1.2, textAlign: "center", color: C.faint }}>
                        <div style={{ display: "inline-block", fontSize: 11, fontWeight: 800, color: C.yellowInk, background: C.yellow, padding: "3px 10px", borderRadius: 20, marginBottom: 5 }}>{trip.trainLine}</div>
                        <div style={{ display: "flex", alignItems: "center", gap: 3, justifyContent: "center" }}>
                          <span style={{ height: 2, flex: 1, background: C.line }} />
                          <Train size={15} />
                          <span style={{ height: 2, flex: 1, background: C.line }} />
                        </div>
                      </div>
                      <div style={{ flex: 1, textAlign: "center" }}>
                        <div style={{ fontSize: 20, fontWeight: 800, color: C.ink }}>{trip.to.time}</div>
                        <div style={{ fontSize: 12.5, color: C.inkSoft, marginTop: 2 }}>{trip.to.name}</div>
                      </div>
                    </div>
                  )}
                  {/* Зворотній поїзд навмисно спрощений: одна година без
                      станцій і пересадок. Час назад щоразу різний, тож
                      докладний ланцюжок лише вводив би в оману. */}
                  {(String(trip.returnTime || "").trim() !== "" || String(trip.returnFrom || "").trim() !== "") && (
                    <div style={{ marginTop: 10, border: `1px solid ${C.greenLine}`, borderRadius: 13, padding: 13, background: "#fff" }}>
                      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                        <span style={{ width: 32, height: 32, borderRadius: 10, background: C.greenSoft, color: C.greenDark, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, transform: "scaleX(-1)" }}>
                          <Train size={16} />
                        </span>
                        <span style={{ flex: 1, minWidth: 0 }}>
                          <span style={{ display: "block", fontSize: 12, color: C.muted, fontWeight: 700 }}>{t("retTitle")}</span>
                          {/* Збираємо рядок із окремих полів, а не з вільного
                              тексту. Слово «колія» береться зі словника
                              застосунку — те саме, що в розкладі поїздів.
                              Машинний переклад тут не потрібен узагалі. */}
                          <span style={{ display: "block", fontSize: 14.5, fontWeight: 700, color: C.ink, marginTop: 2, lineHeight: 1.4 }}>
                            {[String(trip.returnFrom || "").trim(), tc(trip.returnTime).trim()]
                              .filter((x) => x !== "").join(", ")}
                            {String(trip.returnPlatform || "").trim() !== "" && (
                              <span style={{ color: C.ink, fontWeight: 700 }}>
                                , {t("jpTrack")} {String(trip.returnPlatform).trim()}
                              </span>
                            )}
                          </span>
                        </span>
                      </div>
                      <p style={{ fontSize: 11, color: C.muted, lineHeight: 1.5, margin: "9px 0 0" }}>{t("retNote")}</p>
                    </div>
                  )}
                  <div style={{ marginTop: 8, padding: 11, background: C.yellowSoft, borderRadius: 11, fontSize: 12.5, color: C.yellowInk, display: "flex", gap: 7, alignItems: "flex-start" }}>
                    <Train size={15} style={{ flexShrink: 0, marginTop: 1 }} />
                    <span>{t("dTicket")} <b>Deutschland Ticket</b> <b>63 €</b> {t("dTicketTail")}</span>
                  </div>
                  <div style={{ marginTop: 8, padding: 11, background: C.yellowSoft, borderRadius: 11, fontSize: 12.5, color: C.yellowInk, display: "flex", gap: 7, alignItems: "flex-start" }}>
                    <Train size={15} style={{ flexShrink: 0, marginTop: 1 }} />
                    <span><b>Bayern Ticket 34 €</b> {t("bTicketTail")}</span>
                  </div>
                  {!isAdmin && <DbScheduleLink trip={trip} />}
                </>
              ),
            },
            meeting: {
              icon: <MapPin size={17} />, accent: C.green,
              body: (
                <>
                  {trip.coords && <div style={{ marginBottom: 12 }}><MeetingMap lat={trip.coords.lat} lng={trip.coords.lng} /></div>}
                  <div style={{ padding: 13, background: C.greenSoft, borderRadius: 12, display: "flex", gap: 10, alignItems: "flex-start" }}>
                    <div style={{ color: C.green, marginTop: 1 }}><MapPin size={18} /></div>
                    <div style={{ flex: 1 }}>
                      <div style={{ fontSize: 13.5, fontWeight: 700, color: C.ink, marginBottom: 3 }}>{t("meetingPlace")}</div>
                      <div style={{ fontSize: 13, color: C.inkSoft, lineHeight: 1.45 }}>
                        {tc(trip.meetingPoint) && tc(trip.meetingPoint).trim() !== "" ? tc(trip.meetingPoint) : `${tc(trip.route[0]?.name) || trip.from.name}`}
                      </div>
                    </div>
                  </div>
                  {trip.coords && (
                    <a href={gmapsUrl(trip.coords.lat, trip.coords.lng)} target="_blank" rel="noreferrer"
                      style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 7, marginTop: 10, background: C.green, color: "#fff", borderRadius: 11, padding: "13px", fontSize: 14, fontWeight: 700, textDecoration: "none" }}>
                      <Navigation size={17} /> {t("openGeo")}
                    </a>
                  )}
                </>
              ),
            },
            route: {
              icon: <Mountain size={17} />, accent: C.green,
              body: (
                <>
                  {/* Верхню оглядову карту прибрано: вона не реагувала на вибір
                      точки в списку нижче і дублювала робочу карту. Лишилась
                      тільки кнопка на повний маршрут у Komoot/Bergfex. */}
                  {trip.routeUrl && trip.routeUrl.trim() !== "" && (
                    <a href={trip.routeUrl} target="_blank" rel="noreferrer"
                      style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 7, marginBottom: 14, background: C.green, color: "#fff", borderRadius: 11, padding: "12px", fontSize: 13.5, fontWeight: 700, textDecoration: "none" }}>
                      <Navigation size={16} /> {t("openFullRoute")}
                    </a>
                  )}
                {(() => {
                  // Одна карта на обидва списки: показує ту точку, яку
                  // щойно натиснули — чи то з маршруту, чи то бонусну.
                  const isBonus = bonusSel != null;
                  const sel = isBonus ? bonusPts[bonusSel] : (routeSel != null ? trip.route[routeSel] : null);
                  const la = parseFloat(sel && sel.lat), ln = parseFloat(sel && sel.lng);
                  if (!sel || isNaN(la) || isNaN(ln)) return null;
                  return (
                    <div style={{ marginBottom: 14 }}>
                      <MeetingMap lat={la} lng={ln} accent={isBonus ? "bonus" : undefined} />
                      <p style={{ fontSize: 11.5, color: isBonus ? C.yellowInk : C.muted, fontWeight: isBonus ? 700 : 400, margin: "6px 0 0" }}>{tc(sel.name)}</p>
                    </div>
                  );
                })()}
                <div style={{ position: "relative", paddingLeft: 4 }}>
                  {trip.route.map((step, i) => {
                    const hasGeo = !isNaN(parseFloat(step.lat)) && !isNaN(parseFloat(step.lng));
                    const active = routeSel === i;
                    return (
                    <div key={i}
                      onClick={() => { if (hasGeo) { setRouteSel(active ? null : i); setBonusSel(null); } }}
                      style={{ display: "flex", gap: 13, paddingBottom: i === trip.route.length - 1 ? 0 : 18, position: "relative", cursor: hasGeo ? "pointer" : "default" }}>
                      {i !== trip.route.length - 1 && <div style={{ position: "absolute", left: 9, top: 22, bottom: 0, width: 2, background: C.greenLine }} />}
                      <div style={{ width: 20, height: 20, borderRadius: 20, background: active ? C.green : "#fff", border: `2px solid ${active ? C.green : C.greenLine}`, flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", marginTop: 1, zIndex: 1 }}>
                        {active && <span style={{ width: 6, height: 6, borderRadius: 6, background: "#fff" }} />}
                      </div>
                      <div style={{ flex: 1 }}>
                        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
                          <span style={{ fontSize: 14, fontWeight: 700, color: active ? C.greenDark : C.ink }}>{tc(step.name)}</span>
                          <span style={{ fontSize: 12, color: C.rasp, fontWeight: 600 }}>{step.t}</span>
                        </div>
                        <div style={{ fontSize: 12.5, color: "#7a766a", marginTop: 2 }}>{tc(step.note)}</div>
                        {/* Практична інформація — ціна входу, години роботи,
                            подія того дня. Винесена в окрему плашку, щоб не
                            загубитись серед опису точки. */}
                        {tc(step.info) && tc(step.info).trim() !== "" && (
                          <div style={{ display: "flex", gap: 6, alignItems: "flex-start", marginTop: 6, padding: "7px 10px", background: C.yellowSoft, borderRadius: 9, fontSize: 12, color: C.yellowInk, lineHeight: 1.45 }}>
                            <Info size={13} style={{ flexShrink: 0, marginTop: 1.5 }} />
                            <span style={{ whiteSpace: "pre-wrap" }}>{tc(step.info)}</span>
                          </div>
                        )}
                        {hasGeo && !active && <div style={{ fontSize: 11, color: C.green, fontWeight: 600, marginTop: 3 }}>{t("tapToMap")}</div>}
                      </div>
                    </div>
                    );
                  })}
                  {trip.route.length === 0 && <p style={{ margin: 0, fontSize: 13, color: C.muted }}>{t("routeTbd")}</p>}
                </div>
                {/* Бонусні місця. Свідомо стоять ОКРЕМО від таймлайну і без
                    з'єднувальної лінії: вони не є частиною маршруту, а лише
                    пропозиції поруч. Обране підсвічується жовтим — тим самим
                    кольором, що й шпилька на карті. */}
                {bonusPts.length > 0 && (
                  <div style={{ marginTop: 20, paddingTop: 16, borderTop: `1px dashed ${C.greenLine}` }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 3 }}>
                      <MapPin size={15} style={{ color: C.yellowInk }} />
                      <span style={{ fontSize: 13, fontWeight: 800, color: C.yellowInk }}>{t("bonusTitle")}</span>
                    </div>
                    <p style={{ fontSize: 11.5, color: C.muted, margin: "0 0 11px", lineHeight: 1.4 }}>{t("bonusHint")}</p>
                    <div style={{ display: "grid", gap: 8 }}>
                      {bonusPts.map((b, i) => {
                        const hasGeo = !isNaN(parseFloat(b.lat)) && !isNaN(parseFloat(b.lng));
                        const active = bonusSel === i;
                        return (
                          <div key={i}
                            onClick={() => { if (hasGeo) { setBonusSel(active ? null : i); setRouteSel(null); } }}
                            style={{
                              display: "flex", gap: 11, alignItems: "flex-start", padding: "11px 12px", borderRadius: 12,
                              background: active ? C.yellowSoft : "#fff",
                              border: `1.5px solid ${active ? C.yellow : C.line}`,
                              cursor: hasGeo ? "pointer" : "default",
                            }}>
                            <div style={{ width: 26, height: 26, borderRadius: 9, flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", background: active ? C.yellow : C.yellowSoft, color: C.yellowInk }}>
                              <MapPin size={14} />
                            </div>
                            <div style={{ flex: 1, minWidth: 0 }}>
                              <div style={{ fontSize: 14, fontWeight: 700, color: active ? C.yellowInk : C.ink }}>{tc(b.name)}</div>
                              {tc(b.note) && <div style={{ fontSize: 12.5, color: "#7a766a", marginTop: 2, lineHeight: 1.4 }}>{tc(b.note)}</div>}
                              {hasGeo && !active && <div style={{ fontSize: 11, color: C.yellowInk, fontWeight: 700, marginTop: 3 }}>{t("tapToMap")}</div>}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                )}
                </>
              ),
            },
            cafes: {
              icon: <Coffee size={17} />, accent: C.rasp,
              body: (
                <>
                  {trip.cafes.map((c, i) => (
                    <div key={i} style={{ display: "flex", gap: 11, alignItems: "flex-start", padding: "10px 0", borderBottom: i === trip.cafes.length - 1 ? "none" : `1px solid ${C.line}` }}>
                      <div style={{ width: 30, height: 30, borderRadius: 9, background: C.raspSoft, color: C.rasp, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><Coffee size={15} /></div>
                      <div style={{ flex: 1 }}>
                        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 8 }}>
                          <span style={{ fontSize: 14, fontWeight: 700, color: C.ink }}>{tc(c.name)}</span>
                          {cafeTag(c.tag) && <span style={{ fontSize: 10.5, color: C.rasp, background: C.raspSoft, padding: "3px 8px", borderRadius: 20, fontWeight: 600, whiteSpace: "nowrap" }}>{cafeTag(c.tag)}</span>}
                        </div>
                        <div style={{ fontSize: 12.5, color: "#7a766a", marginTop: 2 }}>{tc(c.note)}</div>
                      </div>
                    </div>
                  ))}
                  {trip.cafes.length === 0 && <p style={{ margin: 0, fontSize: 13, color: C.muted }}>{t("listTbd")}</p>}
                </>
              ),
            },
            packing: {
              icon: <ClipboardCheck size={17} />, accent: C.green,
              body: (
                <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                  {trip.packing.map((p, i) => (
                    <span key={i} style={{ fontSize: 12.5, color: C.greenDark, background: C.greenSoft, padding: "7px 12px", borderRadius: 20, fontWeight: 500 }}>{tc(p)}</span>
                  ))}
                  {trip.packing.length === 0 && <span style={{ fontSize: 13, color: C.muted }}>{t("listTbd")}</span>}
                </div>
              ),
            },
            drive: {
              icon: <Camera size={17} />, accent: C.green,
              body: (() => {
                const url = (trip.driveUrl && String(trip.driveUrl).trim() !== "") ? String(trip.driveUrl).trim() : DRIVE_URL;
                return (
                  <>
                    <p style={{ margin: "0 0 13px", fontSize: 13.5, color: C.inkSoft, lineHeight: 1.5 }}>{t("driveNote")}</p>
                    <a href={url} target="_blank" rel="noreferrer"
                      style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8, background: C.green, color: "#fff", borderRadius: 12, padding: "13px", fontSize: 13.5, fontWeight: 700, textDecoration: "none" }}>
                      <Camera size={16} /> {t("driveButton")}
                    </a>
                  </>
                );
              })(),
            },
            contact: {
              icon: <MessageCircle size={17} />, accent: C.rasp,
              body: (() => {
                // Support either a `contacts` array (new) or a single legacy
                // `contact` object (backward compatible).
                const list = (trip.contacts && trip.contacts.length > 0)
                  ? trip.contacts
                  : (trip.contact ? [trip.contact] : []);
                if (list.length === 0) return <p style={{ margin: 0, fontSize: 13, color: C.muted }}>—</p>;
                return (
                  <div style={{ display: "grid", gap: 16 }}>
                    {list.map((person, idx) => (
                      <div key={idx} style={idx > 0 ? { paddingTop: 16, borderTop: `1px solid ${C.line}` } : {}}>
                        <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 14 }}>
                          <div style={{ width: 46, height: 46, borderRadius: 14, background: C.green, color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 19, fontWeight: 800, flexShrink: 0 }}>
                            {(person.name || "?").charAt(0)}
                          </div>
                          <div>
                            <div style={{ fontSize: 15, fontWeight: 700, color: C.ink }}>{person.name}</div>
                            <div style={{ fontSize: 12.5, color: C.muted }}>{tc(person.role)}</div>
                          </div>
                        </div>
                        {/* Прямі кнопки в особисті повідомлення. Без
                            заздалегідь вписаного тексту: людина пише про
                            що завгодно, а не тільки про запис. Посилання
                            на групову розмову тут навмисно немає. */}
                        {(() => {
                          const tg = String(person.telegramDirect || person.telegram || SIGNUP_TELEGRAM || "").replace("@", "").trim();
                          const wa = String(person.phone || "").replace(/\D/g, "");
                          if (tg === "" && wa === "") return null;
                          const base = { flex: 1, color: "#fff", border: "none", padding: "13px 10px", borderRadius: 12, fontSize: 14, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center", gap: 8, textDecoration: "none", boxSizing: "border-box" };
                          return (
                            <div style={{ display: "flex", gap: 8 }}>
                              {tg !== "" && (
                                <a href={`https://t.me/${tg}`} target="_blank" rel="noreferrer" style={{ ...base, background: "#229ed9" }}>
                                  <Send size={16} /> Telegram
                                </a>
                              )}
                              {wa !== "" && (
                                <a href={`https://wa.me/${wa}`} target="_blank" rel="noreferrer" style={{ ...base, background: "#25d366" }}>
                                  <MessageCircle size={16} /> WhatsApp
                                </a>
                              )}
                            </div>
                          );
                        })()}
                      </div>
                    ))}
                  </div>
                );
              })(),
            },
          };
          const r = renderers[sec.type];
          if (!r) return null;
          return (
            <Section key={sec.type} icon={r.icon} title={tc(sec.title)} accent={r.accent}>
              {r.body}
            </Section>
          );
        })}

        {/* Старий блок «Записатися у поїздку» з кнопками Telegram і
            WhatsApp прибрано: запис тепер іде через розділ «Запис у
            поїздку», а особисті контакти організатора — у розділі
            «Питання? Звʼяжіться зі мною» нижче. */}

        {isAdmin && (
          <div style={{ background: C.card, borderRadius: 18, padding: 16, marginTop: 14, boxShadow: "0 2px 12px rgba(60,79,44,0.06)" }}>
            <h3 style={{ margin: "0 0 12px", fontSize: 13, fontWeight: 800, color: C.muted, textTransform: "uppercase", letterSpacing: 0.6 }}>{t("manageTrip")}</h3>
            <OrganizerBookings trip={trip} pin={adminPin} onChanged={onBooked} />
            <PushDiagnostics pin={adminPin} trip={trip} />
            <div style={{ height: 16 }} />
            <label style={{ fontSize: 12, fontWeight: 700, color: C.ink, marginBottom: 6, display: "block" }}>{t("tripStatus")}</label>
            <select value={trip.status} onChange={(e) => onSetStatus(e.target.value)} style={{ width: "100%", boxSizing: "border-box", border: `1px solid ${C.line}`, borderRadius: 11, padding: "12px", fontSize: 14, fontWeight: 700, fontFamily: "inherit", background: C.yellowSoft, color: C.yellowInk, cursor: "pointer", marginBottom: 6 }}>
              {STATUS_ORDER.map((s) => (
                <option key={s} value={s}>{statusLabel(s)}</option>
              ))}
            </select>
            {trip.status === "postponed" && (
              <div style={{ marginBottom: 8 }}>
                <label style={{ fontSize: 12, fontWeight: 700, color: C.ink, marginBottom: 6, display: "block" }}>Нова дата (необов'язково)</label>
                <input
                  value={trip.postponedTo || ""}
                  onChange={(e) => onSetPostponedDate(e.target.value)}
                  placeholder="Наприклад: 12 липня (або лишіть порожнім)"
                  style={{ width: "100%", boxSizing: "border-box", border: `1px solid ${C.line}`, borderRadius: 11, padding: "11px", fontSize: 14, fontFamily: "inherit", background: "#fff", color: C.ink }}
                />
                <p style={{ fontSize: 11.5, color: C.muted, margin: "6px 0 0", lineHeight: 1.4 }}>
                  Якщо порожнє — напис буде просто «Перенесено».
                </p>
              </div>
            )}
            {/* Перенесення й скасування не мають розкладу: їх запускаєте
                ви. Тому сповіщення НЕ йде саме при зміні стану — спершу
                треба обрати причину й натиснути кнопку. Інакше випадковий
                дотик до списку станів розсилав би тривогу всій групі. */}
            {(trip.status === "postponed" || trip.status === "cancelled") && (
              <SituationPush trip={trip} kind={trip.status} pin={adminPin} />
            )}
            <p style={{ fontSize: 11.5, color: C.muted, margin: "0 0 4px", lineHeight: 1.45 }}>
              «Завершено» і «Скасовано» переносять поїздку в розділ «Минулі». Решта лишаються в «Найближчі».
            </p>
            <button
              onClick={() => { if (window.confirm("Видалити цю поїздку? Цю дію не можна скасувати.")) onDelete(); }}
              style={{ width: "100%", marginTop: 10, display: "flex", alignItems: "center", justifyContent: "center", gap: 6, background: "#fff", color: C.rasp, border: `1.5px solid ${C.rasp}`, borderRadius: 11, padding: "11px", fontSize: 13, fontWeight: 700, cursor: "pointer" }}>
              <Trash2 size={15} /> {t("deleteTrip")}
            </button>
          </div>
        )}

        {/* Bottom nav: back to main (left) and scroll to top (right) */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 18 }}>
          <button
            onClick={() => { onBack(); window.scrollTo(0, 0); }}
            aria-label="На головний екран"
            style={{ width: 46, height: 46, borderRadius: 23, border: "none", background: C.card, color: C.green, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", boxShadow: "0 3px 10px rgba(60,79,44,0.18)" }}>
            <ArrowLeft size={21} />
          </button>
          <button
            onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })}
            aria-label="Догори"
            style={{ width: 46, height: 46, borderRadius: 23, border: "none", background: C.card, color: C.green, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", boxShadow: "0 3px 10px rgba(60,79,44,0.18)" }}>
            <ArrowUp size={21} />
          </button>
        </div>
      </div>
    </div>
  );
}

// ── Trip editor form (organizer mode) ─────────────────────────────────
const BLANK_TRIP = () => ({
  id: "t" + Date.now(),
  status: "upcoming",
  postponedTo: "",
  title: "",
  subtitle: "",
  date: "",
  dateLabel: "",
  difficulty: "Легкий",
  difficultyNote: "",
  distanceKm: 0,
  ascentM: 0,
  descentM: 0,
  statsVisible: { distance: true, ascent: true, descent: false, duration: true },
  durationHrs: "",
  spots: 12,
  spotsTaken: 0,
  deadline: "",
  // Підтвердження заявок тепер завжди увімкнене — перемикача більше
  // немає. Поле лишається в даних, щоб старі поїздки не змінили
  // поведінку несподівано.
  requireApproval: true,
  from: { name: "München Hbf", time: "", platform: "" },
  to: { name: "", time: "" },
  trainLine: "",
  legs: [{ from: "", fromTime: "", platform: "", train: "", to: "", toTime: "", toPlatform: "", transfer: "" }],
  priceNote: "",
  contact: { name: "Андрій", role: "Організатор поїздки", telegram: "@autdoor_actyvni", phone: "+49 155 617 12359" },
  heroGradient: "linear-gradient(120deg, #1b92dc 0%, #38a3e0 32%, #5fb0c8 56%, #8fbf8a 78%, #aece5f 100%)",
  coords: { lat: 47.5, lng: 11.0 },
  meetingPoint: "",
  meetTime: "",
  image: "",
  placeType: "mountain",
  about: "",
  route: [],
  routeUrl: "",
  returnFrom: "",
  returnTime: "",
  returnPlatform: "",
  bonus: [],
  cafes: [],
  weather: { tempC: 15, tempMin: null, feelsC: 14, condition: "", code: 3, icon: "cloud", rainPct: 0, windKmh: 0, humidity: 50 },
  packing: [],
  sections: DEFAULT_SECTIONS.map((s) => ({ ...s, visible: true })),
});

// Стилі й Field винесені НА РІВЕНЬ МОДУЛЯ навмисно.
// Якщо оголосити Field усередині TripForm, React вважає його новим типом
// компонента на кожен рендер, розмонтовує поля вводу після кожного натискання
// клавіші — і на телефоні зникає клавіатура.
const lbl = { fontSize: 12, fontWeight: 700, color: C.ink, marginBottom: 5, display: "block" };
const inp = {
  width: "100%", boxSizing: "border-box", border: `1px solid ${C.line}`,
  borderRadius: 10, padding: "10px 12px", fontSize: 14, fontFamily: "inherit",
  background: "#fff", color: C.ink, marginBottom: 12,
};
const card = { background: C.card, borderRadius: 16, padding: 16, marginBottom: 14, boxShadow: "0 2px 12px rgba(60,79,44,0.06)" };
const cardTitle = { margin: "0 0 14px", fontSize: 14, fontWeight: 800, color: C.ink, display: "flex", alignItems: "center", gap: 8 };
const Field = ({ label, children }) => (
  <div><label style={lbl}>{label}</label>{children}</div>
);

function TripForm({ initial, onSave, onCancel }) {
  const [t, setT] = useState(() => JSON.parse(JSON.stringify(initial)));
  // Який маршрут і який поїзд усередині нього зараз розгорнуті.
  // Ключ поїзда — рядок «номер_маршруту:номер_поїзда», інакше розгортання
  // поїзда в одному відправленні відкривало б і сусіднє.
  const [openJourney, setOpenJourney] = useState(0);
  const [openLeg, setOpenLeg] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [addr, setAddr] = useState("");
  const [addrResults, setAddrResults] = useState(null); // null | [] | [..]
  const [addrBusy, setAddrBusy] = useState(false);
  // Стани від автопідбору поїздів через Deutsche Bahn прибрано разом
  // із самим підбором: вони лишались оголошеними, але вже нікуди не
  // використовувались.
  const [selStop, setSelStop] = useState(null);
  const [selBonus, setSelBonus] = useState(null);
  const [trLang, setTrLang] = useState("ru");
  const [trOpen, setTrOpen] = useState(false);
  // Маршрути в редакторі. Стара поїздка зберігала один маршрут у полі
  // legs — читаємо його як перше відправлення, щоб нічого не загубилось.
  const journeys = (t.journeys && t.journeys.length > 0)
    ? t.journeys
    : (t.legs && t.legs.length > 0 ? [{ legs: t.legs }] : [{ legs: [blankLeg()] }]);
  const set = (patch) => setT((prev) => ({ ...prev, ...patch }));
  const setNested = (key, patch) => setT((prev) => ({ ...prev, [key]: { ...prev[key], ...patch } }));


  // Route editing
  const addStop = () => set({ route: [...t.route, { name: "", note: "", info: "", t: "" }] });
  const updStop = (i, patch) => set({ route: t.route.map((s, j) => j === i ? { ...s, ...patch } : s) });
  const delStop = (i) => set({ route: t.route.filter((_, j) => j !== i) });

  // Бонусні точки — окремий список, не пов'язаний з маршрутом.
  const bonus = t.bonus || [];
  const addBonus = () => { set({ bonus: [...bonus, { name: "", note: "", lat: undefined, lng: undefined }] }); setSelBonus(bonus.length); };
  const updBonus = (i, patch) => set({ bonus: bonus.map((b, j) => j === i ? { ...b, ...patch } : b) });
  const delBonus = (i) => { set({ bonus: bonus.filter((_, j) => j !== i) }); setSelBonus(null); };

  // Sections editing (rename / reorder / show-hide). Backfill defaults for
  // older trips that don't yet carry a sections array.
  const sections = (() => {
    if (!(t.sections && t.sections.length > 0)) return DEFAULT_SECTIONS.map((s) => ({ ...s, visible: true }));
    // Розділи, що з'явились у застосунку пізніше, дописуємо в кінець —
    // інакше їх не можна було б ні перейменувати, ні сховати, ні
    // переставити в уже збереженій поїздці.
    const have = new Set(t.sections.map((x) => x.type));
    const missing = DEFAULT_SECTIONS.filter((d) => !have.has(d.type)).map((d) => ({ ...d, visible: true }));
    return t.sections.concat(missing);
  })();
  const setSections = (next) => set({ sections: next });
  const renameSection = (i, title) => setSections(sections.map((s, j) => j === i ? { ...s, title } : s));
  const toggleSectionVisible = (i) => setSections(sections.map((s, j) => j === i ? { ...s, visible: s.visible === false ? true : false } : s));
  const moveSection = (i, dir) => {
    const j = i + dir;
    if (j < 0 || j >= sections.length) return;
    const next = [...sections];
    [next[i], next[j]] = [next[j], next[i]];
    setSections(next);
  };

  const gradients = [
    { name: "Блакитний", v: "linear-gradient(120deg, #1b92dc 0%, #38a3e0 32%, #5fb0c8 56%, #8fbf8a 78%, #aece5f 100%)" },
    { name: "Помаранчевий", v: "linear-gradient(118deg, #b05c06 0%, #d37412 36%, #de9226 64%, #e6bd5d 100%)" },
    { name: "Червоний", v: "linear-gradient(118deg, #951333 0%, #bf0c20 32%, #cf2a26 54%, #db7d4e 82%, #c5a566 100%)" },
    { name: "Бірюзово-лаймовий", v: "radial-gradient(130% 130% at 90% 95%, rgba(215,217,21,0.45) 0%, rgba(215,217,21,0) 55%), linear-gradient(125deg, #1f8877 0%, #1d8f7e 32%, #45ab6e 60%, #84be47 82%, #cdd419 100%)" },
  ];
  const placeTypes = [
    { k: "mountain", n: "Гори" }, { k: "lake", n: "Озеро" },
    { k: "city", n: "Місто" }, { k: "gorge", n: "Ущелина" },
    { k: "forest", n: "Ліс" }, { k: "valley", n: "Долина" },
    { k: "river", n: "Ріка" }, { k: "museum", n: "Музей" },
    { k: "waterfall", n: "Водоспад" }, { k: "bike", n: "Вело" },
  ];

  const canSave = ukOf(t.title).trim() !== "" && ukOf(t.dateLabel).trim() !== "";

  return (
    <div style={{ paddingBottom: 100 }}>
      {/* header */}
      <div style={{ background: t.heroGradient, padding: "16px 18px 22px", color: "#fff" }}>
        <button onClick={onCancel} style={{ background: "rgba(255,255,255,0.2)", border: "none", color: "#fff", borderRadius: 12, padding: "8px 12px", display: "flex", alignItems: "center", gap: 6, cursor: "pointer", fontSize: 13.5, fontWeight: 600 }}>
          <ArrowLeft size={16} /> Скасувати
        </button>
        <h1 style={{ margin: "16px 0 0", fontSize: 22, fontWeight: 800 }}>
          {initial.title ? "Редагувати поїздку" : "Нова поїздка"}
        </h1>
      </div>

      <div style={{ padding: "18px 16px 0", marginTop: -12, background: C.page, borderRadius: "20px 20px 0 0" }}>
        {/* Basics */}
        <div style={card}>
          <h3 style={cardTitle}><Info size={15} /> Основне</h3>
          <Field label="Назва місця *"><input style={inp} value={t.title} onChange={(e) => set({ title: e.target.value })} placeholder="Наприклад: Айбзеє" /></Field>
          <Field label="Короткий підпис"><input style={inp} value={t.subtitle} onChange={(e) => set({ subtitle: e.target.value })} placeholder="Смарагдове озеро під Цугшпітце" /></Field>
          <Field label="Дата (текстом) *"><input style={inp} value={t.dateLabel} onChange={(e) => set({ dateLabel: e.target.value })} placeholder="Субота, 21 червня" /></Field>
          <Field label="Дата (календарна) *">
            <input style={{ ...inp, marginBottom: 6 }} type="date" value={t.date || ""} onChange={(e) => set({ date: e.target.value })} />
            <p style={{ fontSize: 11.5, margin: "0 0 12px", lineHeight: 1.45, color: weekdayOf(t.date) ? C.greenDark : C.rasp }}>
              {weekdayOf(t.date)
                ? <>День тижня: <b>{weekdayOf(t.date)}</b> — додасться до дати сам, усіма мовами.</>
                : <>Заповніть: від цього залежать день тижня біля дати, порядок поїздок у списку та прогноз погоди.</>}
            </p>
          </Field>
          <Field label="Google Диск для цієї поїздки (необов'язково)"><input style={inp} value={t.driveUrl || ""} onChange={(e) => set({ driveUrl: e.target.value })} placeholder="Порожньо — показується спільний архів" /></Field>
          {/* Перемикач ручної погоди. Прогноз — зручність, а не істина:
              сервіси розходяться між собою, і перевірити їх зсередини
              застосунку неможливо. Тому останнє слово лишається за
              організатором, який дивиться той прогноз, якому довіряє. */}
          <button onClick={() => set({ weatherManual: !t.weatherManual })}
            style={{ width: "100%", textAlign: "left", background: t.weatherManual ? C.yellowSoft : "#fff", border: `1.5px solid ${t.weatherManual ? C.yellow : C.line}`, borderRadius: 11, padding: 12, display: "flex", gap: 10, alignItems: "flex-start", cursor: "pointer", fontFamily: "inherit", marginBottom: 12 }}>
            <span style={{ width: 20, height: 20, borderRadius: 6, background: t.weatherManual ? C.yellowInk : "#fff", border: `1.5px solid ${t.weatherManual ? C.yellowInk : C.line}`, color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, marginTop: 1 }}>
              {t.weatherManual && <ClipboardCheck size={12} />}
            </span>
            <span style={{ flex: 1, minWidth: 0 }}>
              <span style={{ display: "block", fontSize: 13, fontWeight: 700, color: C.ink }}>Вписати погоду вручну</span>
              <span style={{ display: "block", fontSize: 11.5, color: C.muted, lineHeight: 1.5, marginTop: 3 }}>
                {t.weatherManual
                  ? "Учасники побачать саме ті числа, які ви вкажете нижче. Прогноз не завантажується."
                  : "Зараз показується автоматичний прогноз. Увімкніть, якщо він розходиться з тим, якому ви довіряєте."}
              </span>
            </span>
          </button>
          {t.weatherManual && (() => {
            const wx = t.weather || {};
            const setW = (patch) => set({ weather: { ...wx, ...patch } });
            const numField = (label, key, hint) => (
              <div>
                <div style={{ fontSize: 11, color: C.muted, fontWeight: 700, marginBottom: 4 }}>{label}</div>
                <input style={{ ...inp, marginBottom: 0 }} type="number" value={wx[key] != null ? wx[key] : ""}
                  onChange={(e) => setW({ [key]: e.target.value === "" ? null : Number(e.target.value) })}
                  placeholder={hint} />
              </div>
            );
            return (
              <div style={{ border: `1.5px solid ${C.yellow}`, background: C.yellowSoft, borderRadius: 12, padding: 12, marginBottom: 12 }}>
                <div style={{ fontSize: 12, fontWeight: 800, color: C.yellowInk, marginBottom: 9 }}>
                  Погода, яку побачать учасники
                </div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginBottom: 9 }}>
                  {numField("Максимум, °C", "tempC", "28")}
                  {numField("Мінімум, °C", "tempMin", "16")}
                  {numField("Опади, %", "rainPct", "20")}
                  {numField("Вітер, км/год", "windKmh", "12")}
                  {numField("Вологість, %", "humidity", "60")}
                  {numField("Відчувається, °C", "feelsC", "28")}
                </div>
                <div style={{ fontSize: 11, color: C.muted, fontWeight: 700, marginBottom: 5 }}>Стан неба</div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 6 }}>
                  {WMO_MAP.map((m) => (
                    <button key={m.codes[0]} onClick={() => setW({ code: m.codes[0], icon: m.icon })}
                      style={{ border: `1px solid ${Number(wx.code) === m.codes[0] ? C.yellowInk : C.line}`, background: Number(wx.code) === m.codes[0] ? C.yellowInk : "#fff", color: Number(wx.code) === m.codes[0] ? "#fff" : C.ink, borderRadius: 9, padding: "9px 8px", fontSize: 12.5, fontWeight: 600, cursor: "pointer", fontFamily: "inherit", textAlign: "left" }}>
                      {m.uk}
                    </button>
                  ))}
                </div>
                <p style={{ fontSize: 11, color: C.muted, margin: "9px 0 0", lineHeight: 1.5 }}>
                  Стан неба перекладається сам усіма мовами — вписувати текст не треба.
                  Порожні числові поля просто не показуються.
                </p>
              </div>
            );
          })()}
          {(() => {
            if (t.weatherManual) return null;
            // Живий прогноз одразу в редакторі — щойно вказані дата й координати.
            const la = parseFloat(t.coords && t.coords.lat), ln = parseFloat(t.coords && t.coords.lng);
            if (!t.date || isNaN(la) || isNaN(ln)) {
              return (
                <p style={{ fontSize: 12, color: C.muted, margin: "-6px 0 12px", lineHeight: 1.45 }}>
                  Вкажіть дату й точку збору нижче — і тут з'явиться прогноз погоди на цей день.
                </p>
              );
            }
            const w = { tempC: 0, feelsC: 0, condition: "", icon: "cloud", rainPct: 0, windKmh: 0, humidity: 0, ...(t.weather || {}) };
            return (
              <div style={{ background: "#fff", border: `1px solid ${C.line}`, borderRadius: 12, padding: 12, marginBottom: 12 }}>
                <LiveWeather trip={{ id: t.id, date: t.date, coords: { lat: la, lng: ln }, weather: w }} />
              </div>
            );
          })()}
          <Field label="Опис місця"><textarea style={{ ...inp, minHeight: 90, resize: "vertical" }} value={t.about} onChange={(e) => set({ about: e.target.value })} placeholder="Розкажіть про місце, маршрут, що побачать учасники…" /></Field>
          <Field label="Фото місця">
            {t.image && t.image.trim() !== "" && (
              <img src={t.image} alt="" style={{ width: "100%", borderRadius: 12, marginBottom: 8, display: "block", maxHeight: 180, objectFit: "cover" }} />
            )}
            <label style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8, border: `1.5px dashed ${C.green}`, background: C.greenSoft, color: C.greenDark, borderRadius: 10, padding: "11px", fontSize: 13, fontWeight: 700, cursor: uploading ? "default" : "pointer", marginBottom: 8, opacity: uploading ? 0.6 : 1 }}>
              <Camera size={16} /> {uploading ? "Завантажую фото…" : "Завантажити фото з пристрою"}
              <input type="file" accept="image/*" style={{ display: "none" }} disabled={uploading}
                onChange={async (e) => {
                  const f = e.target.files && e.target.files[0];
                  e.target.value = "";
                  if (!f) return;
                  try {
                    setUploading(true);
                    const url = await sbUploadImage(f);
                    set({ image: url });
                  } catch (err) {
                    alert("Не вдалося завантажити фото.\n" + (err && err.message ? err.message : err));
                  } finally { setUploading(false); }
                }} />
            </label>
            <input style={inp} value={t.image} onChange={(e) => set({ image: e.target.value })} placeholder="…або вставте URL фото вручну" />
          </Field>
          <Field label="Тип місця (іконка для заглушки)">
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 12 }}>
              {placeTypes.map((p) => (
                <button key={p.k} onClick={() => set({ placeType: p.k })} style={{
                  border: `1.5px solid ${t.placeType === p.k ? C.green : C.line}`, background: t.placeType === p.k ? C.greenSoft : "#fff",
                  color: t.placeType === p.k ? C.greenDark : C.muted, borderRadius: 10, padding: "8px 14px", fontSize: 13, fontWeight: 600, cursor: "pointer",
                }}>{p.n}</button>
              ))}
            </div>
          </Field>
          <Field label="Колір верхньої частини">
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
              {gradients.map((g) => (
                <button key={g.name} onClick={() => set({ heroGradient: g.v })} title={g.name} style={{
                  width: 52, height: 36, borderRadius: 10, border: t.heroGradient === g.v ? "3px solid #fff" : "1px solid rgba(0,0,0,0.1)",
                  boxShadow: t.heroGradient === g.v ? `0 0 0 2px ${C.green}` : "none", background: g.v, cursor: "pointer",
                }} />
              ))}
            </div>
          </Field>
        </div>

        {/* Section structure: rename / reorder / hide */}
        <div style={card}>
          <h3 style={cardTitle}><Settings size={15} /> Структура поїздки</h3>
          <p style={{ fontSize: 12, color: C.muted, margin: "0 0 12px", lineHeight: 1.5 }}>
            Перейменовуйте блоки, міняйте їх порядок стрілками або ховайте окремі блоки для цієї поїздки.
            <br /><b>Порада:</b> лишіть назву порожньою — застосунок підставить власну, вже перекладену
            на всі мови. Власна назва перекладається машинно, і в ній можливі помилки.
          </p>
          {sections.map((s, i) => (
            <div key={s.type} style={{ border: `1px solid ${C.line}`, borderRadius: 12, padding: 10, marginBottom: 8, background: s.visible === false ? "#f5f3ee" : "#fff", opacity: s.visible === false ? 0.7 : 1 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
                  <button onClick={() => moveSection(i, -1)} disabled={i === 0} style={{ border: "none", background: i === 0 ? "#eee" : C.greenSoft, color: i === 0 ? "#bbb" : C.greenDark, borderRadius: 6, width: 26, height: 20, cursor: i === 0 ? "default" : "pointer", fontSize: 11, fontWeight: 800, lineHeight: 1 }}>▲</button>
                  <button onClick={() => moveSection(i, 1)} disabled={i === sections.length - 1} style={{ border: "none", background: i === sections.length - 1 ? "#eee" : C.greenSoft, color: i === sections.length - 1 ? "#bbb" : C.greenDark, borderRadius: 6, width: 26, height: 20, cursor: i === sections.length - 1 ? "default" : "pointer", fontSize: 11, fontWeight: 800, lineHeight: 1 }}>▼</button>
                </div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 3 }}>
                    <span style={{ fontSize: 10.5, color: C.muted, fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.4 }}>{SECTION_LABELS[s.type] || s.type}</span>
                    {/* Порожня назва означає «взяти вбудовану». Вбудовані
                        назви перекладені вручну й правильні в усіх мовах,
                        а власна назва йде через машинний переклад — тому
                        повернути стандартну має бути легко, в один дотик. */}
                    {String(s.title || "").trim() !== "" && (
                      <button onClick={() => renameSection(i, "")}
                        style={{ border: "none", background: "none", color: C.green, fontSize: 10.5, fontWeight: 700, cursor: "pointer", padding: 0, fontFamily: "inherit", textDecoration: "underline" }}>
                        стандартна назва
                      </button>
                    )}
                  </div>
                  <input value={s.title || ""} onChange={(e) => renameSection(i, e.target.value)}
                    placeholder={sectionDefaultTitle(s)}
                    style={{ width: "100%", boxSizing: "border-box", border: `1px solid ${C.line}`, borderRadius: 8, padding: "7px 10px", fontSize: 13.5, fontFamily: "inherit", background: "#fff", color: C.ink }} />
                </div>
                <button onClick={() => toggleSectionVisible(i)} title={s.visible === false ? "Показати" : "Сховати"} style={{ border: "none", background: s.visible === false ? C.line : C.raspSoft, color: s.visible === false ? C.muted : C.rasp, borderRadius: 8, padding: "8px 10px", fontSize: 11.5, fontWeight: 700, cursor: "pointer", whiteSpace: "nowrap" }}>
                  {s.visible === false ? "Сховано" : "Видно"}
                </button>
              </div>
            </div>
          ))}
        </div>

        {/* Stats + difficulty */}
        <div style={card}>
          <h3 style={cardTitle}><Signal size={15} /> Параметри</h3>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
            <Field label="Дистанція (км)"><input style={inp} type="number" value={t.distanceKm} onChange={(e) => set({ distanceKm: e.target.value })} /></Field>
            <Field label="Тривалість"><input style={inp} value={t.durationHrs} onChange={(e) => set({ durationHrs: e.target.value })} placeholder="4–5 год" /></Field>
            <Field label="Підйом (м)"><input style={inp} type="number" value={t.ascentM} onChange={(e) => set({ ascentM: e.target.value })} /></Field>
            <Field label="Спуск (м)"><input style={inp} type="number" value={t.descentM ?? ""} onChange={(e) => set({ descentM: e.target.value })} /></Field>
          </div>
          <label style={lbl}>Які вікна показувати в поїздці</label>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: 12 }}>
            {[
              { k: "distance", n: "Дистанція" },
              { k: "ascent", n: "Підйом" },
              { k: "descent", n: "Спуск" },
              { k: "duration", n: "Тривалість" },
            ].map((o) => {
              const sv = t.statsVisible || {};
              const on = o.k === "descent" ? sv.descent === true : sv[o.k] !== false;
              return (
                <button key={o.k} onClick={() => set({ statsVisible: { ...sv, [o.k]: !on } })} style={{
                  border: `1.5px solid ${on ? C.green : C.line}`, background: on ? C.greenSoft : "#fff",
                  color: on ? C.greenDark : C.muted, borderRadius: 10, padding: "8px 13px", fontSize: 13, fontWeight: 600, cursor: "pointer",
                  display: "flex", alignItems: "center", gap: 6,
                }}>
                  <span style={{ fontSize: 13 }}>{on ? "✓" : "○"}</span> {o.n}
                </button>
              );
            })}
          </div>
          <Field label="Складність">
            <div style={{ display: "flex", gap: 8, marginBottom: 12 }}>
              {["Легкий", "Середній", "Складний"].map((d) => (
                <button key={d} onClick={() => set({ difficulty: d })} style={{
                  flex: 1, border: `1.5px solid ${t.difficulty === d ? diffColor(d) : C.line}`, background: t.difficulty === d ? diffColor(d) : "#fff",
                  color: t.difficulty === d ? "#fff" : C.muted, borderRadius: 10, padding: "9px 6px", fontSize: 13, fontWeight: 700, cursor: "pointer",
                }}>{d}</button>
              ))}
            </div>
          </Field>
          <Field label="Пояснення складності"><input style={inp} value={t.difficultyNote} onChange={(e) => set({ difficultyNote: e.target.value })} placeholder="Для кого підходить, що врахувати" /></Field>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
            <Field label="Всього місць"><input style={inp} type="number" value={t.spots} onChange={(e) => set({ spots: e.target.value })} /></Field>
            <Field label="Запис до (дедлайн)">
              <input style={{ ...inp, marginBottom: 6 }} type="datetime-local" value={t.deadline || ""} onChange={(e) => set({ deadline: e.target.value })} />
              <p style={{ fontSize: 11.5, color: C.muted, margin: "0 0 12px", lineHeight: 1.45 }}>
                Після цього часу кнопка «Записатися» закривається сама. Порожнє поле — запис без обмеження в часі.
              </p>
            </Field>
            <Field label="Зайнято місць (запасне)">
              <input style={{ ...inp, marginBottom: 6 }} type="number" value={t.spotsTaken} onChange={(e) => set({ spotsTaken: e.target.value })} />
              <p style={{ fontSize: 11.5, color: C.muted, margin: "0 0 12px", lineHeight: 1.45 }}>
                Щойно з'явиться перший запис через застосунок, це поле ні на що не впливає.
              </p>
            </Field>
          </div>
        </div>

        {/* Train */}
        <div style={card}>
          <h3 style={cardTitle}><Train size={15} /> Поїзди (з пересадками)</h3>
          <p style={{ fontSize: 12, color: C.muted, margin: "0 0 12px", lineHeight: 1.5 }}>
            Кожне <b>відправлення</b> — окремий маршрут із власного міста до спільної цілі.
            Усередині відправлення додавайте поїзди; між ними сама з'явиться пересадка.
            Лишіть поле пересадки порожнім — час порахується з часів прибуття й відправлення.
            Відправлень, поїздів і пересадок може бути скільки завгодно.
          </p>

          {journeys.map((jr, ji) => {
            const legs = jr.legs || [];
            const jOpen = openJourney === ji;
            const jFrom = (legs.find(legFilled) || {}).from || "";
            const jTo = ([...legs].reverse().find(legFilled) || {}).to || "";
            // Змінює один маршрут, не чіпаючи решту.
            const setLegs = (nextLegs) => set({ journeys: journeys.map((x, k) => k === ji ? { ...x, legs: nextLegs } : x) });
            return (
              <div key={ji} style={{ border: `1.5px solid ${jOpen ? C.rasp : C.line}`, borderRadius: 14, marginBottom: 12, background: jOpen ? C.raspSoft : "#fff", overflow: "hidden" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "12px 13px" }}>
                  <button onClick={() => { setOpenJourney(jOpen ? null : ji); setOpenLeg(null); }}
                    style={{ flex: 1, minWidth: 0, textAlign: "left", background: "none", border: "none", cursor: "pointer", fontFamily: "inherit", padding: 0 }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 7 }}>
                      <span style={{ color: C.rasp, flexShrink: 0, transform: jOpen ? "rotate(90deg)" : "none", transition: "transform .15s", display: "flex" }}>
                        <ChevronRight size={17} />
                      </span>
                      <span style={{ fontSize: 12.5, fontWeight: 800, color: C.rasp }}>Відправлення {ji + 1}</span>
                      <span style={{ fontSize: 11, color: C.muted }}>· поїздів: {legs.filter(legFilled).length}</span>
                    </div>
                    <div style={{ fontSize: 12.5, color: C.ink, fontWeight: 600, marginTop: 4, paddingLeft: 24, lineHeight: 1.35 }}>
                      {(jFrom || "місто не вказане") + " → " + (jTo || "кінцева не вказана")}
                    </div>
                  </button>
                  {journeys.length > 1 && (
                    <button onClick={() => { set({ journeys: journeys.filter((_, k) => k !== ji) }); setOpenJourney(null); setOpenLeg(null); }}
                      style={{ background: "none", border: "none", color: C.rasp, fontSize: 12, fontWeight: 600, cursor: "pointer", flexShrink: 0 }}>Видалити</button>
                  )}
                </div>

                {jOpen && (
                  <div style={{ padding: "0 13px 13px", borderTop: `1px solid ${C.line}`, background: "#fff" }}>
                    <div style={{ height: 12 }} />
                    {legs.map((leg, i) => {
                      const upd = (patch) => setLegs(legs.map((l, j) => j === i ? { ...l, ...patch } : l));
                      const prev = i > 0 ? legs[i - 1] : null;
                      const autoMin = prev ? minutesBetween(prev.toTime, leg.fromTime) : null;
                      // Ключ включає номер маршруту: інакше розгортання поїзда
                      // в одному відправленні відкривало б і поїзд у сусідньому.
                      const legKey = ji + ":" + i;
                      const isOpen = openLeg === legKey;
                      return (
                        <div key={i}>
                          {/* Пересадка стоїть МІЖ поїздами — там, де вона й відбувається. */}
                          {prev && (
                            <div style={{ background: C.yellowSoft, border: `1px solid ${C.yellow}`, borderRadius: 12, padding: "10px 12px", marginBottom: 10, display: "flex", alignItems: "center", gap: 10 }}>
                              <Footprints size={17} style={{ color: C.yellowInk, flexShrink: 0 }} />
                              <span style={{ fontSize: 12.5, fontWeight: 700, color: C.yellowInk, flexShrink: 0 }}>Пересадка</span>
                              <input
                                style={{ ...inp, marginBottom: 0, flex: 1, minWidth: 0, background: "#fff" }}
                                value={leg.transfer || ""}
                                onChange={(e) => upd({ transfer: e.target.value })}
                                placeholder={autoMin != null ? `${autoMin} хв (авто)` : "напр. 14 хв"} />
                            </div>
                          )}
                          <div style={{ border: `1px solid ${C.line}`, borderRadius: 12, marginBottom: 10, background: "#fff", overflow: "hidden" }}>
                            <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "10px 12px" }}>
                              <button onClick={() => setOpenLeg(isOpen ? null : legKey)}
                                style={{ flex: 1, minWidth: 0, textAlign: "left", background: "none", border: "none", cursor: "pointer", fontFamily: "inherit", padding: 0 }}>
                                <div style={{ display: "flex", alignItems: "center", gap: 7 }}>
                                  <span style={{ color: C.rasp, flexShrink: 0, transform: isOpen ? "rotate(90deg)" : "none", transition: "transform .15s", display: "flex" }}>
                                    <ChevronRight size={16} />
                                  </span>
                                  <span style={{ fontSize: 12, fontWeight: 800, color: C.rasp }}>Поїзд {i + 1}</span>
                                  {leg.train && leg.train.trim() !== "" && (
                                    <span style={{ fontSize: 11, fontWeight: 800, color: C.yellowInk, background: C.yellow, padding: "3px 9px", borderRadius: 20 }}>{leg.train}</span>
                                  )}
                                </div>
                                <div style={{ fontSize: 12, color: C.muted, marginTop: 4, paddingLeft: 23, lineHeight: 1.35 }}>
                                  {(leg.fromTime || "—") + " " + (leg.from || "станція не вказана")}
                                  {" → "}
                                  {(leg.toTime || "—") + " " + (leg.to || "кінцева не вказана")}
                                </div>
                              </button>
                              <button onClick={() => { setLegs(legs.filter((_, j) => j !== i)); setOpenLeg(null); }}
                                style={{ background: "none", border: "none", color: C.rasp, fontSize: 12, fontWeight: 600, cursor: "pointer", flexShrink: 0 }}>Видалити</button>
                            </div>
                            {isOpen && (
                              <div style={{ padding: "0 12px 12px", borderTop: `1px solid ${C.line}` }}>
                                <div style={{ fontSize: 11, fontWeight: 800, color: C.muted, textTransform: "uppercase", letterSpacing: 0.4, margin: "11px 0 7px" }}>Звідки</div>
                                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
                                  <input style={{ ...inp, marginBottom: 0 }} value={leg.from || ""} onChange={(e) => upd({ from: e.target.value })} placeholder="Станція (Augsburg Hbf)" />
                                  <input style={{ ...inp, marginBottom: 0 }} value={leg.fromTime || ""} onChange={(e) => upd({ fromTime: e.target.value })} placeholder="Відпр. 08:38" />
                                  <input style={{ ...inp, marginBottom: 0 }} value={leg.platform || ""} onChange={(e) => upd({ platform: e.target.value })} placeholder="Колія (8)" />
                                  <input style={{ ...inp, marginBottom: 0 }} value={leg.train || ""} onChange={(e) => upd({ train: e.target.value })} placeholder="Поїзд (RE 9)" />
                                </div>
                                <div style={{ fontSize: 11, fontWeight: 800, color: C.muted, textTransform: "uppercase", letterSpacing: 0.4, margin: "13px 0 7px" }}>Куди (кінцева станція цього поїзда)</div>
                                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
                                  <input style={{ ...inp, marginBottom: 0 }} value={leg.to || ""} onChange={(e) => upd({ to: e.target.value })} placeholder="Станція (München Hbf)" />
                                  <input style={{ ...inp, marginBottom: 0 }} value={leg.toTime || ""} onChange={(e) => upd({ toTime: e.target.value })} placeholder="Приб. 09:56" />
                                  <input style={{ ...inp, marginBottom: 0 }} value={leg.toPlatform || ""} onChange={(e) => upd({ toPlatform: e.target.value })} placeholder="Колія прибуття (17)" />
                                </div>
                              </div>
                            )}
                          </div>
                        </div>
                      );
                    })}
                    <button onClick={() => { setLegs([...legs, blankLeg()]); setOpenLeg(ji + ":" + legs.length); }}
                      style={{ width: "100%", border: `1.5px dashed ${C.rasp}`, background: C.raspSoft, color: C.rasp, borderRadius: 10, padding: "10px", fontSize: 13, fontWeight: 700, cursor: "pointer" }}>
                      + Додати поїзд{legs.length > 0 ? " і пересадку" : ""}
                    </button>
                  </div>
                )}
              </div>
            );
          })}

          {/* Одне поле часу — свідомо, без станцій і пересадок. */}
          <div style={{ border: `1px solid ${C.line}`, borderRadius: 12, padding: 12, marginBottom: 12, background: "#fff" }}>
            <div style={{ fontSize: 12, fontWeight: 800, color: C.rasp, marginBottom: 7 }}>Відправлення назад</div>
            <input style={{ ...inp, marginBottom: 7 }} value={t.returnFrom || ""} onChange={(e) => set({ returnFrom: e.target.value })} placeholder="Станція (Würzburg Hbf)" />
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
              <input style={{ ...inp, marginBottom: 7 }} value={t.returnTime || ""} onChange={(e) => set({ returnTime: e.target.value })} placeholder="Час (17:41)" />
              <input style={{ ...inp, marginBottom: 7 }} value={t.returnPlatform || ""} onChange={(e) => set({ returnPlatform: e.target.value })} placeholder="Колія (2)" />
            </div>
            <p style={{ fontSize: 11.5, color: C.muted, margin: 0, lineHeight: 1.45 }}>
              Три окремі поля навмисно: слово «колія» підставляє сам застосунок
              потрібною мовою. Якщо вписати все одним рядком, воно лишиться
              українським для англомовних. Порожні поля — блок не показується.
            </p>
          </div>
          <button onClick={() => { const n = journeys.length; set({ journeys: [...journeys, { legs: [blankLeg()] }] }); setOpenJourney(n); setOpenLeg(n + ":0"); }}
            style={{ width: "100%", border: `1.5px dashed ${C.green}`, background: C.greenSoft, color: C.greenDark, borderRadius: 10, padding: "11px", fontSize: 13, fontWeight: 700, cursor: "pointer", marginBottom: 12 }}>
            + Додати відправлення з іншого міста
          </button>
          <Field label="Примітка про квитки"><input style={inp} value={t.priceNote} onChange={(e) => set({ priceNote: e.target.value })} placeholder="Bayern-Ticket ~29 €/особа" /></Field>
        </div>

        {/* Meeting point */}
        <div style={card}>
          <h3 style={cardTitle}><MapPin size={15} /> Точка збору</h3>
          {/* Час збору окремим полем. Від нього відлічуються дві години
              для нагадування. Без нього годинник брав час відправлення
              найдальшого міста — а це зовсім інша година. */}
          <Field label="Час збору">
            <input style={{ ...inp, marginBottom: 6 }} value={t.meetTime || ""} onChange={(e) => set({ meetTime: e.target.value })} placeholder="напр. 08:15" />
            <p style={{ fontSize: 11.5, color: C.muted, margin: "0 0 12px", lineHeight: 1.45 }}>
              {String(t.meetTime || "").match(/(\d{1,2}):(\d{2})/)
                ? <>Нагадування учасникам надійде за дві години — приблизно о{" "}
                    <b style={{ color: C.greenDark }}>{(() => {
                      const m = String(t.meetTime).match(/(\d{1,2}):(\d{2})/);
                      const mins = Math.max(0, Number(m[1]) * 60 + Number(m[2]) - 120);
                      return `${String(Math.floor(mins / 60)).padStart(2, "0")}:${String(mins % 60).padStart(2, "0")}`;
                    })()}</b>.</>
                : <>Заповніть — інакше нагадування про збір не надійде: нема від чого відлічувати дві години.</>}
            </p>
          </Field>
          <Field label="Місце зустрічі (текстом)">
            <textarea style={{ ...inp, minHeight: 70, resize: "vertical" }} value={t.meetingPoint} onChange={(e) => set({ meetingPoint: e.target.value })} placeholder="Наприклад: біля головного входу München Hbf, під табло. Шукайте жовтий прапорець." />
          </Field>
          <label style={lbl}>Геолокація (точка збору)</label>
          <div style={{ display: "flex", gap: 8, marginBottom: 10 }}>
            <input
              style={{ ...inp, marginBottom: 0, flex: 1 }}
              value={addr}
              placeholder="Адреса, назва місця або координати"
              onChange={(e) => {
                setAddr(e.target.value);
                // Якщо вставили координати чи посилання з Google Maps —
                // підставляємо одразу, без пошуку.
                const p = parseCoordsInput(e.target.value);
                if (p) { setNested("coords", p); setAddrResults(null); }
              }}
              onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); document.getElementById("addr-find-btn")?.click(); } }}
            />
            <button
              id="addr-find-btn"
              onClick={async () => {
                const q = addr.trim();
                if (q === "") return;
                if (parseCoordsInput(q)) return; // це вже координати
                try {
                  setAddrBusy(true); setAddrResults(null);
                  setAddrResults(await geocodeAddress(q));
                } catch (err) {
                  alert("Пошук не спрацював. Перевірте інтернет або введіть координати вручну.");
                } finally { setAddrBusy(false); }
              }}
              style={{ border: "none", background: C.green, color: "#fff", borderRadius: 10, padding: "0 16px", fontSize: 13, fontWeight: 700, cursor: "pointer", whiteSpace: "nowrap" }}>
              {addrBusy ? "…" : "Знайти"}
            </button>
          </div>
          {addrResults && addrResults.length === 0 && (
            <p style={{ fontSize: 12.5, color: C.rasp, margin: "0 0 10px" }}>Нічого не знайдено. Спробуйте додати місто чи країну — напр. «Bayerstraße 10A, München».</p>
          )}
          {addrResults && addrResults.length > 0 && (
            <div style={{ border: `1px solid ${C.line}`, borderRadius: 10, overflow: "hidden", marginBottom: 10 }}>
              {addrResults.map((r, i) => (
                <button key={i} onClick={() => { setNested("coords", { lat: r.lat, lng: r.lng }); setAddrResults(null); setAddr(r.label); }}
                  style={{ display: "block", width: "100%", textAlign: "left", background: "#fff", border: "none", borderBottom: i === addrResults.length - 1 ? "none" : `1px solid ${C.line}`, padding: "10px 12px", fontSize: 12.5, lineHeight: 1.4, color: C.ink, cursor: "pointer", fontFamily: "inherit" }}>
                  📍 {r.label}
                </button>
              ))}
            </div>
          )}
          {(() => {
            const la = parseFloat(t.coords && t.coords.lat), ln = parseFloat(t.coords && t.coords.lng);
            return !isNaN(la) && !isNaN(ln) && (la !== 0 || ln !== 0) ? (
              <div style={{ marginBottom: 10 }}><MeetingMap lat={la} lng={ln} /></div>
            ) : null;
          })()}
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
            <input style={inp} type="number" step="any" value={t.coords.lat} onChange={(e) => setNested("coords", { lat: e.target.value })} placeholder="Широта (47.4917)" />
            <input style={inp} type="number" step="any" value={t.coords.lng} onChange={(e) => setNested("coords", { lng: e.target.value })} placeholder="Довгота (11.0958)" />
          </div>
          <div style={{ display: "flex", gap: 8, alignItems: "flex-start", padding: "10px 12px", background: C.greenSoft, borderRadius: 10, fontSize: 12, color: C.greenDark, lineHeight: 1.5 }}>
            <Info size={15} style={{ flexShrink: 0, marginTop: 1 }} />
            <span>Напишіть адресу або назву місця й натисніть <b>«Знайти»</b> — оберіть потрібний варіант зі списку, координати підставляться самі. Або вставте у це ж поле готові координати чи посилання з <a href="https://www.google.com/maps" target="_blank" rel="noreferrer" style={{ color: C.greenDark, fontWeight: 700 }}>Google Maps</a>. Перевіряйте точку на карті вище.</span>
          </div>
          {(t.coords.lat !== 0 || t.coords.lng !== 0) && (
            <a href={gmapsUrl(t.coords.lat, t.coords.lng)} target="_blank" rel="noreferrer"
              style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 6, marginTop: 10, background: "#fff", color: C.green, border: `1.5px solid ${C.green}`, borderRadius: 10, padding: "9px", fontSize: 12.5, fontWeight: 700, textDecoration: "none" }}>
              <Navigation size={14} /> Перевірити на карті
            </a>
          )}
        </div>

        {/* Route */}
        <div style={card}>
          <h3 style={cardTitle}><Mountain size={15} /> Маршрут</h3>
          {t.route.length === 0 && <p style={{ fontSize: 13, color: C.muted, margin: "0 0 12px" }}>Поки немає точок. Додайте першу нижче.</p>}
          {(() => {
            // Карта показує ту точку, яку обрали в списку нижче.
            const sel = selStop != null ? t.route[selStop] : null;
            const la = parseFloat(sel && sel.lat), ln = parseFloat(sel && sel.lng);
            if (!sel || isNaN(la) || isNaN(ln)) return null;
            return (
              <div style={{ marginBottom: 12 }}>
                <MeetingMap lat={la} lng={ln} />
                <p style={{ fontSize: 11.5, color: C.muted, margin: "6px 0 0" }}>На карті: {sel.name || `Точка ${selStop + 1}`}</p>
              </div>
            );
          })()}
          {t.route.map((s, i) => (
            <div key={i}
              onClick={() => setSelStop(selStop === i ? null : i)}
              style={{ border: `1.5px solid ${selStop === i ? C.green : C.line}`, borderRadius: 12, padding: 12, marginBottom: 10, background: selStop === i ? C.greenSoft : "#fff", cursor: "pointer" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                <span style={{ fontSize: 12, fontWeight: 700, color: C.green }}>Точка {i + 1}{selStop === i ? " · на карті" : ""}</span>
                <button onClick={() => delStop(i)} style={{ background: "none", border: "none", color: C.rasp, fontSize: 12, fontWeight: 600, cursor: "pointer" }}>Видалити</button>
              </div>
              <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr", gap: 8 }}>
                <input onClick={(e) => e.stopPropagation()} style={{ ...inp, marginBottom: 8 }} value={s.name} onChange={(e) => updStop(i, { name: e.target.value })} placeholder="Назва точки" />
                <input style={{ ...inp, marginBottom: 8 }} value={s.t} onChange={(e) => updStop(i, { t: e.target.value })} placeholder="10:30" />
              </div>
              <input onClick={(e) => e.stopPropagation()} style={{ ...inp, marginBottom: 8 }} value={s.note} onChange={(e) => updStop(i, { note: e.target.value })} placeholder="Примітка (необов'язково)" />
              {/* Багаторядкове: сюди йдуть ціни, години роботи, події —
                  один рядок для цього затісний, а перенесення рядків
                  зберігаються й показуються учаснику як є. */}
              <textarea onClick={(e) => e.stopPropagation()} rows={2}
                style={{ ...inp, marginBottom: 8, resize: "vertical", lineHeight: 1.45 }}
                value={s.info || ""}
                onChange={(e) => updStop(i, { info: e.target.value })}
                placeholder="Додаткова інформація: вхід 8 €, музей до 17:00, у неділю фестиваль" />
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
                <input style={{ ...inp, marginBottom: 0 }} type="number" step="any" value={s.lat ?? ""} onChange={(e) => updStop(i, { lat: e.target.value === "" ? undefined : parseFloat(e.target.value) })} placeholder="Широта (47.49)" />
                <input style={{ ...inp, marginBottom: 0 }} type="number" step="any" value={s.lng ?? ""} onChange={(e) => updStop(i, { lng: e.target.value === "" ? undefined : parseFloat(e.target.value) })} placeholder="Довгота (11.10)" />
              </div>
            </div>
          ))}
          <button onClick={addStop} style={{ width: "100%", border: `1.5px dashed ${C.green}`, background: C.greenSoft, color: C.greenDark, borderRadius: 10, padding: "10px", fontSize: 13, fontWeight: 700, cursor: "pointer" }}>+ Додати точку маршруту</button>
          <label style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8, border: `1.5px dashed ${C.rasp}`, background: C.raspSoft, color: C.rasp, borderRadius: 10, padding: "11px", fontSize: 13, fontWeight: 700, cursor: "pointer", marginTop: 8 }}>
            <MapPin size={15} /> Завантажити GPX з Komoot / Bergfex
            <input type="file" accept=".gpx,application/gpx+xml,text/xml" style={{ display: "none" }}
              onChange={async (e) => {
                const f = e.target.files && e.target.files[0];
                e.target.value = "";
                if (!f) return;
                try {
                  const text = await f.text();
                  const doc = new DOMParser().parseFromString(text, "application/xml");
                  if (doc.querySelector("parsererror")) throw new Error("Файл пошкоджений");
                  // Спершу беремо іменовані точки (wpt) — це саме зупинки
                  // й паузи, які позначив автор маршруту в Komoot/Bergfex.
                  let pts = [...doc.querySelectorAll("wpt")].map((w) => ({
                    name: (w.querySelector("name") && w.querySelector("name").textContent.trim()) || "",
                    lat: parseFloat(w.getAttribute("lat")),
                    lng: parseFloat(w.getAttribute("lon")),
                  })).filter((p) => !isNaN(p.lat) && !isNaN(p.lng));
                  // Якщо іменованих точок немає — беремо сам трек і рівномірно
                  // розріджуємо його до 8 точок, щоб карта лишалась читабельною.
                  if (pts.length === 0) {
                    const trk = [...doc.querySelectorAll("trkpt, rtept")].map((w) => ({
                      lat: parseFloat(w.getAttribute("lat")),
                      lng: parseFloat(w.getAttribute("lon")),
                    })).filter((p) => !isNaN(p.lat) && !isNaN(p.lng));
                    if (trk.length === 0) throw new Error("У файлі немає точок");
                    const want = Math.min(8, trk.length);
                    const step = Math.max(1, Math.floor(trk.length / want));
                    pts = trk.filter((_, i) => i % step === 0).slice(0, want)
                      .map((p, i, a) => ({ ...p, name: i === 0 ? "Старт" : i === a.length - 1 ? "Фініш" : `Точка ${i}` }));
                  }
                  set({
                    route: pts.map((p) => ({
                      name: p.name || "Точка",
                      note: "",
                      t: "",
                      lat: Number(p.lat.toFixed(6)),
                      lng: Number(p.lng.toFixed(6)),
                    })),
                  });
                  alert(`Завантажено точок: ${pts.length}. Назви й примітки можна відредагувати нижче.`);
                } catch (err) {
                  alert("Не вдалося прочитати GPX.\n\n" + ((err && err.message) || err) + "\n\nУ Komoot: «Експорт туру» → GPX. У Bergfex: кнопка завантаження треку → GPX.");
                }
              }} />
          </label>
          <p style={{ fontSize: 11.5, color: C.muted, margin: "8px 0 0", lineHeight: 1.5 }}>
            Експортуйте маршрут у файл GPX (Komoot: «Експорт туру»; Bergfex: завантаження треку) — точки з паузами підставляться автоматично. Пряме посилання на сторінку Komoot/Bergfex не спрацює: ці сервіси не дозволяють читати маршрут із чужих сайтів.
          </p>
          <div style={{ marginTop: 12 }}>
            <label style={lbl}>Посилання на повний маршрут (Komoot / Bergfex, необов'язково)</label>
            <input style={inp} value={t.routeUrl || ""} onChange={(e) => set({ routeUrl: e.target.value })} placeholder="https://www.komoot.com/tour/..." />
            <div style={{ display: "flex", gap: 8, alignItems: "flex-start", padding: "10px 12px", background: C.greenSoft, borderRadius: 10, fontSize: 12, color: C.greenDark, lineHeight: 1.5 }}>
              <Info size={15} style={{ flexShrink: 0, marginTop: 1 }} />
              <span>Карта маршруту з точками показується прямо в додатку (OpenStreetMap). Якщо є готовий маршрут у Komoot чи Bergfex — вставте посилання, і додасться кнопка «Відкрити повний маршрут».</span>
            </div>
          </div>
        </div>

        {/* Бонусні точки */}
        <div style={card}>
          <h3 style={cardTitle}><MapPin size={15} /> Додаткові місця на карті</h3>
          <p style={{ fontSize: 12, color: C.muted, margin: "0 0 12px", lineHeight: 1.5 }}>
            Місця поруч, які не входять у маршрут: оглядовий майданчик, каплиця, купальня.
            У розділі «Маршрут» вони йдуть окремим списком під основними точками, а при
            натисканні підсвічуються жовтим і показуються на карті жовтою шпилькою.
          </p>
          {bonus.length === 0 && <p style={{ fontSize: 13, color: C.muted, margin: "0 0 12px" }}>Поки немає. Можна не додавати — розділ просто не з'явиться.</p>}
          {(() => {
            const sel = selBonus != null ? bonus[selBonus] : null;
            const la = parseFloat(sel && sel.lat), ln = parseFloat(sel && sel.lng);
            if (!sel || isNaN(la) || isNaN(ln)) return null;
            return (
              <div style={{ marginBottom: 12 }}>
                <MeetingMap lat={la} lng={ln} accent="bonus" />
                <p style={{ fontSize: 11.5, color: C.muted, margin: "6px 0 0" }}>На карті: {sel.name || `Місце ${selBonus + 1}`}</p>
              </div>
            );
          })()}
          {bonus.map((b, i) => (
            <div key={i}
              onClick={() => setSelBonus(selBonus === i ? null : i)}
              style={{ border: `1.5px solid ${selBonus === i ? C.yellow : C.line}`, borderRadius: 12, padding: 12, marginBottom: 10, background: selBonus === i ? C.yellowSoft : "#fff", cursor: "pointer" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                <span style={{ fontSize: 12, fontWeight: 700, color: C.yellowInk }}>Місце {i + 1}{selBonus === i ? " · на карті" : ""}</span>
                <button onClick={(e) => { e.stopPropagation(); delBonus(i); }} style={{ background: "none", border: "none", color: C.rasp, fontSize: 12, fontWeight: 600, cursor: "pointer" }}>Видалити</button>
              </div>
              <input onClick={(e) => e.stopPropagation()} style={{ ...inp, marginBottom: 8 }} value={b.name || ""} onChange={(e) => updBonus(i, { name: e.target.value })} placeholder="Назва (Оглядовий майданчик Wendelstein)" />
              <input onClick={(e) => e.stopPropagation()} style={{ ...inp, marginBottom: 8 }} value={b.note || ""} onChange={(e) => updBonus(i, { note: e.target.value })} placeholder="Опис (20 хв пішки від станції, вхід вільний)" />
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
                <input onClick={(e) => e.stopPropagation()} style={{ ...inp, marginBottom: 0 }} type="number" step="any" value={b.lat ?? ""} onChange={(e) => updBonus(i, { lat: e.target.value === "" ? undefined : parseFloat(e.target.value) })} placeholder="Широта (47.49)" />
                <input onClick={(e) => e.stopPropagation()} style={{ ...inp, marginBottom: 0 }} type="number" step="any" value={b.lng ?? ""} onChange={(e) => updBonus(i, { lng: e.target.value === "" ? undefined : parseFloat(e.target.value) })} placeholder="Довгота (11.10)" />
              </div>
            </div>
          ))}
          <button onClick={addBonus} style={{ width: "100%", border: `1.5px dashed ${C.yellowInk}`, background: C.yellowSoft, color: C.yellowInk, borderRadius: 10, padding: "10px", fontSize: 13, fontWeight: 700, cursor: "pointer" }}>+ Додати додаткове місце</button>
        </div>

        {/* Ручне виправлення перекладів */}
        <div style={card}>
          <button onClick={() => setTrOpen(!trOpen)}
            style={{ width: "100%", display: "flex", alignItems: "center", gap: 8, background: "none", border: "none", padding: 0, cursor: "pointer", fontFamily: "inherit", textAlign: "left" }}>
            <span style={{ color: C.green, flexShrink: 0, transform: trOpen ? "rotate(90deg)" : "none", transition: "transform .15s", display: "flex" }}>
              <ChevronRight size={17} />
            </span>
            <h3 style={{ ...cardTitle, margin: 0 }}>🌐 Переклади</h3>
          </button>
          {trOpen && (() => {
            // Список збирається тим самим обходом, що й автопереклад, тож
            // сюди автоматично потрапляє КОЖНЕ текстове поле поїздки —
            // і ті, які з'являться в застосунку пізніше.
            const manual = t.manualTr || {};
            const show = t.__trShow || {};
            // Однакові тексти в різних полях — один рядок: виправлення
            // застосується скрізь, і вигляд лишиться однаковим.
            const seen = new Set();
            const rows = TRANSLATABLE(t)
              .map((r) => ukOf(r.get()).trim())
              .filter((uk) => uk !== "" && !seen.has(uk) && seen.add(uk));
            const setTr = (uk, value) => {
              const cur = manual[uk] || {};
              set({ manualTr: { ...manual, [uk]: { ...cur, [trLang]: value } } });
            };
            return (
              <>
                <p style={{ fontSize: 12, color: C.muted, margin: "12px 0 12px", lineHeight: 1.5 }}>
                  Автопереклад — машина, і в іменах та рідкісних словах він помиляється:
                  «Bismarcksturm» стає «Штурмом Бисмарка» замість «Башни Бисмарка».
                  Тут можна виправити будь-який рядок вручну. Зверху — ваш український
                  оригінал, знизу — переклад, який побачать учасники. Порожнє поле означає,
                  що переклад підставиться автоматично при збереженні.
                </p>
                <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
                  {[["en", "English"], ["ru", "Русский"]].map(([code, name]) => (
                    <button key={code} onClick={() => setTrLang(code)}
                      style={{ flex: 1, border: `1.5px solid ${trLang === code ? C.green : C.line}`, background: trLang === code ? C.greenSoft : "#fff", color: trLang === code ? C.greenDark : C.muted, borderRadius: 10, padding: "9px 6px", fontSize: 12.5, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>
                      {name}
                    </button>
                  ))}
                </div>
                {rows.length === 0 && <p style={{ fontSize: 13, color: C.muted, margin: 0 }}>Спершу заповніть тексти поїздки.</p>}
                {rows.map((uk) => {
                  const cur = (manual[uk] && manual[uk][trLang]) || "";
                  const auto = (show[uk] && show[uk][trLang]) || "";
                  const long = uk.length > 60;
                  const edited = cur.trim() !== "";
                  return (
                    <div key={uk} style={{ border: `1px solid ${edited ? C.green : C.line}`, borderRadius: 12, padding: 11, marginBottom: 9, background: "#fff" }}>
                      <div style={{ fontSize: 12.5, color: C.muted, lineHeight: 1.45, marginBottom: 7 }}>{uk}</div>
                      {long
                        ? <textarea rows={3} style={{ ...inp, marginBottom: 0, resize: "vertical", lineHeight: 1.45 }} value={cur} onChange={(e) => setTr(uk, e.target.value)} placeholder={auto || "Переклад підставиться автоматично"} />
                        : <input style={{ ...inp, marginBottom: 0 }} value={cur} onChange={(e) => setTr(uk, e.target.value)} placeholder={auto || "Переклад підставиться автоматично"} />}
                      {!edited && auto !== "" && (
                        <div style={{ fontSize: 11, color: C.muted, marginTop: 5 }}>Зараз показується: {auto}</div>
                      )}
                    </div>
                  );
                })}
              </>
            );
          })()}
        </div>

        {/* Contacts editor: multiple people per trip */}
        <div style={card}>
          <h3 style={cardTitle}><MessageCircle size={15} /> Контакти для зв'язку</h3>
          <p style={{ fontSize: 12, color: C.muted, margin: "0 0 12px", lineHeight: 1.5 }}>
            Додайте себе та інших організаторів або гідів цієї поїздки. Кожен контакт відображається окремо.
          </p>
          {(() => {
            const list = (t.contacts && t.contacts.length > 0) ? t.contacts : (t.contact ? [t.contact] : []);
            const updateList = (next) => set({ contacts: next, contact: next[0] || t.contact });
            const updContact = (i, patch) => updateList(list.map((c, j) => j === i ? { ...c, ...patch } : c));
            const delContact = (i) => updateList(list.filter((_, j) => j !== i));
            const addContact = () => updateList([...list, { name: "", role: "", telegram: "", phone: "" }]);
            return (
              <>
                {list.map((person, i) => (
                  <div key={i} style={{ border: `1px solid ${C.line}`, borderRadius: 12, padding: 12, marginBottom: 10, background: "#fff" }}>
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                      <span style={{ fontSize: 12, fontWeight: 700, color: C.green }}>Контакт {i + 1}</span>
                      {list.length > 1 && (
                        <button onClick={() => delContact(i)} style={{ background: "none", border: "none", color: C.rasp, fontSize: 12, fontWeight: 600, cursor: "pointer" }}>Видалити</button>
                      )}
                    </div>
                    <input style={{ ...inp, marginBottom: 8 }} value={person.name || ""} onChange={(e) => updContact(i, { name: e.target.value })} placeholder="Ім'я" />
                    <input style={{ ...inp, marginBottom: 8 }} value={typeof person.role === "string" ? person.role : (person.role?.uk || "")} onChange={(e) => updContact(i, { role: e.target.value })} placeholder="Роль (Організатор, Гід…)" />
                    <input style={{ ...inp, marginBottom: 8 }} value={person.telegram || ""} onChange={(e) => updContact(i, { telegram: e.target.value })} placeholder="Telegram (@…)" />
                    <input style={{ ...inp, marginBottom: 0 }} value={person.phone || ""} onChange={(e) => updContact(i, { phone: e.target.value })} placeholder="Телефон (+49…)" />
                  </div>
                ))}
                <button onClick={addContact} style={{ width: "100%", border: `1.5px dashed ${C.rasp}`, background: C.raspSoft, color: C.rasp, borderRadius: 10, padding: "10px", fontSize: 13, fontWeight: 700, cursor: "pointer" }}>+ Додати контакт</button>
              </>
            );
          })()}
        </div>

        {/* Cafes editor */}
        <div style={card}>
          <h3 style={cardTitle}><Coffee size={15} /> Кафе / їжа</h3>
          <p style={{ fontSize: 12, color: C.muted, margin: "0 0 12px", lineHeight: 1.5 }}>
            Місця, де можна поїсти під час поїздки. Якщо не додати жодного — покажеться «Список уточнюється».
          </p>
          {(() => {
            const list = t.cafes || [];
            const upd = (next) => set({ cafes: next });
            const updItem = (i, patch) => upd(list.map((c, j) => j === i ? { ...c, ...patch } : c));
            const del = (i) => upd(list.filter((_, j) => j !== i));
            const add = () => upd([...list, { name: "", note: "", tag: "" }]);
            return (
              <>
                {list.map((c, i) => (
                  <div key={i} style={{ border: `1px solid ${C.line}`, borderRadius: 12, padding: 12, marginBottom: 10, background: "#fff" }}>
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                      <span style={{ fontSize: 12, fontWeight: 700, color: C.green }}>Місце {i + 1}</span>
                      <button onClick={() => del(i)} style={{ background: "none", border: "none", color: C.rasp, fontSize: 12, fontWeight: 600, cursor: "pointer" }}>Видалити</button>
                    </div>
                    <input style={{ ...inp, marginBottom: 8 }} value={c.name || ""} onChange={(e) => updItem(i, { name: e.target.value })} placeholder="Назва (напр. Gasthof Alpenblick)" />
                    <input style={{ ...inp, marginBottom: 8 }} value={typeof c.note === "string" ? c.note : (c.note?.uk || "")} onChange={(e) => updItem(i, { note: e.target.value })} placeholder="Опис (напр. домашня кухня, є вегетаріанське)" />
                    <input style={{ ...inp, marginBottom: 0 }} value={typeof c.tag === "string" ? c.tag : (c.tag?.uk || "")} onChange={(e) => updItem(i, { tag: e.target.value })} placeholder="Позначка (напр. €€ · біля станції)" />
                  </div>
                ))}
                {list.length === 0 && <p style={{ fontSize: 13, color: C.muted, margin: "0 0 12px" }}>Поки нічого не додано.</p>}
                <button onClick={add} style={{ width: "100%", border: `1.5px dashed ${C.rasp}`, background: C.raspSoft, color: C.rasp, borderRadius: 10, padding: "10px", fontSize: 13, fontWeight: 700, cursor: "pointer" }}>+ Додати місце</button>
              </>
            );
          })()}
        </div>

        {/* Packing list editor */}
        <div style={card}>
          <h3 style={cardTitle}><ClipboardCheck size={15} /> Що взяти з собою</h3>
          <p style={{ fontSize: 12, color: C.muted, margin: "0 0 12px", lineHeight: 1.5 }}>
            Додайте кожну позицію окремим рядком: взуття, одяг, вода, перекус тощо.
          </p>
          {(() => {
            const list = t.packing || [];
            const updList = (next) => set({ packing: next });
            const updItem = (i, val) => updList(list.map((p, j) => j === i ? val : p));
            const delItem = (i) => updList(list.filter((_, j) => j !== i));
            const addItem = () => updList([...list, ""]);
            return (
              <>
                {list.map((item, i) => (
                  <div key={i} style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 8 }}>
                    <input
                      value={typeof item === "string" ? item : (item?.uk || "")}
                      onChange={(e) => updItem(i, e.target.value)}
                      placeholder={`Наприклад: Зручне взуття`}
                      style={{ flex: 1, boxSizing: "border-box", border: `1px solid ${C.line}`, borderRadius: 10, padding: "10px 12px", fontSize: 14, fontFamily: "inherit", background: "#fff", color: C.ink }}
                    />
                    <button onClick={() => delItem(i)} title="Видалити" style={{ background: C.raspSoft, border: "none", color: C.rasp, borderRadius: 9, padding: "9px 12px", fontSize: 13, fontWeight: 700, cursor: "pointer", flexShrink: 0 }}>×</button>
                  </div>
                ))}
                {list.length === 0 && (
                  <p style={{ fontSize: 13, color: C.muted, margin: "0 0 12px" }}>Поки нічого не додано.</p>
                )}
                <button onClick={addItem} style={{ width: "100%", border: `1.5px dashed ${C.green}`, background: C.greenSoft, color: C.greenDark, borderRadius: 10, padding: "10px", fontSize: 13, fontWeight: 700, cursor: "pointer" }}>+ Додати позицію</button>
              </>
            );
          })()}
        </div>
      </div>

      {/* Sticky save bar */}
      {!canSave && (
        <div style={{ position: "fixed", bottom: "calc(68px + env(safe-area-inset-bottom))", left: 0, right: 0, maxWidth: 440, margin: "0 auto", padding: "0 14px", zIndex: 5 }}>
          <div style={{ background: "rgba(0,0,0,0.55)", color: "#fff", borderRadius: 12, padding: "9px 13px", fontSize: 12.5, lineHeight: 1.45 }}>
            Щоб зберегти, заповніть у блоці «Основне»:{" "}
            {ukOf(t.title).trim() === "" ? "«Назва»" : ""}
            {ukOf(t.title).trim() === "" && ukOf(t.dateLabel).trim() === "" ? " і " : ""}
            {ukOf(t.dateLabel).trim() === "" ? "«Дата (текстом)»" : ""}
          </div>
        </div>
      )}
      <div style={{ position: "fixed", bottom: 0, left: 0, right: 0, maxWidth: 440, margin: "0 auto", padding: "14px 14px calc(14px + env(safe-area-inset-bottom))", background: "rgba(80,104,60,0.96)", backdropFilter: "blur(8px)", display: "flex", gap: 10 }}>
        <button onClick={onCancel} style={{ flex: 1, background: "rgba(255,255,255,0.18)", color: "#fff", border: "none", padding: "14px", borderRadius: 14, fontSize: 14.5, fontWeight: 700, cursor: "pointer" }}>Скасувати</button>
        <button onClick={() => {
          if (!canSave) return;
          // Keep legacy from/to fields in sync with the first/last leg so the
          // meeting point (departure time) and journey planner (destination)
          // keep working for multi-leg trips.
          const out = { ...t };
          // Числові поля під час набору зберігаються як текст (щоб можна було
          // повністю стерти значення) — тут приводимо їх до чисел.
          const num = (v, isInt) => { const n = isInt ? parseInt(v) : parseFloat(v); return isNaN(n) ? 0 : n; };
          out.distanceKm = num(out.distanceKm);
          out.ascentM = num(out.ascentM, true);
          out.descentM = num(out.descentM, true);
          out.spots = num(out.spots, true);
          out.spotsTaken = num(out.spotsTaken, true);
          if (out.coords) out.coords = { lat: num(out.coords.lat), lng: num(out.coords.lng) };
          if (out.weather) out.weather = { ...out.weather, tempC: num(out.weather.tempC, true), feelsC: num(out.weather.feelsC, true), rainPct: num(out.weather.rainPct, true), windKmh: num(out.weather.windKmh, true), humidity: num(out.weather.humidity, true) };
          // Маршрути: викидаємо порожні заготовки поїздів і порожні
          // відправлення, щоб у користувача не з'являлись картки з рисками.
          const js = (out.journeys && out.journeys.length > 0
            ? out.journeys
            : (out.legs && out.legs.length > 0 ? [{ legs: out.legs }] : []))
            .map((j) => ({ legs: ((j && j.legs) || []).filter(legFilled) }))
            .filter((j) => j.legs.length > 0);
          out.journeys = js;
          // Порожні заготовки додаткових місць теж викидаємо.
          out.bonus = (out.bonus || []).filter(bonusFilled);
          // Поле legs лишається як перше відправлення — на нього спираються
          // збережені раніше поїздки й похідні поля нижче.
          out.legs = js.length > 0 ? js[0].legs : [];
          if (out.legs.length > 0) {
            const first = out.legs[0], last = out.legs[out.legs.length - 1];
            out.from = { name: first.from, time: first.fromTime, platform: first.platform };
            out.to = { name: last.to, time: last.toTime };
            out.trainLine = out.legs.map((l) => l.train).filter(Boolean).join(" + ");
          }
          onSave(out);
        }} disabled={!canSave} style={{ flex: 2, background: canSave ? C.yellow : "rgba(255,255,255,0.25)", color: canSave ? C.greenDark : "rgba(255,255,255,0.6)", border: "none", padding: "14px", borderRadius: 14, fontSize: 14.5, fontWeight: 800, cursor: canSave ? "pointer" : "default" }}>Зберегти поїздку</button>
      </div>
    </div>
  );
}

// ── Root ───────────────────────────────────────────────────────────────
// Масштабування двома пальцями. Заборона зуму сидить у метатезі viewport
// у index.html; там її теж треба виправити. Але метатег легко проґавити
// під час правок, тому застосунок перезаписує його сам при завантаженні —
// так зум працює навіть зі старим index.html. Мінімальний масштаб лишаємо
// рівним 1, щоб не можна було випадково «здути» сторінку менше за екран.
function enablePinchZoom() {
  if (typeof document === "undefined") return;
  let m = document.querySelector('meta[name="viewport"]');
  if (!m) {
    m = document.createElement("meta");
    m.setAttribute("name", "viewport");
    document.head.appendChild(m);
  }
  m.setAttribute("content", "width=device-width, initial-scale=1, minimum-scale=1, maximum-scale=5, user-scalable=yes, viewport-fit=cover");
}

export default function App() {
  useEffect(() => { enablePinchZoom(); }, []);
  const [trips, setTrips] = useState(() => (sbConfigured() ? [] : TRIPS));
  const [loadingTrips, setLoadingTrips] = useState(() => sbConfigured());
  const [loadError, setLoadError] = useState(false);
  const [tProgress, setTProgress] = useState(null); // null | {done, total}
  // Скільки місць зайнято в кожній поїздці. Тягнемо одним запитом на всі
  // й оновлюємо після кожного нового запису, щоб цифра на картці була
  // справжньою, а не вписаною руками.
  const [counts, setCounts] = useState({});
  const refreshCounts = useCallback(() => {
    if (!sbConfigured()) return;
    sbBookedCounts().then(setCounts).catch(() => {});
  }, []);
  useEffect(() => { refreshCounts(); }, [refreshCounts]);
  const [adminPin, setAdminPin] = useState("");
  // Мова береться з телефона, а не жорстко українська: німець чи поляк
  // побачить англійську, а не текст, якого не читає. Обраний вручну
  // варіант має перевагу й памʼятається між відкриттями.
  const [lang, setLang] = useState(() => {
    try {
      const saved = localStorage.getItem("lang");
      if (saved && LANGS.some((l) => l.code === saved)) return saved;
    } catch {}
    const sys = String((navigator.languages && navigator.languages[0]) || navigator.language || "uk").slice(0, 2).toLowerCase();
    return LANGS.some((l) => l.code === sys) ? sys : (sys === "be" || sys === "kk" ? "ru" : "en");
  });
  useEffect(() => { try { localStorage.setItem("lang", lang); } catch {} }, [lang]);
  // Keep the module-level CURRENT_LANG in sync so t() works everywhere.
  CURRENT_LANG = lang;
  // Сповіщення приходять мовою, збереженою в підписці. Якщо людина
  // перемкнула мову вже після того, як увімкнула сповіщення, підписку
  // треба переписати — інакше пуші й далі йшли б старою мовою.
  useEffect(() => {
    if (!pushSupported() || !sbConfigured()) return;
    navigator.serviceWorker.ready
      .then((reg) => reg.pushManager.getSubscription())
      .then((sub) => {
        if (!sub) return;
        const j = sub.toJSON();
        return sbRpc("push_subscribe", {
          p_endpoint: j.endpoint, p_p256dh: j.keys.p256dh, p_auth: j.keys.auth, p_lang: lang,
        });
      })
      .catch(() => {});
  }, [lang]);

  // Завантаження поїздок із Supabase (якщо підключено). Якщо база
  // недоступна — тихо відкочуємось на демо-дані, щоб сайт ніколи не падав.
  const reloadTrips = () => {
    if (!sbConfigured()) return;
    setLoadingTrips(true);
    setLoadError(false);
    sbLoadTrips()
      .then((rows) => { setTrips(rows); setLoadingTrips(false); })
      .catch(() => { setLoadingTrips(false); setLoadError(true); });
  };
  useEffect(() => {
    // ВАЖЛИВО: на невдалому читанні НЕ відкочуємось на демо-дані з коду —
    // інакше старі поїздки виглядають так, ніби «повернулись» після
    // видалення, хоча насправді це просто не оновився список. Замість
    // цього показуємо явну помилку з кнопкою «Спробувати ще раз».
    if (!sbConfigured()) return;
    let cancelled = false;
    sbLoadTrips()
      .then((rows) => { if (!cancelled) { setTrips(rows); setLoadingTrips(false); } })
      .catch(() => { if (!cancelled) { setLoadingTrips(false); setLoadError(true); } });
    return () => { cancelled = true; };
  }, []);
  const [selected, setSelected] = useState(null);
  const [isAdmin, setIsAdmin] = useState(false);
  const [editing, setEditing] = useState(null); // trip object being edited, or "new"
  const [pinOpen, setPinOpen] = useState(false);
  const [pin, setPin] = useState("");
  const [pinVisible, setPinVisible] = useState(false);
  // PIN організатора — 10 знаків: A 7 3 9 1 . 1 3 0 5
  // ⚠️ Той самий PIN мусить стояти у ДВОХ функціях Supabase
  // (save_trip і delete_trip) — інакше збереження мовчки перестане
  // працювати, хоча вхід у режим організатора буде проходити.
  // PIN у коді більше НЕМАЄ. Код застосунку завантажується на телефон
  // кожного відвідувача повністю — усе, що в ньому написано, видно всім.
  // Тому введене надсилається в базу, і база відповідає «так» або «ні».
  // У коді лишається запитання, а не відповідь.
  const [pinBusy, setPinBusy] = useState(false);
  const [pinErr, setPinErr] = useState("");
  const tryPin = async (value) => {
    if (String(value).trim() === "") return;
    setPinBusy(true); setPinErr("");
    try {
      const ok = await sbRpc("check_pin", { pin: value });
      if (ok === true) {
        setIsAdmin(true); setAdminPin(value); setPinOpen(false); setPin("");
        sbMarkAdminDevice(value).catch(() => {});
      }
      else { setPin(""); setPinErr(t("pinWrong")); }
    } catch (e) {
      setPinErr(t("pinFailed"));
    } finally { setPinBusy(false); }
  };

  // Group trips by their status group. "done"/"cancelled" → Минулі; the rest
  // (upcoming, recruiting, ongoing, postponed) → Найближчі. At the start of a
  // new month there are simply no past trips yet, so everything naturally
  // shows under Найближчі — matching the one-month planning cycle.
  // Порядок за датою, а не за порядком у базі. Майбутні — від найближчої
  // до найдальшої, минулі — навпаки, свіжі зверху. Поїздка без дати йде
  // в кінець свого списку: сховати її було б гірше, ніж показати останньою.
  const dateKey = (x) => {
    const d = new Date(String(x && x.date ? x.date : "") + "T00:00:00");
    return isNaN(d.getTime()) ? null : d.getTime();
  };
  const byDate = (dir) => (a, b) => {
    const ka = dateKey(a), kb = dateKey(b);
    if (ka == null && kb == null) return 0;
    if (ka == null) return 1;
    if (kb == null) return -1;
    return dir * (ka - kb);
  };
  const upcomingAll = trips.filter((t) => (STATUS[t.status]?.group || "upcoming") === "upcoming").sort(byDate(1));
  const past = trips.filter((t) => (STATUS[t.status]?.group || "upcoming") === "past").sort(byDate(-1));
  // «Найближчі» — те, що вже за два тижні або раніше. Решта майбутніх
  // поїздок іде окремим списком нижче: так одразу видно, куди йдемо цими
  // вихідними, а далекі плани не змішуються з найближчими. Поїздка без
  // проставленої дати лишається серед найближчих — краще показати зайве,
  // ніж заховати.
  const SOON_DAYS = 14;
  const daysUntil = (iso) => {
    if (!iso) return null;
    const d = new Date(String(iso) + "T00:00:00");
    if (isNaN(d.getTime())) return null;
    const n = new Date();
    return Math.round((d - new Date(n.getFullYear(), n.getMonth(), n.getDate())) / 86400000);
  };
  const upcoming = upcomingAll.filter((x) => { const n = daysUntil(x.date); return n == null || n <= SOON_DAYS; });
  const later = upcomingAll.filter((x) => { const n = daysUntil(x.date); return n != null && n > SOON_DAYS; });
  const trip = trips.find((t) => t.id === selected);

  // Зберігає поїздку в Supabase (якщо підключено).
  const persistTrip = async (t1) => {
    if (!sbConfigured()) return;
    try { await sbSaveTrip(t1, adminPin); }
    catch (e) { alert("Не вдалося зберегти в базі даних.\n" + (e && e.message ? e.message : e)); }
  };
  const saveTrip = (edited) => {
    // У пам'ять кладемо без службового списку ручних правок — він потрібен
    // лише всередині редактора й не повинен ані показуватись, ані зберігатись.
    const shown = { ...edited }; delete shown.__tr; delete shown.__trShow;
    setTrips((prev) => {
      const exists = prev.some((t) => t.id === shown.id);
      return exists ? prev.map((t) => (t.id === shown.id ? shown : t)) : [...prev, shown];
    });
    setEditing(null);
    // У фоні: автопереклад вмісту (DeepL) і збереження в базу.
    (async () => {
      let final = edited;
      try {
        final = await translateTripContent(edited);
        setTrips((prev) => prev.map((t) => (t.id === final.id ? final : t)));
      } catch (e) {
        // Переклад вимкнено або недоступний — лишаємо український текст.
        // Службовий список ручних правок у базу не пишемо в жодному разі.
        final = { ...edited }; delete final.__tr; delete final.__trShow;
      }
      await persistTrip(final);
    })();
  };
  const deleteTrip = (id) => {
    setTrips((prev) => prev.filter((t) => t.id !== id));
    setSelected(null);
    if (sbConfigured()) sbDeleteTrip(id, adminPin).catch((e) => alert("Не вдалося видалити з бази.\n" + e.message));
  };
  const setStatus = (id, status) => {
    const t0 = trips.find((t) => t.id === id);
    setTrips((prev) => prev.map((t) => t.id === id ? { ...t, status } : t));
    if (t0) persistTrip({ ...t0, status });
  };
  const setPostponedDate = (id, date) => {
    const t0 = trips.find((t) => t.id === id);
    setTrips((prev) => prev.map((t) => t.id === id ? { ...t, postponedTo: date } : t));
    if (t0) persistTrip({ ...t0, postponedTo: date });
  };
  // Разове наповнення порожньої бази демо-поїздками (кнопка для організатора).
  const seedDemo = async () => {
    setTrips(TRIPS);
    for (const t0 of TRIPS) {
      let f = t0;
      try { f = await translateTripContent(t0); setTrips((prev) => prev.map((x) => (x.id === f.id ? f : x))); } catch {}
      await persistTrip(f);
    }
  };
  // Разовий переклад ВЖЕ збережених поїздок (для тих, що потрапили в базу
  // до підключення DeepL). Кнопка в режимі організатора.
  const translateAll = async () => {
    if (!window.confirm("Перекласти вміст усіх поїздок на англійську й російську?\n\nЦе займе до хвилини та перезапише наявні переклади.")) return;
    const total = trips.length;
    let ok = 0, failed = 0;
    setTProgress({ done: 0, total });
    for (let i = 0; i < trips.length; i++) {
      try {
        const f = await translateTripContent(toEditable(trips[i]));
        if (f.__translated > 0) ok++; else failed++;
        delete f.__translated;
        setTrips((prev) => prev.map((x) => (x.id === f.id ? f : x)));
        await persistTrip(f);
      } catch { failed++; }
      setTProgress({ done: i + 1, total });
    }
    setTProgress(null);
    if (failed === 0) alert(`Готово — перекладено поїздок: ${ok}.\n\nПеремкніть мову на EN або RU, щоб перевірити.`);
    else if (ok > 0) alert(`Перекладено: ${ok} з ${total}.\n\nЧастина не вдалася — можливо, тимчасово недоступний сервіс перекладу. Спробуйте натиснути ще раз через кілька хвилин.`);
    else alert("Не вдалося перекласти жодної поїздки.\n\nПеревірте інтернет-зʼєднання і спробуйте ще раз.");
  };

  // Екран завантаження при відкритті (лише первинне, поки тягнемо базу).
  if (loadingTrips) return <SplashScreen />;

  // ---- Editing form view ----
  if (editing) {
    return (
      <div style={{ minHeight: "100vh", background: C.page, fontFamily: "'Inter', system-ui, sans-serif", color: C.ink }}>
        <div style={{ maxWidth: 440, margin: "0 auto", background: C.page, minHeight: "100vh", position: "relative" }}>
          <TripForm
            initial={editing === "new" ? BLANK_TRIP() : editing}
            onSave={saveTrip}
            onCancel={() => setEditing(null)}
          />
        </div>
      </div>
    );
  }

  return (
    <div style={{ minHeight: "100vh", background: C.page, fontFamily: "'Inter', system-ui, sans-serif", color: C.ink }}>
      <div style={{ maxWidth: 440, margin: "0 auto", background: C.page, minHeight: "100vh", position: "relative", overflow: "hidden" }}>
        <div style={{ position: "relative", zIndex: 1 }}>
        {trip ? (
          <TripDetail
            trip={trip}
            onBack={() => setSelected(null)}
            isAdmin={isAdmin}
            onEdit={() => setEditing(toEditable(trip))}
            onDelete={() => deleteTrip(trip.id)}
            onSetStatus={(s) => setStatus(trip.id, s)}
            onSetPostponedDate={(d) => setPostponedDate(trip.id, d)}
            counts={counts}
            onBooked={refreshCounts}
            adminPin={adminPin}
          />
        ) : (
          <div style={{ padding: "0 16px 30px" }}>
            <div style={{ padding: "calc(26px + env(safe-area-inset-top)) 4px 20px", display: "flex", alignItems: "center", gap: 12 }}>
              <img src={LOGO} alt={t("appName")} style={{ width: 60, height: 60, borderRadius: 14, display: "block", objectFit: "cover", border: "1.5px solid rgba(253,228,70,0.45)", boxShadow: "0 3px 10px rgba(0,0,0,0.18)" }} />
              <div style={{ flex: 1 }}>
                <h1 style={{ margin: 0, fontSize: 21, fontWeight: 800, letterSpacing: -0.4, color: "#fff" }}>{t("appName")}</h1>
                <p style={{ margin: 0, fontSize: 13, color: "rgba(255,255,255,0.75)" }}>{t("appSubtitle")}</p>
              </div>
              {isAdmin && (
                <span style={{ fontSize: 10, fontWeight: 800, color: C.greenDark, background: C.yellow, padding: "4px 9px", borderRadius: 20, textTransform: "uppercase", letterSpacing: 0.5 }}>{t("organizer")} · {APP_VERSION}</span>
              )}
            </div>

            {/* Language switcher */}
            <div style={{ display: "flex", gap: 6, marginBottom: 18, justifyContent: "center" }}>
              {LANGS.map((l) => (
                <button key={l.code} onClick={() => setLang(l.code)} style={{
                  display: "flex", alignItems: "center", justifyContent: "center", padding: "7px 16px", borderRadius: 20,
                  border: lang === l.code ? `1.5px solid ${C.yellow}` : "1.5px solid rgba(255,255,255,0.25)",
                  background: lang === l.code ? "rgba(253,228,70,0.18)" : "rgba(255,255,255,0.06)",
                  color: lang === l.code ? "#fff" : "rgba(255,255,255,0.7)",
                  fontSize: 13, fontWeight: lang === l.code ? 700 : 500, cursor: "pointer", letterSpacing: 0.5,
                }}>
                  {l.display}
                </button>
              ))}
            </div>

            {/* Admin: add button */}
            {isAdmin && (
              <button onClick={() => setEditing("new")} style={{ width: "100%", background: C.yellow, color: C.greenDark, border: "none", padding: "14px", borderRadius: 14, fontSize: 14.5, fontWeight: 800, cursor: "pointer", marginBottom: 18, display: "flex", alignItems: "center", justifyContent: "center", gap: 8, boxShadow: "0 3px 12px rgba(0,0,0,0.15)" }}>
                <span style={{ fontSize: 19 }}>＋</span> {t("addTrip")}
              </button>
            )}
            {isAdmin && trips.length > 0 && (
              <button onClick={translateAll} disabled={!!tProgress} style={{ width: "100%", display: "flex", alignItems: "center", justifyContent: "center", gap: 8, background: "rgba(255,255,255,0.10)", color: "#fff", border: "1.5px dashed rgba(255,255,255,0.45)", padding: "11px", borderRadius: 12, fontSize: 12.5, fontWeight: 700, cursor: tProgress ? "default" : "pointer", marginBottom: 14, opacity: tProgress ? 0.7 : 1 }}>
                🌐 {tProgress ? `Перекладаю… ${tProgress.done}/${tProgress.total}` : t("translateAllBtn")}
              </button>
            )}

            <div style={{ display: "flex", alignItems: "center", gap: 8, margin: "6px 4px 14px" }}>
              <Calendar size={16} color={C.yellow} />
              <h2 style={{ margin: 0, fontSize: 13, fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.8, color: C.yellow }}>{t("upcomingTrips")}</h2>
            </div>
            {loadingTrips && <p style={{ fontSize: 13, color: "rgba(255,255,255,0.6)", margin: "0 4px 14px" }}>{t("loading")}</p>}
            {!loadingTrips && loadError && (
              <div style={{ background: "rgba(0,0,0,0.22)", borderRadius: 12, padding: "12px 14px", margin: "0 4px 14px" }}>
                <p style={{ fontSize: 13, color: "rgba(255,255,255,0.85)", margin: "0 0 10px", lineHeight: 1.5 }}>{t("loadErrorMsg")}</p>
                <button onClick={reloadTrips} style={{ background: "rgba(255,255,255,0.15)", color: "#fff", border: "1.5px solid rgba(255,255,255,0.4)", borderRadius: 10, padding: "9px 16px", fontSize: 12.5, fontWeight: 700, cursor: "pointer" }}>{t("retry")}</button>
              </div>
            )}
            {!loadingTrips && !loadError && upcoming.length === 0 && <p style={{ fontSize: 13, color: "rgba(255,255,255,0.6)", margin: "0 4px 14px" }}>{t("noUpcoming")}</p>}
            {!loadingTrips && !loadError && sbConfigured() && trips.length === 0 && isAdmin && (
              <button onClick={seedDemo} style={{ width: "100%", background: "rgba(255,255,255,0.12)", color: "#fff", border: "1.5px dashed rgba(255,255,255,0.5)", padding: "12px", borderRadius: 12, fontSize: 13, fontWeight: 700, cursor: "pointer", marginBottom: 14 }}>
                Завантажити демо-поїздки в базу
              </button>
            )}
            {upcoming.map((t) => (
              <TripCard key={t.id} trip={t} counts={counts} onClick={() => setSelected(t.id)} isAdmin={isAdmin} onSetStatus={(s) => setStatus(t.id, s)} onSetPostponedDate={(d) => setPostponedDate(t.id, d)} onEdit={() => setEditing(toEditable(t))} />
            ))}

            {later.length > 0 && (
              <div style={{ display: "flex", alignItems: "center", gap: 8, margin: "24px 4px 14px" }}>
                <Calendar size={16} color={C.yellow} />
                <h2 style={{ margin: 0, fontSize: 13, fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.8, color: C.yellow }}>{t("futureTrips")}</h2>
              </div>
            )}
            {later.map((t) => (
              <TripCard key={t.id} trip={t} counts={counts} onClick={() => setSelected(t.id)} isAdmin={isAdmin} onSetStatus={(s) => setStatus(t.id, s)} onSetPostponedDate={(d) => setPostponedDate(t.id, d)} onEdit={() => setEditing(toEditable(t))} />
            ))}

            {past.length > 0 && (
              <div style={{ display: "flex", alignItems: "center", gap: 8, margin: "24px 4px 14px" }}>
                <Clock size={16} color="rgba(255,255,255,0.55)" />
                <h2 style={{ margin: 0, fontSize: 13, fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.8, color: "rgba(255,255,255,0.6)" }}>{t("pastTrips")}</h2>
              </div>
            )}
            {past.map((t) => (
              <TripCard key={t.id} trip={t} counts={counts} onClick={() => setSelected(t.id)} isAdmin={isAdmin} onSetStatus={(s) => setStatus(t.id, s)} onSetPostponedDate={(d) => setPostponedDate(t.id, d)} onEdit={() => setEditing(toEditable(t))} />
            ))}

            <PushToggle />

            {/* Архів на Google Диску. Стоїть під списками, а не над ними:
                головне на цьому екрані — найближчі поїздки, а архів
                потрібен рідше й не має відтягувати увагу. */}
            <a href={DRIVE_URL} target="_blank" rel="noreferrer"
              style={{ display: "flex", alignItems: "center", gap: 11, margin: "34px 30px 0", background: "transparent", border: "1px solid rgba(253,228,70,0.6)", borderRadius: 14, padding: "11px 13px", textDecoration: "none" }}>
              <span style={{ width: 30, height: 30, borderRadius: 9, background: "rgba(255,255,255,0.12)", color: "rgba(255,255,255,0.85)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                <Camera size={15} />
              </span>
              <span style={{ flex: 1, minWidth: 0 }}>
                <span style={{ display: "block", fontSize: 13, fontWeight: 700, color: "rgba(255,255,255,0.9)" }}>{t("secDrive")}</span>
                <span style={{ display: "block", fontSize: 11, color: "rgba(255,255,255,0.5)", marginTop: 1, lineHeight: 1.35 }}>{t("driveHomeNote")}</span>
              </span>
              <ChevronRight size={16} style={{ color: "rgba(255,255,255,0.45)", flexShrink: 0 }} />
            </a>

            {/* Footer + organizer gear */}
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", marginTop: 26, gap: 14 }}>
              {null}
              {isAdmin ? (
                <button onClick={() => setIsAdmin(false)} style={{ background: "none", border: "1px solid rgba(255,255,255,0.3)", color: "rgba(255,255,255,0.7)", borderRadius: 20, padding: "7px 14px", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>
                  {t("exitOrganizer")}
                </button>
              ) : (
                <button onClick={() => { setPinOpen(true); setPin(""); }} aria-label="Режим організатора" style={{ background: "none", border: "none", color: "rgba(255,255,255,0.35)", cursor: "pointer", padding: 6, display: "flex", alignItems: "center", gap: 5, fontSize: 12 }}>
                  <Settings size={15} /> {t("forOrganizer")}
                </button>
              )}
            </div>
          </div>
        )}
        </div>

        {/* PIN modal */}
        {pinOpen && (
          <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.5)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 50, padding: 24 }} onClick={() => setPinOpen(false)}>
            <div onClick={(e) => e.stopPropagation()} style={{ background: C.card, borderRadius: 18, padding: 22, width: "100%", maxWidth: 320, boxShadow: "0 10px 40px rgba(0,0,0,0.3)" }}>
              <h3 style={{ margin: "0 0 6px", fontSize: 17, fontWeight: 800, color: C.ink }}>{t("pinTitle")}</h3>
              <p style={{ margin: "0 0 16px", fontSize: 13, color: C.muted }}>{t("pinDesc")}</p>
              {/* Клавіатура літер і символів. Раніше стояло
                  inputMode="numeric" — телефон показував лише цифрову
                  панель, і ввести літеру чи крапку було просто нічим. */}
              <div style={{ position: "relative", marginBottom: 14 }}>
                <input
                  autoFocus type={pinVisible ? "text" : "password"} inputMode="text"
                  autoCapitalize="off" autoCorrect="off" spellCheck={false}
                  value={pin}
                  onChange={(e) => { setPin(e.target.value); setPinErr(""); }}
                  onKeyDown={(e) => { if (e.key === "Enter") tryPin(pin); }}
                  placeholder="••••••••"
                  style={{ width: "100%", boxSizing: "border-box", border: `1px solid ${C.line}`, borderRadius: 10, padding: "12px 44px 12px 12px", fontSize: 18, textAlign: "center", letterSpacing: 2, fontFamily: "inherit" }}
                />
                {/* Показати введене. Для PIN із літер і символів це не
                    примха: одну помилку в одинадцяти знаках наосліп
                    знайти неможливо. */}
                <button type="button" onClick={() => setPinVisible((v) => !v)}
                  aria-label={pinVisible ? "Сховати" : "Показати"}
                  style={{ position: "absolute", right: 6, top: "50%", transform: "translateY(-50%)", background: "none", border: "none", cursor: "pointer", color: C.muted, fontSize: 11, fontWeight: 700, padding: "8px 10px", fontFamily: "inherit" }}>
                  {pinVisible ? "СХОВАТИ" : "ПОКАЗАТИ"}
                </button>
              </div>
              {/* Помилка входу тепер видима. Раніше поле просто мовчки
                  очищалось, і було незрозуміло, чи PIN невірний, чи
                  застосунок не достукався до бази. */}
              {pinErr !== "" && (
                <p style={{ fontSize: 12.5, color: C.rasp, margin: "0 0 12px", textAlign: "center", lineHeight: 1.45 }}>{pinErr}</p>
              )}
              <div style={{ display: "flex", gap: 10 }}>
                <button onClick={() => setPinOpen(false)} style={{ flex: 1, background: "#fff", border: `1px solid ${C.line}`, color: C.muted, borderRadius: 10, padding: "11px", fontSize: 14, fontWeight: 700, cursor: "pointer" }}>{t("cancel")}</button>
                <button onClick={() => tryPin(pin)} disabled={pinBusy} style={{ flex: 1, background: pinBusy ? C.pageSoft : C.green, border: "none", color: "#fff", borderRadius: 10, padding: "11px", fontSize: 14, fontWeight: 700, cursor: pinBusy ? "default" : "pointer" }}>{pinBusy ? "…" : t("enter")}</button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
